var JINGWEN = window.JINGWEN || (window.JINGWEN = {});
JINGWEN['s45'] = {"id": "s45", "title": "金丹大要", "subtitle": "陈致虚", "note": "底本：正統道藏·涵芬樓版（正統道藏，三家本，1988，24—1 十六卷 太玄部），經 Kanseki Repository（Kanripo）KR5d0090 轉錄｜機器標點 · 未經校訂", "sections": [{"h": "序", "paras": [{"t": "上陽子金丹大要序。睦一伊川先生云：天下有大難事者三：一曰爲國而至於祈天永命，二曰爲學而至於聖人，三曰修身而至於神仙。斯確論也。", "py": []}, {"t": "天琮幼始知學，長而從玄，慨然信長生之道可學而致，乃希高志，叅玄訪微，刮垢磨光，斂華就實，擬向孤峯絶頂，把茅蓋頭，侣洪崖，友赤松，抱雞子之中黄，養蟾光之明素，庶幾萬一克償素願也。", "py": []}, {"t": "豈謂天不愛道，善啓其衷。乙亥夏五，際遇我師紫霄絳宫上陽真人於方壺天中，解襟傾蓋，歡如平生，瀹茗焚香，共談丹道。機緘微露，針芥相投。時以去就匆匆，莫究衷藴。既而瞻候紫氣，追隨黄鶴，至交泰别館，叩首上請，懇款再三，然後歃丹盟天，披青誓地，衆真監度，盡授所祕。", "py": []}, {"t": "初則迅雷貫耳，驚駭異常；次則瘴霧中心，昧惑尤甚。乃至竟夕不寐，繼日弗寧，既未敢誚其非，亦未肯信其是，反覆紬繹，周悉搜羅。感神明之告人，忽心靈而自悟，於是掀翻迷網，打破疑團，比沈痾之頓甦，猶大夣之驚意，通身是汗，瞽目開明。", "py": []}, {"t": "遂將生平記誦丹經，如《叅同契》、《悟真篇》等書，叅訂而印證之，則言言句句，若合符節，千變萬化，緫歸一貫。而今而後，宇宙在乎手，造化備吾身，可以大休歇，可以大自在。覩玄珠之有象，鍊金液以成丹，白日登晨，清都進秩，皆分内事也。", "py": []}, {"t": "回視半生學問，猶管窺天、蠡測海，其大小淺深，固已懸絶；亦猶炊沙作飯，攪水爲膏，欲求充飢、繼明，不可得也。", "py": []}, {"t": "吁，金丹之學，近代自紫清白真人返珮帝鄉，世無真師，傳多失實。談性者，非流於狂蕩，則滯於空寂；論命者，非執於有作，則失於無爲。根器高而利者，不遇師傳，惟祗求之方册，自證自是，自滿自足，自謂一聞百會，眼空四海，已與鍾、吕並駕，寧肯謙抑而師問哉？", "py": []}, {"t": "根器劣而鈍者，求之盲師，一知半見，自喜自幸，自執自守，自謂休心歇妄，枯坐無爲，即道在其中矣，奚暇多事而更叩人哉？是非海闊，人我山高，毒藥入心，黥墨透骨，世無拔山竭海之力，又無補黥去毒之方，莫之能救，可勝歎哉。", "py": []}, {"t": "我師上陽真人，駕拯溺之慈航，仗斬邪之慧劎，紹隆丹陽正傳之脉，發泄青城至祕之文，明前代所未明，說古人所未說，推赤心於人腹，垂青眼於學徒。所著《金丹大要》十卷，條理敷暢，斗拱星羅，詞意昭明，金聲玉振，體堂堂說透骨髓，血滴滴吐出肺肝，恨不與法界衆生盡皆作大羅眷屬，其慈仁忠厚，盛德之至，乃如此。", "py": []}, {"t": "僕懼學徒不察真師之用心，將聖諦玄章作泛常看過，非徒無益而生惑，或乃興謗而自弃，因述己所遇而爲之序，貴以拯拔沉迷，剖鑿聾瞽，庶幾摽指見月，發瓿知天，是亦一助也。", "py": []}, {"t": "金丹之妙，在乎三大要：一曰鼎器，二曰藥物，三曰火候。然鼎器有隂陽，藥物有内外，火候有時節，三者實爲金丹之樞要。知此，則到家有期，可罷問程矣。", "py": []}, {"t": "所冀頭頭會合，口口叅同，慨興進道之心，高中選仙之舉。千年鐵柱，久締龍沙之盟；萬朵玉蓮，嘉慶天元之會。凡我同志，各宜勉旃。門弟子明素蟾天琮序。", "py": []}, {"t": "老易洩天機，古文《龍虎經》、《叅同契》作，以無爲物祖，有爲丹母，乾坤鑪鼎，坎離升降，闢鴻濛，鑿混沌，採藥物，明火符，無非法天地隂陽造化生生之功，有順逆而鍊成金丹也。", "py": []}, {"t": "紫陽《悟眞篇》繼出，發揮玄理，殆無餘藴矣。唯火候之祕，妙存口訣，世之學者往往趨於旁蹊，出於臆度，未能聞其大要，況通其微妙乎？", "py": []}, {"t": "紫霄絳宫上陽先生，繼眞師之絶響，指後學之迷津，千載一時，百年幾見。推明老易深造之道，紬啓仙聖未發之言，謂天人爲物靈，具足此理，知而行之，頓超生死。真心化導，矢口成辭，演爲《金丹大要》十卷，諄諭反復，羅縷再三，誠欲與有志者原始要終，心靈自悟，一得永得，同躋仙阼，其慈憫之心亦溥矣。", "py": []}, {"t": "茗漕冰田王公，吏隱仙材，夙深丹契，知音有遇，思廣其傳。山中主席太初提點、道林隆揀、靜宇深淵，躭味重玄，首唱繡梓。當時及門，皆鳳逸龍蟠，蟬蛻穎脫，列具序說，想見聲光。", "py": []}, {"t": "區區寄跡紫元，留心玄覽，種縁已熟，獲聆緒餘。所謂月現庚方，西南得朋，金歸性初，杳冥有信，依時採取，三性會融，赤水玄珠，得之罔象。當斯之時，至願畢矣。", "py": []}, {"t": "夫窮理盡性以至于命，長生乆視而命在我，《大要》之作，其老易之津涉乎？噫，將外老易而求之，奚言道？至元改元，旃蒙大淵獻，歲除月，門弟子廬山紫元歐陽天璹拜手序。", "py": []}]}, {"h": "虛無卷之一", "paras": [{"t": "上陽子金丹大要虛無卷之一。紫霄絳宫上陽子觀吾陳致虚撰。上陽子曰：金丹之道，黄帝修之而登雲天，老君修之，是爲道祖。巢、由高蹈，籛鏗長年。爾來迄今，歷數何限？求於冊者，當以《隂符》、《道德》爲祖，《金碧》、《叅同》次之。", "py": []}, {"t": "自河上公五傳而至伯陽真人，祖天師得伯陽之㫖，丹成道備，降魔流教；仙翁濟幽，旌陽斬蛟，是皆逢時匡世、救劫，斯乃真仙之餘事耳。", "py": []}, {"t": "華陽、玄甫、雲房、洞賔授受以來，深山妙窟，代不乏人。其間道成而隱、但爲身謀、不肯遺名於世間者，豈勝道哉？復有傳世存道、序傳詩歌，或隱或顯，寧具知乎？至於功高德重、尊居帝境、宰制劫運者，又難備知。", "py": []}, {"t": "燕相海蟾受於純陽而得，紫陽以傳杏林，紫賢、泥丸、海瓊接踵者多。我重陽翁受於純陽而得，丹陽全真教立，長春、長真、長生、玉陽、廣寧、清靜諸老仙輩，枝分縷濟，丹經妙訣，散滿人間。唯紫陽《悟眞篇》頗詳，又得無名子諸公引而明之。", "py": []}, {"t": "我黄房公得於丹陽，乃授太虚以傳紫瓊；我縁督子得於紫瓊，詳見《太虚真人傳》。縁督子間氣聦明，博物精通，挹盡群書，或註或釋，總三教爲一家，作《仙佛同源》、《金丹難問》等書，到此而丹經大備。", "py": []}, {"t": "其意憫憐修道之人，率多旁門，以僞亂眞，故於卷中指出先天一氣，獨是謂若水銀、朱砂、黑汞、白金、火候抽添、安爐立鼎，名之則是，用之則非。", "py": []}, {"t": "《隂符經》云：天性，人也；人心，機也。又云：天地，萬物之盜；萬物，人之盜；人，萬物之盜。又云：人知其神而神，不知不神而所以神也。《道德經》云：有無、妙竅、玄牝、神器，至有上善若水、不敢爲天下先者，皆至言也。", "py": []}, {"t": "又如列子御風、莊周鵬運，雖皆寓言，却有深義。《金碧經》、《叅同契》分明指出金汞、火候、弦氣、爻符，借易爲準，其妙在於欲作服食仙，宜以同類者，取象於月，以驗採鉛。後之所述，無以易此。仙聖用心，普接未來，惟只先天眞一之氣而已。", "py": []}, {"t": "致虚夙荷祖宗積善，天地卑矜，游浪人間，年且四十，伏蒙我師授以正道。厥後復遇青城老師，親傳先天一氣、坎月離日金丹之㫖，抽添運用、火候之祕，悉授無隱。", "py": []}, {"t": "粤從敬受以來，日夕兢惶，恐辜盟誓，且負所望，儘將從前淺聞陋學、煩惱業識，盡皆脫去，長爲天地間一箇閑人也。而爲囊中丹材罔措，兩稔于兹，訪侣求朋，將集吾事，乃不敢祕，焚香告天，啓白聖師、七眞、五祖，遂乃引諸列仙丹經，作此《金丹大要》。其中冒禁詳述，開顯條說，直與後來學仙之士闢門引路，上士至人或於此中得而解悟，同步逍遥，即滿素志。", "py": []}, {"t": "重惟世有先後，人有賢愚，文愈出而道愈明，世愈降而人愈昧，乃以神仙之說而爲渺茫，或謂仙佛天之所生，非人可學，流而至此，復柰之何？老子曰：吾非聖人，學而得之。中下之流，口欲修行而不用心於此，究竟甘分輪迴，可深惜哉。", "py": []}, {"t": "所幸邇來抱材負器之士，叅問尋廣，較之古先，比兹稍衆。雖無旌陽拔宅之舉，安知地仙八百讖數將期？儻有識者，應期立志，疾早求師，成道必矣。", "py": []}, {"t": "世有千蹊百徑，專則所趨必至，好正則君子喜，務誕則邪怪憑。勤織無寒，力耕常飽，學弓能射，習水能游，堅固修行，必成仙佛。今夫百工而不求師，藝豈自精？一經而不求師，科豈必中？專心積善而學仙，亦必有真仙至矣。", "py": []}, {"t": "老子曰：諦觀此身，從虚無中因縁運會，和合受生。我師數指先天一氣，自虚無中來。致虚續曰：既自虚無中來，却非天之所降、地之所出，又非我身所有，亦非精，亦非血，非草木，非金石，是皆非也，誰得而知之乎？", "py": []}, {"t": "《易》曰：西南得朋，乃與類行。又云：君子以虚受人。佛謂西方蓮華世界，馬祖云西江水，《悟真篇》云：藥在西南，是本郷。又云：蟾光終日照西川。又云：鉛遇癸生，須急採。又云：取將坎位心中寳，點化離宫腹内隂。《太一真人破迷歌》云：如何却是道？太乙含真氣。太一豈非西乎？西南者，金火所在也；坎癸者，水鉛所居也。黑鉛是先天一炁，而隱于北方水也，然本無方位，故云自虚無中來也。", "py": []}, {"t": "《叅同契》云：真人潜深淵，浮游守規中。領悟於此，何憂不仙？曰隂陽，曰夫婦，曰男女，曰鉛汞，曰龍虎，曰鼎爐，許多名色，無非先天一氣，狀如細雨宻霧，亦如明窗塵，亦如黍米珠。其道易知，其事易成，初無難也。故我師云：形神無爲，而精氣自然有所爲，是猶天地無爲，而萬物自然化育也。", "py": []}, {"t": "修道的人，果得真師口訣，則恐光隂迅速，目下收料，汲汲成就我身，又何暇奔功名富貴，而共人閑論哉？蓋非得真訣者，於丹經内默猜暗想，無一可成，只得旁引曲證，闊論高談，以度歲月，復何怪焉？", "py": []}, {"t": "且無知者妄造丹書，假借先聖爲名，如葛仙翁《保生養命丹訣》、達磨《胎息經論》、趙州《十二時歌》、龐公《河車頌》，以至八段錦、六字氣之類，其他文目更多，切不可信。", "py": []}, {"t": "要當以《叅同契》、《悟真篇》爲主。然未遇聖師面傳，那有自悟？黄帝師廣成子，老子師商容，孔子師老子，釋迦師瞿曇，聖人皆拜真師，後世凡流却要自悟，何其誑妄？唯有俊流，得師一指，閑處下工，無人知覺，一旦道成，顯其神通，以爲頓悟，此則有之。", "py": []}, {"t": "夫金丹一事，其中奥㫖，不啻一件。只如藥物、鼎器、玄牝、隂陽、太易、子癸、復震、屯蒙、水火、金木、母隱、子胎、情性、龍虎、鉛汞、主賔、刀圭、媒娉、白黑、雌雄、顛倒、沈浮、攢簇、時節、朔望、弦氣、火候、進退、斤兩、爻符、抽添、沐浴、烹鍊、温養、换鼎、脫胎，似此等名，雖聖師丁寧訓誨，猶恐乖錯，安得凡夫而自會耶？", "py": []}, {"t": "故純陽祖師云：當時自飲刀圭，誰信無中養就兒？辨水源清濁，木金間隔，不因師指，此事難知。紫陽翁云：饒君聦慧過顔、閔，不遇真師莫强猜。", "py": []}, {"t": "今留試金石三寸于此，别其真僞。凡學仙子，先一試之：若得至人傳了，首以《叅同契》、《龍虎經》、《悟真篇》此數書内問，無不知，順了逆明，横串直貫，指南透北，識西就東，只此便是。何以故？蓋聖賢之言，亦有順求，亦有逆取，雙關二意，曉了一般。若邪師俗子，妄談臆會，問他已上數書，則懡㦬其說，直也不了，横也不知，縱能直知，逆又不了。此處有著落，便試了也。", "py": []}, {"t": "且得人最難。純陽帝君、海蟾、重陽諸祖，特憫世之間道者少，雖證帝位，立誓度人，故出没變化，往來塵世，必其可者度之。是此金丹之道，神仙能授與人，而不能必其成，却能知其必成之人，是以度之必成之人耳。口自别，何哉？大智慧的，口求之而心愈低下，耳聽之而思所以行。", "py": []}, {"t": "上陽子曰：予昔未聞，擬若得之，要與世人盡諳此道，不相瞞隱。及既得聞，審思宻視，果無其人堪傳此者。純陽翁云：茫茫宇宙人無數，幾箇男兒是丈夫？俗眼看來，丈夫而非男兒乎？蒙師宻授，吾乃今而後知真仙聖師意，豈不欲人人領悟、箇箇圓成？爭奈世人不及者衆，過者大多，百般蔽阻，無由見聞。", "py": []}, {"t": "是道也不可以言傳，而非言則何以聞？謂不可以言傳者，縁以時人習卑識陋，不足以語之也。必固語之，彼豈信受而行之哉？是曰不可以言傳也。果若非言，云何口授？今人直以無言是道，寧知於中妙語更多，但非六耳所可共聽，否則聖人明示直說，何乃從古隱到而今，轉不可說？", "py": []}, {"t": "後之學者，慧眼未開，宜先審其忠孝、正直、善惡、賢愚。大道非正人君子、非素所好善者，端不可與，切莫嗜利妄泄輕傳。儻非其人，彼此受譴，況欲其敬師成道乎？", "py": []}, {"t": "《黄庭經》曰：授者曰師，受者盟以代，割髮肌膚全，携手登山，歃液丹，金書玉景，乃可宣太上微言，致神仙不死之道。此其文。天地之間，此事最大，非重盟誓，孰敢泄機？比授非人，已彰明譴。紫陽三傳非人，三遭其難，仙經具載，可不戒之？", "py": []}, {"t": "顧惟禁祕不傳，則是拒抑仙子，不能接引方來，拒祕非宜，但當審擇。僕之念此熟矣，遂作《金丹大要》，直述無文，便於觀覽。", "py": []}, {"t": "所謂要者，在於庚方月現、子時癸生，取先天地真一之氣，是氣即黑鉛也。當此之時，藥物真正，水源至清。然月之現，存乎口訣；時之子也，亦要心傳。", "py": []}, {"t": "廣成子謂黄帝曰：慎汝内，閉汝外，多知爲敗。我爲汝遂於大明之上矣，至彼至陽之原也；爲汝入於杳冥之門矣，至彼至隂之原也。老子曰：天地之間，其猶橐籥乎？虚而不屈，動而愈出。多言數窮，不如守中。孔子翼《易》曰：一隂一陽之謂道，偏隂偏陽之謂疾。魏伯陽曰：類同者相從，事乖不成寳。崔公《入藥鏡》云：是性命，非神氣，水郷鉛只一味。是也。", "py": []}, {"t": "天性之道，或有自悟；天命之妙，必待師傳。無名子云：偃月爐，隂爐也，中有玉蘂之陽氣，即虎之弦氣也；朱砂鼎，陽鼎也，中有水銀之隂氣，即龍之弦氣也。金丹即此二火之氣，調停和合以成。", "py": []}, {"t": "然吾所謂神與氣精，迎送動止，凡百作爲，皆主於意；色聲香味觸，皆關於意。意爲即爲，意止即止。故求丹取鉛，以意迎之；收火入鼎，以意送之；烹鍊沐浴，以意守之；温養脫化，以意成之。故崔公云：一日内，十二時，意所到，皆可爲。此之謂大要也。", "py": []}, {"t": "有能猛省，如前試金石，則得《金丹大要》之要也。既得其要，不妨求侣問材，以成真人。", "py": []}, {"t": "噫，世有以萬金而買功名者，其身安能久乎？世有以萬金而濟死者，其尸能載生乎？運有否終，唯道長久。", "py": []}, {"t": "亦有聞道之士，不肯直下承當，勇銳向前，疾早便做，乃欲待其功名志滿、諸事已了，方成此道，又惑之甚。怱怱天不與年，身捐於世，悔何能及？佛果云：只今休去便休去，若覓了時無了時。祖師云：試問堆金等山嶽，無常買得不來。無棄萬户侯而爲身者，張子房焉；棄萬金貲而求道者，馬宜甫焉。今之視昔，誰能及之？後之視今，蚤宜叅悟。", "py": []}, {"t": "上陽子曰：大修行人，已得師傳，先結丹友。薛眞人云：我今收得長生訣，年年海上覓知音。又云：幾年湖海覓仙儔，不做神仙不肯休。泥丸翁云：若無同志相規覺，時恐爐中火候非。陳虎丘云：朝朝惟切尋同志，走遍東吴不見人。蓋得知音道侣，乃相規檢，匡其不逮，以共成道。亦有善侣而未聞道，財則有餘，是宜貿易，兩相成事。故龐藴溺財求藥，傳大士唱賣妻子，皆同此道也。", "py": []}, {"t": "是以釋氏修定坐禪，以土制鉛，以鉛制汞，鉛汞歸鼎，身心不動，是云修禪入定。今之所謂禪者，皆琉璃瓶子禪，行也打碎，坐也跌碎。世惟皮可漏子禪，撦亦不斷，咬亦不破。若人叅得皮可漏子禪，則鉛與汞自相投矣。三教一家，實無二道。其分彼我者，乃是一箇盲人鞭騎瞎馬，而與人較勝負，豈不爲明眼底所笑？", "py": []}, {"t": "圜悟云：禪非意想，以意想叅禪，則乖道絶功勳；以功勳學道，則失。直須絶却意想，唤什麽作禪？脚跟下廓爾，無禪之禪，謂之真禪，如兔子懷胎。絶却功勳，唤什麽作道？頂門上照耀，無道之道，謂之眞道，似蚌含明月。佛祖留下數百公案，見性爲先。是此《金丹大要》，禪道俱明，仙佛同證，性命二者，皆要了知。既得了知，宜加精進。", "py": []}, {"t": "上陽子曰：是此《金丹大要》，訪諸仙聖之書，發明先天一炁之妙，開引後來之人，于中顯露泄漏尤多。夫此何故？是予早年素有此志，未遇真師，不明其要，閱諸丹經，杳難捉摸，思考不及，研窮無方，廢寢忘餐，每留此憾。", "py": []}, {"t": "神仙之道，因執爲無，非遇聖師分明指示，則與凡流同歸腐朽。是因師指，盡以其間難形言者，悉皆詳述，作爲此書，名曰《金丹大要》，以續往憾，與後來人出隻慧眼。不可施於筆者筆之，不可發於語者發之。", "py": []}, {"t": "後道之士，因縁獲覩是此《金丹大要》，如對聖師親相授付，當知火藥悉具，運用皆全。", "py": []}, {"t": "上陽子曰：是此《金丹大要》十卷：首卷虚無三章，以象三才；二卷上藥一章，以體法身；三卷妙用九章，以證九還；四卷須知七章，以驗七返；五卷積功詩歌，以分邪正；六卷累行序說，使無著象；七卷發眞問答，接引群生；八卷脩眞圖像，示可印證；九卷越格擬古，最上一乘；十卷超宗酌古，見性成佛。卷卷皆備鉛汞火候。", "py": []}, {"t": "學道之士，首卷不悟，須尋二卷；三卷不達，四卷須知。次第熟覽，無一不備。吾之成此《金丹大要》，多重言者，切之故也；多俗語者，顯之故也。", "py": []}, {"t": "寧免泄露，冒瀆真詮。然恐方來無直悟底：自非宿昔有仙骨者，不能聞是《金丹大要》之名，況云欲得而誦之乎？非有大因縁者，不能存是《金丹大要》之㫖，況云欲得而了之乎？非有大智彗者，不能入是《金丹大要》之路，況云欲得而行之乎？非有大功德者，不能親是《金丹大要》之道，況云欲得而修之乎？", "py": []}, {"t": "上陽子曰：大修行人，已證脫胎神化，若復得此《金丹大要》，可以再進向上工夫。其有十月聖胎已完，若復得此《金丹大要》，可以叅證出入去來。若初下手，得藥入室，是此《金丹大要》可以保養全功。亦有聞道蒙惑，懷疑所未决者，是此《金丹大要》中有試金之石，即可辨驗。過得實，疾早下工，更莫遲疑。", "py": []}, {"t": "入道詩云：人身難得今已得，正道難明今已明。此身不向今生度，更向何生度此身？", "py": []}, {"t": "上陽子曰：復有得此《金丹大要》，不能明了於中奥㫖，便可像繪祖師純陽、重陽、丹陽三仙真形，晨夕香花，一心對像，誦念是此《金丹大要》一遍，乃至十遍、百遍、千遍。日積月深，初心不退，愈加精勤，自感真仙親臨付授，是學仙子頓爾開悟，理路透徹，心地虚靈，即時脚跟踏得實際。", "py": []}, {"t": "夫何以故？玉命見授，丹陽真君掌領仙籍，巡行天下，察人功勤，註上丹臺，分遣已成真人仙子，下爲人師，移文録司，主借材寳，成就學仙之士無上妙道，以成真人。", "py": []}, {"t": "是學仙子精專注想，因縁遭逢；是學仙子不憚苦辛，懇求至道；是學仙子勿以天高地厚，難以感通；是學仙子勿以大道窈冥，非凡可學；是學仙子勿以隂陽分位，非人能成；是學仙子勿以性命由天，非我所有。是學仙子不作是見，不作是聞，勇猛智慧，即得性海汪洋，命源流潤。是學仙子列名書丹，冥心究竟。", "py": []}, {"t": "是此《金丹大要》，或觸事物，或過經筵，或在舟船，或行道路，或對鏡容，或照水影，或觀淫房，或覩屠殺，或因童戲，或見僧坐，築著磕著，偶一覺悟，從之而入，倮倮洒洒，圓圓陀陀，得大自在，恰如貧人於房舍中掘得祖父一窖金寳相似，方知此是自家之物，多年棄藏，一旦得之，受用不盡。", "py": []}, {"t": "上士至人，昔藴大乘根器，又復得此《金丹大要》，一誦再憶，豁然見性，即佛即仙，如嗜寳人道傍拾得無價明珠，喜慶無量。學仙之士，願以生死爲一大件，早收藥物，成事丹爐，白日騰身，高奔帝境，實我志也。上陽子金丹大要虚無卷之一。", "py": []}]}, {"h": "虛無卷之二", "paras": [{"t": "上陽子金丹大要虛無卷之二。睦二紫霄絳宫上陽子觀吾陳致虚撰。道德經序。上陽子曰：道始無名，德亦非稱。自伏羲畫卦，蒼頡創爻，玄龜龍馬，河圖洛書，文王重易，箕子洪範，皆存而不名。老子垂世，始强名之曰道。", "py": []}, {"t": "夫道之爲說，先天地而位天地，始萬物而育萬物，草木根實，非道不生；胎卵濕化，非道不産。道果何物也？其可見乎，而功用若是？其可摸捉乎，而造化若是？其可思議乎，而變通若是？自老子一指出、一强名之後，千古之上，此道得老子以明；萬世之下，此道以老子爲法。天以清，地以寧，三光以明，萬物以榮，聖人仙佛以修以成。噫，道果何物，而若是其大也？", "py": []}, {"t": "孔子而佛，皆明此道，非别有一道也。後來乃分三教：儒者不明曾子、子思之相受何事，却猜之爲日用當行；釋者不能明心見性，只得念誦頑坐；道則不究金丹竅妙，以爲焚修法術皆非道也。蓋未有所授受耳。", "py": []}, {"t": "道之爲物，通氣而生，氣復資氣而育，天地萬物，未有非氣而自生育者。然吾所謂氣，却非天地呼吸、口鼻往來。要知是氣之名，須究外内之道。氣之在外者，曰黑鉛，即金丹之道也：釋云佛法，儒謂仁義，道曰金丹。三教大聖，必用是氣而後方能成佛作仙，即此是道，非别有一路耶？", "py": []}, {"t": "氣之在内者，曰黑汞，即修定之道也：道名踵音，儒謂中和，釋云世音，即自然之道。三教大聖，必用此道，故名雖殊而道則同也。是以天下無二道，聖人無兩心。", "py": []}, {"t": "昔者老子西游，關令君喜知爲聖人，迎之曰：子將隱矣，强爲我著書。老子乃著五千餘言而去。眞著書處，今京兆盩厔縣終南山宗聖宫是也。此書留世，始以老子名，分上下二篇，真人鄭思遠標注八十一章之目，唐賜號曰《道德經》。古今解註，何啻數百人？唯河上公所釋，以授漢文帝者，語淡義深，今難得其眞本。", "py": []}, {"t": "經中大意，第一章顯而出之了，具眼者於此早分利鈍。夫道也者，本無名無爲，且名亦既有，復不可常名，則無爲而無不爲矣。故三十八章曰：上德無爲而無以爲，下德爲之而有以爲，上仁爲之而無以爲，上義爲之而有以爲。熟於道德者，體無爲而無不爲也。無爲者，無以爲也；無不爲者，有以爲也。爲是道者，慧饒顔、閔，必待師傳。建言有之：古之善爲士者，微妙玄通，深不可識。", "py": []}, {"t": "上陽子曰：豈古然哉？於今爲然。蓋不可識則不可見，不可見則不可思議摸捉。我師縁督真人，授鍾、吕、王、馬之的㫖，南嶽一面，悉拜其授。致虚年甫四十，雖居林下，癖嗜詩書，嘗謂寂滅虚無，其說杳冥渀𧧯，蒙師一指，芒刺脫然，眼下便見，方知脚跟元踏實地，猶如空中浮雲忽散，寳月圓明。", "py": []}, {"t": "並得所解《道德經》，焚香啓視，至此「兩者同出而異名」，早是性命雙題，愈覺渾身是汗。", "py": []}, {"t": "坐對老子坐，行共老子行，佛祖在脚跟底立，似三界中我的最尊，超然有何生死？則三清劎、五嶽冠、有與無、物與竅、朱裏汞、水中銀、日兔月烏、雌雄黑白，以至金剛、浮幢、燈籠、佛殿、正法眼藏、涅槃妙心、百尺竿、西江水、竹麻萑葦、棒喝照用、恒河沙量佛法，莫不皆是。見了悟了，日夕照覷，大機大用，有時得到休歇之處，尤爲快活。", "py": []}, {"t": "何以故？只爲此者雙關二意，直要世人明了爲期。且道同出却不同入，同出又不同没，只一已是强名，況復云此兩者？於下重云衆妙之門。聖人無空言，一字是一箇鐵漢，點檢將來，却似大路傍草裏有兩顆驪珠，尋常人都驀直過了，明眼人一見，圓陀陀，光爍爍，收拾隨身去，豈不欣然？", "py": []}, {"t": "何哉？蓋今世人只是看經，却不觀經。聖賢仙佛留下經書，要引世人皆爲聖賢仙佛。一切常人不明其意，朝念暮誦，以爲禱祈，更不於中究竟生死一件實事，抑何愚哉？", "py": []}, {"t": "猶誨人醫指以訣云：左心、小腸、肝、膽、腎。明了的，便以此而脉人之脉，不必勞誦千遍萬遍；若病而不診，只誦此語，雖感得叔和立現，復奈之何？經書亦然。若看而不觀，亦猶病之誦而不診者，但了其字。觀者要了其義：了字，則訛了舌頭；了義，則坐斷舌頭。訛了非了，坐斷是了。不了的是人，了底是聖賢仙佛。", "py": []}, {"t": "喻如《金剛經》云：佛說非身，是名大身。六祖釋云：色身雖大，内心量小，不名大身；法身雖小，内心量大，等虚空界，方名大身。色身雖如須彌，終不爲大。此欲世人早明色身、法身二事。若只口誦，不觀其義，輪迴生死，何有了期？", "py": []}, {"t": "三教聖師，立言垂訓，皆欲接引方來，非各門異户以相氷炭者。師授是經，俾之續其言外意。", "py": []}, {"t": "上陽子曰：大哉五千餘言，多以天下國家、用兵治民之說，以翼其道。然以之平天下、治國家、用兵使民，無施不可。仁者見之謂之仁，智者見之謂之智，故瑩蟾子有治道、丹道、兵機、禪機之說也。將以無爲之道奏之於吾皇，以倣陶唐無爲之治也；其將以有爲之道告之于宰輔，行治平日新之德也；其將以無不爲、有以爲之道，訓諸學道之士，以修金丹也。", "py": []}, {"t": "得此道以無爲而治天下者，漢文帝之謂矣；得此道以佐漢而定天下者，張子房之謂矣；得此道而其鬼不神者，張輔漢之謂矣；得此道而善攝生者，許旌陽之謂矣。妙哉是經。其言父，則云教父；母，則云物母。此其爲《道德經》也。", "py": []}, {"t": "其㫖意，先有爲而後無爲，非蠢然無爲也；本道德而後仁義，非毁於仁義也；先仁義而後禮，非棄於禮者也。如恍惚中有象有物，杳冥中有精有信，不貴難得之貨，此皆直指大道、顯露玄機者也。經内隱八十餘異名，如衆甫、神器、玄牝、橐籥之類，蓋深注意於道，使後之人從是而悟，因悟而入，因入而有焉，即有爲者，金丹也。", "py": []}, {"t": "噫，後之人峩其冠者，不明玄牝竅妙之門；曳其裾者，不修無爲有爲之道。使彼之有目者，視之爲異端之教；彼之有口者，呼之爲異端之徒。而世之明敏器識之士，甘與彼之下愚，或儕或躐，奔競是非，至于老死，而不知有神仙之道，惜哉。", "py": []}, {"t": "且三教聖賢之所建立者，始焉莫不各有其道，而繼之者特未善也。老子者，聖人也，太上也，巍巍尊居三清之境，以生育天地、運行日月、宰制劫運、終始萬物爲心，其視天下民物，一不安者，若已有之。中下之人，恣其狂愚，不知源流，妄誕詆排，謂彼之非聖人者，罔譴益彰，惑之甚也；謂此之歸太上者，罔福，是未得其道也。", "py": []}, {"t": "原其著此書者，其欲引道修行之士以成真人，使天下有以匡世救劫者也，如降魔、斬蛟、平潮、弭灾之事焉。然悟者自悟也，迷者自迷也。悟也者，因縁時節之來也；迷也者，宿昔所未種也。君臣也，父子也，夫婦也，兄弟也，朋友也，此大道之綱常也，萬世之不可易也。降魔也，斬蛟也，此道成之事也，適時而就其功也。", "py": []}, {"t": "老子之道，即金丹大道也。夫金丹之道，先明三綱五常，次則因定生慧。綱常既明，則道自綱常而出，非出綱常之外而别求道也，是謂有爲，故云和其光、同其塵也。乃至定慧圓明，是謂無爲，故云知其雄、守其雌也。道至無爲，則神仙之事備矣。", "py": []}, {"t": "知此經者，則明其道，故曰：太上下知有之。不知者，則辯其語，故曰：夫唯無知，是以不我知。今遵師訓，因並釋之，每章就下轉語。夫如此者，特爲此老垂一隻方便手，爲天下人具一隻智慧眼。垂手者，接濟迷途；具眼者，早自明了。使人人回首，物物知歸，長生昇仙，必有真實根器的。至順辛未中秋後三日，紫霄上陽子觀吾陳致虚謹序。", "py": []}, {"t": "道可道章解。道可道，非常道。上陽子曰：夫道也者，位天地，育萬物，曰道；揭日月，生五行，曰道；多於恒河沙數，曰道。恒河者，西之界，此河四十里，沙細如麪，比數多者之也。孤則獨一無侣，曰道；直入鴻濛而還歸溟涬，曰道；善奪造化而頓超聖凡，曰道；目下機境未兆而突爾靈通，曰道；眼前生殺分明而無能逃避，曰道；處卑污而大尊貴，曰道；居幽暗而極高明，曰道。是道也，", "py": []}, {"t": "有大識見之眼而無睛，有大智慧之耳而無聞，有吸西江之口而無齒，有諸妙香之鼻而不嗅，有殺活舌頭而味不味，有金剛法身而在自在，有生死劒而武士不敢施用，有一字義而文人不能形容。雖黑漫漫，不許一眨，闇而日彰；任峭巍巍，辟立萬仞，放身無怖。", "py": []}, {"t": "細入刹塵，曰道；大包天地，曰道；將無入有，是道。作佛成仙，是道。佛經五千四十八卷也，說不到了處；《中庸》三十三章也，說不到窮處；《道德》五千餘言也，說不到極處。道也果何謂也？一言以定之，曰氣也。", "py": []}, {"t": "故鄭真人曰：道乃氣之用。當知體其道者，是氣也。可道者，道有號，道有名，道有諱。比如道之號曰萬物宗，是道號也；名曰涅槃妙心，是表德也。道之號與表，皆可呼可言，故曰可道。至如道之諱，却是生萬物之道，雖有其名，而不可以常道，故曰非常道。", "py": []}, {"t": "何謂非常道？蓋可自見而不可以人見，衆生見；可自道而不可以人道，衆生道。是云可道、非常道也。何謂非常道？以其至廣大而盡精微，故不可以常道也；以其淨倮倮、赤洒洒，巍巍尊高，故不可以常道也；以其杳冥恍惚，有物混成，先天地生，故不可常道也。是謂非常道者也。", "py": []}, {"t": "名可名，非常名。上陽子曰：夫名也者，事物用以稱題曰名，人神借以呼唤曰名。可名、非常名者，喻如乾，陽物也，曰乾則可，曰陽物則不可；又如坤，隂物也，曰坤則可，曰隂物則不可，故曰可名、非常名也。", "py": []}, {"t": "又如今有人，名曰谷神，小名曰芻狗，而字曰衆甫。諱與小名，上之呼下可也，故曰可名；衆人則不可呼。若衆人呼人之小名，則其人勃然而怒矣。何以故？衆人不可呼人之小名。若於僻陋之所、人不聞見之地而言之，則可；若於稠人中呼之，則必自取辱焉，故曰非常名也。", "py": []}, {"t": "何謂非常名？蓋人人有一箇諱名，或可以自題，而不可托人言，是云非常名。我師曰：道以用言，在人未嘗不可行，但非泛常所行之道；名以體言，在人未嘗不可稱，但非泛常所稱之名耳。", "py": []}, {"t": "無名，天地之始；有名，萬物之母。無者，待之而後動也；有者，已動而將形也。天地始者，雌雄蟠糺，而物所自暉；萬物母者，隂陽感兆，而氣所自育。以無而偶有者，猶以天而配地；以母而匹始者，猶以氣而合神。是知有與無，二者峙而天地位焉；始與母，二者出而萬物育焉。", "py": []}, {"t": "我師云：人之靈明知覺者，即無也，神也；絪緼活動者，即有也，氣也。此論玄遠，安其大方眼，然後可以見不見之處，照不照之所也。", "py": []}, {"t": "常無欲以觀其妙，常有欲以觀其竅。一定之中而求變化，曰常；未見之前而將興發，曰欲；沖虚至聖，曰妙；包元含靈，曰竅。常無欲以觀其妙者，於一定之中而求變化，待之而後動，而於未見之前而將興發，此即觀其沖虚至聖之妙也。常有欲以觀其竅者，於一定之中而求變化，已動而將形，形於未見之前而將興發，此即觀其包元含靈之竅也。", "py": []}, {"t": "我師曰：觀其妙者，見其智慧之精微；觀其竅者，見其功用之遠大也。此兩者，同岀而異名，同謂之玄。兩者，道與名也，無與有也，始與母也，妙與竅也，皆云兩者，而當以無與有爲先。同出而異名者，有無同出於一，而名乃分矣。玄者，不可見，不可聞，不可說。同謂之玄者，無與有兩者，皆不可得而見聞名說也。", "py": []}, {"t": "玄之又玄者，以其無與有兩者，愈不可見，愈不可聞，愈不可名謂，即佛云不可說、不可說，轉不可說者，即此道也。衆妙之門者，言其玄乃萬物沖虚至聖岀入之所也，而我師謂有言外意。", "py": []}, {"t": "上陽子曰：有物先天地，眼下甚分明。道之體者，自然也；道之用者，虚无也。虚无者，先天地也。契曰：委志歸虚无。《悟真篇》曰：道自虚无生一氣。我師云：先天一氣，自虚无中來。此乃爲之而有以爲也。自然者，復天地也。人禀父母隂陽二氣而生而長，渾混未判，抱一無離，此乃無爲而無以爲也。", "py": []}, {"t": "道本無名，强名之曰道，是有名矣。既有名矣，又不可常名；既不可常名，則不可得而聞見也。是道也是物耶？是有形也是無形耶？乃不可常道、常名而不可聞見者也。是以從古聖人，以至于今，成仙作佛者何限，雖遺千經萬論于世，而終不顯題者，唯是道之尊、德之貴也。", "py": []}, {"t": "夫人本來清靜，若脚跟下見得明了，無他障礙，何必更向經句上尋覓？蓋爲世人翻著見解，訥處不能訥，知處不能知，是故聖人慈悲，方便假名託字，百般遷就而爲之諱，亦只先天地一物耳。", "py": []}, {"t": "三教大聖，殊途同歸，初無差别。如孟子集義所生之道，即孔子一貫之道也；釋迦拈花以傳涅槃妙心之㫖，即達麽直指人心、見性成佛也；老子有無、玄牝、物母之道，即玄關一竅、大道金丹也。深山妙窟裏，代不乏人。所謂透到是處，一明一切明，一了一切了。利根上士，獲覩此經，字上求義，義裏通禪，句中得意，意外悟道，忽若智慧眼開，感得天人相與，寧不慶快？上陽子金丹大要虚無卷之二。", "py": []}]}, {"h": "上藥卷之三", "paras": [{"t": "上陽子金丹大要上藥卷之三(四同/卷)睦三。紫霄絳宫上陽子觀吾陳致虚撰。精氣神說上。黄帝曰：知之修鍊，謂之聖人。無上元君謂老子曰：長生之功，由於丹；丹之成，由於神。故將合丹，必正身心。《黄庭外景經》曰：玉池清水灌靈根，審能修之可長存。《心印經》曰：上藥三品，神與氣精。", "py": []}, {"t": "聖人言修鍊合丹者，鍊精、氣、神而已。唯此三者，千古之上、萬世之下，無以易之。而精氣神，有後天地，有先天地，今將此二說别而曉之。", "py": []}, {"t": "夫精者，極好之稱：美者言精，惡者言麄，夫物皆然。凡人唯精最貴，而甚少。在身中，通有一升六合，此男子二八已滿、未洩之成數，稱得一斤；積而滿者，至三升；損而喪之者，不及一升。", "py": []}, {"t": "精與氣相養：氣聚則精盈，精盈則氣盛。日啗飮食之華美者爲精，故從未從青。人年十六，則精洩。凡交一次，則喪半合。所喪者少，即隨日生而補之，所補者隂精而已。唯元精一洩，非先天者，則不能補。若有喪而無益，則精竭而身憊也。", "py": []}, {"t": "故慾不節則精耗，精耗則氣衰，氣衰則病至，病至則身危。噫，精之爲物，其真寳乎？又奚可縱慾而喪軀乎？丹陽祖師曰：色者，甚於虎狼，敗人美行，損人善事，亡精滅神，至於殞軀，爲道之大孽也。下愚之人，謂其壽命數定，恣欲爲快其意。古之戒曰：油枯燈盡，髓竭人亡。是知精實一身之根本，未有木無根而能乆乎？", "py": []}, {"t": "象川翁曰：精爲生氣，氣能生神，榮衛一身，莫大於此。養生之士，先寳其精：精滿則氣壯，氣壯則神旺，神旺則身健而少病。内則五藏敷華，外則皮膚潤澤，顔容光彩，耳目聦明，老當益壯，神氣堅强。嘗見高年慾情未衰，此其蚤年洩遲之驗；至此又能絶慾，則壽更多。", "py": []}, {"t": "精之全者，無如赤子。赤子受父母隂陽二氣而生，日以增長。老子曰：骨弱筋柔而握固，未知牝牡之合而䘒作，精之至也。使赤子如有知，保固其渾然之精而無虧洩，待其年壯明敏，乃遇至人，授以燮調之道，必作無爲之眞仙矣。兹事固少。此以人身中之精而言，乃後天地之精；若論還丹，却非此精。", "py": []}, {"t": "夫金液還丹之精，姓金，唤九三郎，諱元晶，號曰金華商，夫君居玉池之西，出入跨虎，乳名嬰兒，晩則呼爲金公，凡到鄰家，便稱主人，其情嗜交梨。此乃先天地之精，却爲人之至寳。老子曰：窈窈㝠㝠，其中有精，其精甚真，其中有信者，此也。修鍊之士，先有此精，既若明了，即可仙矣。是號爲金液還丹。佛號丈六金身者，積精至十六兩也。", "py": []}, {"t": "純陽翁云：吞精食氣，先從有悟，理歸真便入無。海蟾《金丹歌》曰：爲甚神仙却愛身？也須借殻養精神。陳泥丸云：大藥須憑精氣神，採來一處結交成。大藥者，即金液還丹也。", "py": []}, {"t": "昔者堯得之於務成子，亟欲修鍊，縁緫萬機，慮不得就，乃捐天下而授舜，曰：惟精惟一，允執厥中。舜以授禹，而增之曰：人心惟危，道心惟微，惟精惟一，允執厥中。後來龍互禪師乃云：人情濃厚道情微，道用人情世豈知？空有人情無道用，人情能得幾多時？從古到今，修仙作佛者，未有捨此精而别有路耶？", "py": []}, {"t": "其後天地之精屬隂，人若寳之，唯能健其身、益其壽而已。學猥之徒，欲吞此精之穢，或採閨丹而嚥，或運己精補腦，以是爲道，不亦愚乎？獨先天地之精屬陽，聖人修鍊以爲丹者，此也。", "py": []}, {"t": "雲房老仙曰：涕、唾、精、津、氣、血、液，七般物事，盡爲隂。又云：四大一身，皆屬隂，不知何物是陽精？趙中一云：一身内外，緫皆隂，莫把陽精裏面尋。白紫清云：其精不是交感精，廼是玉皇口中涎。雲門和尚云：乾坤之内，宇宙之間，中有一寳，秘在形山。孔子翼《易》曰：男女媾精，萬物化生。", "py": []}, {"t": "若其上士，言下須有指歸。何以故？曰：男女媾精，萬物化生，此爲奇特。若當時孔子以世俗生養之說爲言，則必云男女媾精，人乃化生，却乃普云萬物化生，於此切莫淺易看過了。上士至人，一聞便了；中下之士，非遇真師直指宻訓，奚可暗猜？", "py": []}, {"t": "我師縁督子曰：何者爲性命？人之一身，至精至粹，至尊至貴，莫越精、氣、神三者，舉世罕能達此。《黄庭經》云：急守精室勿妄洩，閉而寳之可長活。廣成子授黄帝曰：毋勞汝形，毋摇汝精。黄帝以之而修鍊，後於鼎湖上昇。自後言修鍊之道爲黄老術，抑愚矣。此乃金丹之大道也，不可謂術。世唯此事最大，人人可以修鍊，而成仙作佛也。", "py": []}, {"t": "夫氣者，天地萬物莫不由之：在天地之外，包覆天地；在天地之内，運行天地。日月星辰得以明，風雲雷雨得以動，四時品物得以生長收藏。此唯天地間隂陽造化之氣爾。獨人身之中，全其天地隂陽造化之氣，得勤而用之，又有二焉。二者何也？有先天地之氣，有後天地之氣。今以後天地之氣爲言：此氣生於穀，故從乞從米，而蓄於胃，胃得穀而生氣。", "py": []}, {"t": "黄帝曰：五藏之氣，會於胃，而氣所由生也。葉文叔曰：人受生之初，在胞胎之内，隨母呼吸，受氣而成。及乎生下，剪去臍帶，一點元靈之氣，聚於臍下。凡人唯氣最先，莫先於呼吸。眼、耳、鼻、舌、身、意，皆由是氣；非是氣，則色、聲、香、味、觸、法，都不知覺。氣之呼，接于天根；吸，接地根。", "py": []}, {"t": "氣之在人身，有八百一十丈，與脉偕行，衰旺相關。積而壯者倍之，因勞慾而喪者，無一半而已。人唯寳精，則氣自裕；氣裕則精盈。日啗飮食之精，熱者益氣。人年二十，面氣旺。節慾少勞者，則氣長而緩；多慾而勞倦者，則氣少而短。氣少則身弱，身弱則病生，病生則命危。", "py": []}, {"t": "試以日用常行見之：凡交感之後，氣即促急。葉文叔云：衆生迷蒙，醉於情愛，日夜漏洩，不知眞幾何也，本去根枯之死必矣。世人但知養生止於禁慾，殊不知一念若動，氣隨心散，精逐氣忘。爲此道者，當心體太虚，内外如一。噫，氣之爲物，奚可不愛之乎？", "py": []}, {"t": "下愚之人，日則逞力多勞，夜則恣慾喪精，氣因以乏，不知氣乃命之蔕，未有花無蔕而不凋乎？養生之士，先資其氣，資氣在於寡慾，慾情不動，則精氣自相生矣。氣之盛者少病，内則志堅骨强，外則筋力勇銳，身體秀實，齒白唇紅，老而不衰，步履輕快。", "py": []}, {"t": "且氣之全者，無如赤子。赤子禀父母隂陽之氣，日漸長而無虧，加以乳哺飮食，日以增羡。老子曰：終日號而嗌不嗄，和之至也。碧虚子陳景元註曰：天和之氣至全也，故真人之息以踵，其嗌不哇。使赤子如有知，守其渾然之氣，與精同保而不虧洩，年壯又遇至人，曉以永世之道，亦可作無爲之眞仙矣。兹事又少。", "py": []}, {"t": "丹陽祖師曰：薄滋味，所以養氣；去嗔恚，所以養性。又曰：守氣之妙，在乎全精，尤當防其睡眠。《黄庭經》云：元氣所合，列宿分，紫烟上下，三素雲，灌溉五華，植靈根。", "py": []}, {"t": "孔子曰：血氣方剛，戒之在鬥。夫人遇行走，則氣急而嗄甚；睡，則氣麄而劓；唯坐靜，則氣平而緩。又氣屬火，而脾因氣以運。蓋人睡則脾損而色黄，冷食亦然。多喫冷飯之後而又行房，則能使人心狡而色黄。何以故？飯窒於氣，而意多婪，復嗜睡而損脾也。", "py": []}, {"t": "此以人身中之氣而言，乃後天地之氣。傍門迷人，欲嚥其津而納此氣，以爲是道，猶炊砂而得飯，不亦惑乎？紫陽翁云：嚥津納氣是人行，有藥方能造化生。鼎内若無真種子，猶將水火煑空鐺。唯先天真一之氣，可鍊還丹，乃自虚無中來。", "py": []}, {"t": "此氣姓白，唤太一郎，名元炁，號曰宇宙主宰素練郎君，寄居西川，出入乘白馬，乳名真種子，晚則呼白頭老子，到鄰家便稱父母，好食烏龜而多情。", "py": []}, {"t": "此爲先天地之真氣，却是人之至寳。《隂符經》曰：天之至祕，用之至公，禽之制在氣。老子曰：萬物負隂而抱陽，沖氣以爲和。又云：或嘘或吹，或强或羸。大修行人，先須洞明此之一氣。若得之，號曰紫金花，又曰摩尼珠。茅真君《靖中吟》：氣是添年藥，心爲使氣神。若知行氣主，便是得仙人。上陽子金丹大要上藥卷之三。", "py": []}]}, {"h": "上藥卷之四", "paras": [{"t": "上陽子金丹大要上藥卷之四。紫霄絳宫上陽子觀吾陳致虚撰。精氣神說下。海蟾翁《金丹歌》：鍊形成氣歸真一，鍊氣成形謁紫宸。《丹髓歌》云：昔日遇師真口訣，只要凝神入氣穴。《悟真篇》云：道自虚無生一氣，便從一氣産隂陽。《石真人還源篇》云：氣是形中命。無名子云：真一之氣，生於天地之先，得於虚無之中，恍惚窈冥，視之不見，聽之不聞，摶之不得。如之何凝結，而成黍珠者哉？", "py": []}, {"t": "蓋聖人以實而形虚，以有而形無。實而有者，真隂真陽也，同類有情之物也；虚而無者，二八初弦之氣也，有氣而無質者也。兩者相形，一物生焉。所謂一者，即先天地真一之氣，凝而爲一黍之珠也。原其天地之内，已有形質者，皆後天地之氣，屬隂；獨先天地之氣屬陽。", "py": []}, {"t": "崔公《入藥鏡》云：先天氣，後天氣，得之者常似醉。形如明窗塵，一似細霧烟。何謂先天氣？重陽翁云：五行不到處，父母未生前。丹陽翁曰：喘息莫教麄，上下寬舒。《叅同契》曰：枝莖花葉，果實垂布，正其根株，不失其素。《悟真篇》云：萬般非類徒勞力，爭似真鉛合聖機。蓋世間從石而出者，凡鉛也；從造化窟中出者，真鉛也。何謂真鉛？即先天地真一之氣。", "py": []}, {"t": "《契祕圖》曰：離納己，爲日、爲火、爲心、爲丹砂、爲龍、爲汞；坎納戊，爲月、爲水、爲腎、爲鉛、爲虎、爲氣。在易之初爻，曰潜龍勿用，夫子翼之曰：潜龍勿用，陽氣潜藏。三教中人，觀書莫驀直讀過了，内有做官、作佛、修仙的道理在，須下了些工夫始得。", "py": []}, {"t": "上陽子曰：若陽氣潜藏，必難求之也，直要有力者，然後能求之。達磨初來曰：見此赤縣神州，有大乘氣象，成道必矣。此達磨之來，欲仗有力者，爲求是氣，以成其道。豈料謁梁未諧，至魏方得成佛。因知是氣，無其力者，必不得之。紫陽真人，乃依馬處厚之力；王沖照，乃得韓富公之力。石杏林授薛紫賢云：可往通邑大都，依有力者爲之。是知此氣每好潜藏，無力者安能得之？", "py": []}, {"t": "《太一真人破迷歌》曰：如何却是道？太乙含真氣。白真人云：此氣即非呼吸氣，乃知却是大素烟。我師曰：先天一氣，自虚無中來。上陽子曰：誰能承當得此一句，便是活仙了也。蓋虚無中來，却不是從天上落底，既不從天上落，又非自己所有。", "py": []}, {"t": "孟子曰：吾善養吾浩然之氣。其爲氣也，至大至剛，以直養而無害。又曰：是集義所生者，非義襲而取之也。又曰：持其志，無暴其氣。又曰：志至焉，氣次焉。次者，隨而至也。又曰：志者，氣之帥。既爲氣之帥，必爲氣主。爲之主者，使之來即來，使之住即住。又曰：配義與道。若大智慧底，於此便分清濁。", "py": []}, {"t": "何以故？曰吾善養，既而曰以直養，此乃發明易中之直。曰：夫乾，其靜也專，其動也直，是以大生焉。故周子《愛蓮說》「中通外直」，亦是意也。", "py": []}, {"t": "又曰是集義所生、非義襲而取，後云配義與道，以是而知孟子以仁義言之。又曰持其志、無暴其氣，志至焉、氣次焉，則知孟子非特善養，而亦善取。曰：云何取？曰：以直取。曰：云何來？曰：義所生。曰：云何見？曰：以志爲帥。以是知，以是見，孰皆出頭頂著，則他也有是知是見了。", "py": []}, {"t": "《叅同契》曰：此兩孔穴法，金氣亦相胥。《金碧經》曰：造化泉窟，陽氣發坤，日晷南至，五星聯珠，日月合璧。葛仙翁《流珠歌》曰：流珠流珠，役我區區，雲遊四海，歷涉萬書，忙忙汲汲，忘寢失哺，叅遍知友，燒竭汞朱，三十年内，日月長吁。", "py": []}, {"t": "吾今六十，憂赴三塗，賴師傳授，元氣虚無，真隂真陽，一吸一呼，五液灌溉，洞房流酥，真人度我要大丈夫。仙翁得此先天真一之氣，依法修鍊，白日紫雲，騰空升舉，天下後世受其賜也。", "py": []}, {"t": "天神者，妙萬物而言，依形而生。《黄庭經》云：至道不煩訣存真，泥丸百節皆有神。神名最多，莫能枚舉。身中三部：上部八景，髮神、腦神、眼神、鼻神、耳神、口神、舌神、齒神；中部八景，肺神、心神、肝神、脾神、左腎神、右腎神、膽神、喉神；下部八景，腎神、大小腸神、胴神、胷神、膈神、兩脇神、左隂左陽神、右隂右陽神。", "py": []}, {"t": "身中九宫真人：心爲絳霄宫真人，腎爲丹元宫真人，肝爲蘭臺宫真人，肺爲尚書宫真人，脾爲黄庭宫真人，膽爲天霐宫真人，小腸爲玄靈宫真人，大腸爲木靈宫真人，膀胱爲玉房宫真人。", "py": []}, {"t": "又有元首九宫真人：雙丹宫、明堂宫、丹田宫、泥丸宫、流珠宫、大帝宫、天庭宫、極真宫、玄丹宫、太皇宫。又金樓重門，十二亭長。身外有一萬八千陽神，身内有一萬八千隂神，共三萬六千神。所主者，唯絳霄宫真人，亦名肉團神，即心王也。", "py": []}, {"t": "又有三身神、四智神、三魂神、七魄神、七元八識神，假名異字，難可悉數。心王乃一身之君，萬神爲之聽命焉。故能虚靈知覺，作止任滅，隨機應境，千變萬化，瞬息千里，夢寐百般。又能逆料未來，推測禍福，大而天下國家，小而僻陋罅隙，無所不至。", "py": []}, {"t": "善藏喜怒哀樂、慈愛惡欲，又能隨人：其人表正，其神亦正；其人諂曲，神亦邪佞。人若絶慾忘情，精氣壯盛，神亦發旺明麗，形容美好；若人多慾勞損，神將衰而不守。其人恃酒風顛，汙名短行，神亦隨順，反益助之。", "py": []}, {"t": "《悟真篇》云：柰何精神屬隂，宅舍難固。又云：修真之士，若執己而修之，無過鍊精、氣、神三物而已。柰何三物一致，俱是後天地生，純隂而無陽，安能化形於純陽而出乎天地之外耶？此言一身之精氣神也。紫陽蓋欲提省世人，未得先天地之陽神，與身中精氣神相配，終不仙也。猶傅大士《金剛經》偈云：饒經八萬劫，終是落空亡。", "py": []}, {"t": "今以先天地之神而言：其神號無位真人，佛云紇利陀耶佛。若識認得此神，却有妙用。此神專主殺人，專主生人，修仙求佛者，必要此神主之方得。此神元來無頭無尾，無背無面，無名無字，廼能與佛同名同號，能順於人。若人姓張三，其神亦云張三；其人名金剛，其神亦云金剛；其人諱法眼，其神亦云法眼；人好食火棗，神亦好食火棗。蓋其性善隨人之所好，此乃先天地之神。", "py": []}, {"t": "《隂符經》曰：人知其神而神，不知不神而所以神也。大修行人，先明此神而敬憚之，若能明了，即神仙矣。", "py": []}, {"t": "此神之功能，驅用四心神、四智神、八識神，非特能用，又能使之變化：八識變爲八金剛，四智化爲四菩薩，四心化爲四佛。", "py": []}, {"t": "一名紇利陀耶佛，二名阿賴陀耶佛，三名質多耶佛，四名乾栗陀耶佛。四智菩薩：一名大成就菩薩，二名妙觀察智菩薩，三名平等性智菩薩，四名大圓鏡智菩薩。八識金剛：色識金剛，聲、香、味、觸、法識金剛，傳送識金剛，含藏識金剛。道呼神帝，神名衆多。不知修鍊底人，反爲此神所役，安能驅駕而用之哉？", "py": []}, {"t": "《黄庭經》云：仙人道士非有神，積精累氣以爲真。又云：方寸之中謹蓋藏，精神還歸老復壯。純陽祖師云：精神氣血歸三要，南北東西共一家。又云：精養靈根氣養神，此真真外更無真。曹真人云：比來修鍊賴神氣，神氣不安空辛苦。又云：神是性兮氣是命，神不外馳氣自定。虚靜天師云：神若出便收來，神返身中氣自回。白真人云：此神即非思慮神，可與元始相比肩。是皆不外神、氣、精三物。", "py": []}, {"t": "是以三物相感，順則成人，逆則生丹。何謂順？一生二，二生三，三生萬物，故虚化神，神化氣，氣化精，精化形，形乃成人。何謂逆？萬物含三，三歸二，二歸一。知此道者，怡神守形，養形鍊精，積精化氣，鍊氣合神，鍊神還虚，金丹乃成。只在先天地之一物耳。", "py": []}, {"t": "要此物至，却憑先天地之神功，役用八識神，使之採丹取鉛，隄防固濟，傳送保護，皆其力也。八識之中，有法識神，主人之意，意行即行，意止即止；又平等性智菩薩，主傳送識金剛；又大圓鏡智菩薩，主含藏識金剛。皆聽意神，以主之意，使之去則去，使之來即來。下工之初，全仗此神以鍊丹，故曰神仙雖得，此神要知其家。", "py": []}, {"t": "《金丹歌》曰：身譬屋兮，屋譬身，却將居者比精神。又云：中央神室本虚閑，自有先天真氣到。《資生經》曰：臍下三寸爲下丹田，方圓四寸，著於脊梁，兩腎中間，左青右白，上黄下黑，中央赤色，名曰大海，貯其血炁，亦名大中極，言人身上下四向最爲中也。中央正位，即丹田，金胎神室也。", "py": []}, {"t": "《金碧經》曰：神室者，丹之樞轄，衆石之父母，砂汞别居，出陽入隂。又曰：神室用施行，金丹然後成。又曰：神室設位，變化在乎其中矣。神室者，上下釜也；設位者，列雌雄配合之宻也；變化者，謂鉛汞之用也。", "py": []}, {"t": "我師曰：聖人恐泄天機，道家以妙有真空爲宗，多借喻曰朱砂、水銀、紅鉛、黑汞、嬰兒、姹女、丁公、黄婆、黄芽、白雪等類。近於著實，致令迷人妄亂猜度，學人將似是而非者執以爲有，却謂金母是圓、外藥，滯於有形滓質，採戰穢行，而終莫悟真空之妙。", "py": []}, {"t": "釋氏以妙空不空爲宗，多喻之曰狐孫、狗子、露柱、刹竿、黄花、翠竹、棒、拂、花草、燈籠、佛殿、西江水、趙州茶等類，全無意義，使人不可解悟。學者思之不得，議之不及，遂云禪機，因執爲無，流於頑空，靜坐入定，出神，而終莫悟不空之妙。豈知禪憂頑坐，道怕傍門？學佛修仙，一件事大。我自得師一言之下，如光明鏡挂於高堂，物去物來，無不照了，今特指出一條大路，共諸人行。", "py": []}, {"t": "彭真人云：一日可以奪四千二百二十年天地正氣。無名子曰：天一生水，在人曰精；地二生火，在人曰神。大修行人，早用妙意觀察智菩薩，役使紇利陀耶佛，八月初三夜，子癸時，急走西川，採鉛取金，疾駕白虎，與傳送識金剛一同回還，付與妙觀察智菩薩，送歸神室，與勾陳神君、螣蛇神君而同收貯，關鎖封固。", "py": []}, {"t": "初則虎龍交戰，後則龍虎降伏。妙觀察智菩薩，與乾栗陀耶佛，戮力同心，不可暫離，日夕衛護。如此保顧，十月之後，却有一箇金色頭陀，道曰上陽真人，在内作主，二佛仍前照管，不使輕離遠出。", "py": []}, {"t": "一周二載，二佛分付與上陽真人之後，方可受賞言功。正陽翁曰：縱横天地不由親，其是之謂也。章思廉《出神訣》云：得太極全體，見本來面目，先天一點真，後天却是屋。吕祖師云：九年火候真經過，忽爾天門頂中破，真人出現大神通，從此天仙可相賀。", "py": []}, {"t": "後天地之神，及先天地之神，億乘萬騎，隨逐已成真人，同駕雲駢，逕詣三清，均受仙秩，是之謂白日昇天，也是云大丈夫之事畢也。上陽子金丹大要卷之四。", "py": []}]}, {"h": "卷之五", "paras": [{"t": "上陽子金丹大要卷之五(六同/卷)睦四。紫霄絳宫上陽子觀吾陳致虚撰。金丹妙用章。《金碧古文》：丹術著明，莫大乎金火。金火者，真鉛也。又云：元君始鍊汞，神室含洞虚，玄白生金公，巍巍建始初。又云：神室用施行，金丹然後成。伯陽真人曰：金來歸性初，乃得稱還丹。", "py": []}, {"t": "上陽子曰：金者，非云金也，指鉛以爲金也。鉛乃金銀之祖，故總題爲金。蓋非世上金寳之金，非從凡間土石中出者。此金乃先天之祖氣，却生於後天。大修行人，擬太極未分之前，體而求之，即造真際。是以高仙上聖，於後天地已有形質之中，而求先天地未生之氣，乃以此氣鍊成純陽，故名曰丹。", "py": []}, {"t": "夫純陽者，乾也；純隂，坤也；隂中陽者，坎也；陽中隂者，離也。喻人之身，亦如離卦，却向坎心取出陽爻，而實離中之隂，則成乾卦，故曰純陽。以其坎中心爻屬金，故曰金丹。須求先天未形者是。若後天地已有形者，人也、物也，非金丹也。然又非金、非鉛、非銀，乃其氣也。我師縁督子所以云先天一氣自虚无中來者，此也。", "py": []}, {"t": "《黄庭經》：天迴紫抱，黄入丹田，幽室内明，照陽門。又云：呼吸元氣以求仙。魏師吕《先天大學書》曰：聖人能返一氣，而歸根復命，與元神道合，生生無窮，緫括萬象，謂之得一，强名曰丹，非法術也。是乾道變化，隂陽不測，太極無上至真之妙，包含性命之宗，謂之金液歸真、形神俱妙之道，至簡至易，一得永得。得其口訣，雖至愚小人，立躋聖位。要之，所謂神仙者，以能殺隂而迴陽，抱神以致仙也。", "py": []}, {"t": "丹陽翁曰：性定則情忘，體虚則氣運，心死則神活，陽盛則隂消。大修行人，既得真師盟授，趁早分去身中之隂，而歸至真之陽也。瑩蟾子曰：一切常人，分陽未盡則不死；大修行人，分隂未盡則不仙。蓋念慮絶則隂消，幻縁空則陽長，故隂盡陽純，則金丹藥熟，丹熟則飛神仙境，此謂之神仙矣。", "py": []}, {"t": "藥物妙用章。《黄帝》曰：人，萬物之盜。又曰：日月有度，大小有數，聖功生焉，神明出焉。《金碧經》曰：鍊銀於鉛，神物自生。《叅同契》曰：同類易施功，非類難爲巧。丹陽祖師曰：神氣是性命，性命是龍虎，龍虎是鉛汞，鉛汞是水火，水火是嬰姹，嬰姹是真隂真陽。紫陽翁曰：嚥津納氣是人行，有藥方能造化生。鼎内若無真種子，猶將水火煑空鐺。又云：要知産藥川源處，只在西南是本郷。", "py": []}, {"t": "上陽子曰：從古到今，上聖列仙，留下丹經，不肯明示藥物一件。其間所指金、木、水、火、鉛、汞、砂、銀，此皆譬喻，而凡俗直以煅鍊爲事，却將凡鉛、水銀、砂、硫爲其藥物，以盲引盲，可勝憐憫。吾今分明與世泄露：夫藥物者，須知此藥從物中出，非凡世金石草木之類，亦非有形有質之數，却又在有形之中而得。似金非世金，似水非凡水。亦有内藥，亦有外藥。", "py": []}, {"t": "夫外藥者，坎中求先天真一之水，水中取先天未擾之鉛，鉛中採先天太一之氣。此氣即黑中之白、隂中之陽也。", "py": []}, {"t": "《悟真篇》云：取將坎位中心實者，是也。蓋真一之水，即真一之精氣。此氣爲天地之母、隂陽之根、水火之本、日月之宗、萬物之祖。《契祕圖》曰：坎爲水、爲月，在人爲腎，腎藏生精，精中有正陽之氣，炎升于上。精隂氣陽，故鉛柔而銀剛。虎性屬金，而金能生水，顛倒取之，母隱子胎，故虎向水中生。虎乃配鉛，是謂隂中之陽也。此上宫外藥者也。", "py": []}, {"t": "夫内藥者，離中求先天真一之液，液中行先天久積之砂，砂中運先天至真之汞。此汞即白中之黑、陽中之隂也。《悟真篇》云：點化離宫腹裏隂，是也。《契祕圖》曰：離爲火、爲日，在人爲心，心藏生血，血中有真一之液，流降于下。血陽液隂，故砂陽而汞隂。龍性屬木，而木能生火，顛倒取之，母隱子胎，故龍從火裏出也。龍亦配汞，是謂陽中之隂也。此止言内藥者也。", "py": []}, {"t": "瑩蟾子曰：大凡學道，必先從外藥起，然後及内藥。高上之士，夙植德本，生而知之，故不鍊外藥，便修内藥也。内藥者，無爲而無不爲也；外藥者，有爲而有以爲也。内藥，則无形无質而實有；外藥，則有體有用而實无。外藥者，色身上事；内藥者，法身上事。外藥是地仙之道，内藥是天仙之道。外藥了命，内藥了性。夫惟道屬隂陽，所以藥有内外。", "py": []}, {"t": "无名子曰：離外陽而内隂，坎外隂而内陽。以内陽點内隂，即成乾卦。喻如金丹，是至陽之氣，結在隂海之中，取來點己之隂汞，即爲化純陽之身矣。上陽子羞不得兩片皮，說又說不厭煩，留丹訣令後來皆通徹。", "py": []}, {"t": "海蟾翁《金丹歌》：若要超凡入聖處，无出隂陽二品丹。陽丹須得先天寳，中有五色包至道；隂丹須認先天氣，常以性根護命蔕。陽丹者，即外丹也，即外藥也。造化在二八爐中，不要半箇時辰而生，立得成就。", "py": []}, {"t": "此即先天地真一之氣，號曰真鉛，又曰華池神水真金。故真一子曰：未有天地混沌之前，真鉛得一以先形，而漸生天地、隂陽、五行、萬物也。大修行人，採此真鉛，歸于懸胎鼎内，點汞入室，是謂外丹也。", "py": []}, {"t": "隂丹者，即内丹也，即内藥也。大修行人，既得外丹入鼎，却行隂陽符火，運用抽添，以温養之。丹陽祖師云：心液下降，腎氣上昇，至于黄房，氤氲不散，則丹聚矣。", "py": []}, {"t": "《悟真篇》云：謾守藥爐看火候，但看神息任天然。神息者，即莊子云真人之息以踵，即廣成子云：丹竈河車休矻矻，鶴胎龜息自綿綿。此龜息、踵息、神息，名雖殊而用之則一。此即謂之真火，以爲内藥也。餌丹之後，非真火无以育聖胎，是以坐看神息。", "py": []}, {"t": "夫天一生水，在人曰精；地二生火，在人曰神。人之精神，營衛一身，運隂陽，合呼吸。以呼吸用神氣，以神氣取水火，以水火鍊胎息，胎息綿綿，游泳坎離，坎離交感而生金液，金液還而丹成也。", "py": []}, {"t": "鼎器妙用章。《隂符經》曰：爰有奇器，是生萬象。太上曰：當其無，有器之用。《龍虎上經》：圓中高起，狀似蓬壺，關閉微宻，神運其中，爐竈取象。《黄庭經》云：出入二竅合黄庭，呼吸虚无見吾形。伯陽真人云：此兩孔穴法，金氣亦相胥。紫陽真人云：先把乾坤爲鼎器，次搏烏兔藥來烹。", "py": []}, {"t": "上陽子曰：鼎器之名，非但一說，匪遇聖師，難可擬議。曰乾坤鼎器，曰坎離匡郭，曰玄關一竅，曰太一神爐，曰神室黄房，曰混元丹鼎，曰陽爐，曰隂鼎，曰玉爐，曰金鼎，曰偃月爐，曰懸胎鼎，曰二八爐，曰朱砂鼎，曰上下釜，曰内外鼎，曰黄金室，曰威光鼎，曰東陽造化爐。名雖多，而所用亦别。", "py": []}, {"t": "且如内鼎、外鼎之說：内鼎者，即下丹田，在臍之下三寸。一曰臍後腎前，一曰前對臍、後對腎，一曰臍之下、腎之上。凡此說者，猶暗中而射垛也。有道之士，只要認取下丹田之極處爲準。蓋下丹田，是神氣歸藏之府，方圓四寸，一名太中極。太中極者，言當一身上下四向之中，故曰太中極也。大海者，以貯人一身之血氣，故曰大海。", "py": []}, {"t": "《悟真篇》云：真精既返黄金室，一顆明珠永不移。李清庵云：乾宫交媾罷，一點落黄庭。即此内鼎神室也。", "py": []}, {"t": "外鼎者，亦名谷神，亦名神器，亦名玄關，亦名玄牝之門，亦名衆妙之門，亦曰有無妙竅。凡此數者，猶聾人而聽管籥也。有道之士，只要認其經營採取之所。紫陽真人云：要得谷神長不死，須憑玄牝立根基。葉文叔註，以玄牝爲兩腎中間混元一穴。無名子題曰誤矣。殊不知玄牝乃二物也，若無此二物，安能有萬物哉？故内外二丹，從此而得。聖人祕之，號偃月爐、懸胎鼎也。", "py": []}, {"t": "《叅同契》鼎器歌：圓三五，寸一分，口四八，兩寸唇，長尺二，厚薄匀，腰臍三坐垂温，隂在上，陽下奔，首尾武，中間文，始七十，終三旬，二百六，善調均，隂火白，黄芽鉛，兩七聚，輔翼人。《悟真篇》首云：周圍一尺五寸，中虚五寸，長一尺二寸，狀似蓬壺，亦如人之身形，分三層，應三才。爐面周圍一尺二寸，明心横有一尺，立唇環匝二寸，唇厚二寸，爐口偃開，鍋釜如仰月狀。張隨號爲偃月爐。此上言外爐也。", "py": []}, {"t": "仙師之意，借物爲喻，使後來人易於領悟。只如「圓三五，寸一分」，此非真師詳誨，豈有自知？況其下文，多少深意。如葉文叔自叙，丹丘有遇，了然明白。豈謂玄牝之說，不得師傳，妄意紬度，果何益哉？後之學人，既蒙師授，當明大要，不可尋文而泥象也。", "py": []}, {"t": "又詳隂爐、陽鼎之說：偃月爐者，隂爐也，中有玉蘂之陽氣，即虎之弦氣也。何謂偃月？蓋此爐之口，偃仰之間，如偃月之狀，隂海是也。先天自然真一之火，月生日長於其中，是曰隂爐也。朱砂鼎者，陽鼎也，中有水銀之隂氣，即龍之弦氣也。號曰懸胎，以其不著於地，如懸於竈中。此鼎入爐八寸，身腹通直，是曰陽鼎也。似此之類，皆不可泥文，切須尋其義也。", "py": []}, {"t": "採取妙用章。《隂符經》曰：其盜機也，天下莫能見，莫能知。君子得之固窮，小人得之輕命。", "py": []}, {"t": "《黄庭經》云：玄膺氣管受精府，急固子精須自持。《叅同契》曰：採之類白，造之則朱。又曰：昴畢之上，震出爲徴，陽氣造端，初九潜龍。《金碧經》曰：磁石吸鐵，隔礙潜通。正陽翁曰：有無交入爲丹本。紫陽真人曰：鉛遇癸生須急採。又曰：甘露降時天地合，黄芽生處坎離交。朱震《易傳》云：晦日朔旦，坎月離日，會于壬癸。又云：三日暮，震象月出庚。", "py": []}, {"t": "上陽子曰：看書要達古人意，若只念字，又何益？且如日月會壬癸、三日之暮、震始生，此固不可以清曉，況只尋常看過乎？謂如有無交入、癸生急採、天地合、坎離交，此無真師口授，强猜不得，是云真實希有之妙義也。", "py": []}, {"t": "何謂交？曰：交以不交之交。何謂合？曰：合以不合之合。何謂採？曰：採以不採之採。何謂不採之採？曰：擘裂鴻濛，採以不採之採。何謂不交之交？曰：鑿開渾敦，交以不交之交。何謂不合之合？曰：恍惚窈冥，合以不合之合。蓋鴻濛未判，須尋太易之先；渾沌既分，則究癸生之際；窈冥無象，以求其真。", "py": []}, {"t": "何謂鴻濛？曰：形如雞子之初，比似中黄之義。何謂渾混？曰：月出庚申之上，震生昴畢之方。夫雞卵分形，知未始太極之肇；庚方月現，推癸生復至之時。何謂恍惚窈㝠？曰：勸君窮取生身處，種向乾家交感宫。無名子曰：癸生者，時將丑也。紫陽翁云：白虎首經至寳，華池神水真金。象川翁曰：癸日子時急採，不得逾時。是言採取也。", "py": []}, {"t": "但癸與子，非天干地支之擬；又復與震，非易中爻上之文。吾所謂大要者，如坎離會、癸月出、震生、恍惚、窈冥、雞子、大易，皆於人身求之，是以冬至不在子也。", "py": []}, {"t": "上陽子曰：今之言採取者，當明以何物爲採取之具，何者爲採取之神也。縁督子曰：人之靈明知覺者，即無也，神也；絪緼活動者，即有也，氣也。正陽祖師曰：鑽天入地承誰力？妙用靈通須是神。蓋是者，此也。神者物也，言必須以此物爲採取之家具也。", "py": []}, {"t": "丹陽翁曰：速把我人山放倒，急將龍虎穴衝開。《叅同契》曰：耳目口三寳，閉塞勿發通，真人潜深淵，浮游守規中。此皆專心致志，躬己以聽命也。又曰：離炁納營衛，坎乃不用聦，兌合不以談，希言順鴻濛。三者既關楗，緩體處空房，委志歸虚無，無念以爲常。此則言去我之聲色言語，而有所待也。", "py": []}, {"t": "當其採藥之時，關防愼宻，謹戒尤切。在易之復卦，曰：復，其見天地之心乎？又曰：先王至日閉關，商旅不行，后不省方。此易中之謹戒也。《指迷詩》云：塞兌垂簾寂默窺，滿空白雪亂叅差，慇懃收拾無令失，竚看孤輪月上時。兊者，口也；簾者，目也；白雪者，外丹也。此正陽翁令後人於採取之際，當如此而謹戒者也。", "py": []}, {"t": "廣成子謂黄帝曰：愼汝内，閉汝外，多知爲敗。我爲汝遂於大明之上矣，至彼至陽之原也；爲汝入於窈冥之門矣，至彼至隂之原也。又曰：彼其物無窮，而人皆以爲終；彼其物無測，而人皆以爲極。上陽子曰：以爲極者，立人之極也。至陽、至隂之原，即無窮、無測之門，玄牝是也。", "py": []}, {"t": "紫陽真人曰：但將地魄擒朱汞，自有天魂制水金。地魄者，虎之弦氣，坎中之陽也；天魂者，龍之弦炁，離中之隂也。虎爲鉛、爲君、爲主，故先取之，將來擒汞；龍爲汞、爲臣、爲賔，故後用以制鉛。是故虎以隂中之陽火，烹鍊乾龍，龍即發陽中之隂火以應之，鉛汞相併，和合凝結了，即時餌歸金室。古仙詩曰：香從臭内出，甜向苦中來。", "py": []}, {"t": "正陽翁曰：及夫採藥，於九宫之上得之，而下入於黄庭；抽鉛於曲江之下，般之而上昇内院。玉液、金液，本還丹，般運可以鍊形，而使水上行；君火、民火，本煉形，般運可以燒丹，而使火下進。五氣朝元，般運各有時；三花聚頂，般運各有日。神聚多魔，般真火以焚身，則三尸絶迹；藥就海枯，運霞漿而沐浴，則入水無波。", "py": []}, {"t": "又曰：龍虎相交而變黄芽，抽鉛添汞而成大藥。玄武宫中而金晶纔起，玉京山下而真氣方昇。走河車於頂上，灌玉液於中衢，起龍虎而飛金晶，養胎仙而生真炁。", "py": []}, {"t": "上陽子曰：聖師接人，唯恐不至。且修鍊事大，既非燒煑而下手，採取又不得而聞見也。其言採取者，採何物也？取何等也？吾今重爲顯說：夫採取者，採先天之氣，取真一之鉛，採坎中之爻，取水中之虎，採黑中之白，取隂中之陽。却非傍門採精取血，又非入室補腦還精，非用靈柯一深九淺，又非三峰採戰穢行。彼皆一等濁俗愚夫，不求真師，迷迷相指，非唯自失，並害道真。", "py": []}, {"t": "大修行人，須究生身，明太極已前之心，叅造化未始之妙。晦朔屏耀，月映太陽而復明；西南得朋，光吐庚方而成震。究竟到此，則知人禀先天虚無窈冥真一之氣而生者也，則知母之復有母也，則知真鉛之宗祖也。", "py": []}, {"t": "何謂真鉛宗祖？夫渾淪已判，乾乃成巽，久變爲離，而其真陽寄于坎中，是以坎中之金，元屬於乾，此爲真鉛之宗祖也。何謂母之母？在天地未根之前，有物混成之中，含靈至妙之瑞，此爲母之有母也。", "py": []}, {"t": "大修行人，既明採取，又悟生身，須攷氣候。且一月之中，止有一日；一日之内，唯在一時；一時之中，分爲六候，止用二候，以爲採取。則一時中，尚餘四候，四候之内，却名合丹。合丹之妙，急以己汞合鉛。於斯時也，調和真息，周流六虚，自太玄關逆流，至天谷穴，而吞入黄金室也。斯乃元年起火，下手之工。", "py": []}, {"t": "故真一子曰：立剏鼎器，運動天機，初則全無形質，一如鴻濛混沌之中。既經起火運符，便應元年滋産。《叅同契》曰：冠婚氣相紐，元年乃芽滋。是爲受氣之初也。古歌曰：黄芽鉛汞造隂殻，含陽華。是謂之男子懷胎也。端坐面壁之功，於此乎見。上陽子金丹大要妙用卷之五。", "py": []}]}, {"h": "妙用卷之六", "paras": [{"t": "上陽子金丹大要妙用卷之六。紫霄絳宫上陽子觀吾陳致虚撰。", "py": []}, {"t": "真土妙用章", "py": []}, {"t": "伯陽真人曰：土遊於四季，守界定規矩。龍虎經曰：土德以王，提劎偃戈，以鎮四方。又曰：坎雄金精，離雌火光。金火相伐，水土相剋。土王金鄉，三物俱喪，四海輻凑，以置太平，並由中宫土德黄帝之功。", "py": []}, {"t": "又云：玄女演其序，戊己貴天符。又云：丹砂流汞父，戊己黄金母。紫陽真人曰：離坎若還無戊己，雖含四象不成丹。又云：木金間隔會無因，須假黄婆媒娉。上陽子曰：五行無土則不全，五金無土則不生，五穀無土則不實，金丹無土則不成。", "py": []}, {"t": "是以乾坤四向有土：東有氐土，南有柳土，西有胃土，北有女土，而復與日月同於四正之宫。此星宿中定位之土：坎中女土爲戊，離中柳土爲己，比爲金丹之象也。一年四季，分土而居，唯獨夏末秋初，土王適用。非土之用，則金不生。", "py": []}, {"t": "五行之中，以木剋土，然木非土，豈能生也？今以鉛汞砂銀土之五行爲言：鉛本生於兌，而母隱子胎，却於坎中求之，蓋坎中有戊土者也。故以鉛投汞，即流戊就己之義也。", "py": []}, {"t": "言戊土與己土一處相交，則金花自結，却吞入腹中，此爲飲刀圭也。刀者，乃戊土中之鉛也；圭者，乃戊己二土合爲一圭也。", "py": []}, {"t": "離中己土，輔日之光，居於午上，故夏日熱而冬日暖。午爲隂之首，而日爲陽，是以己土乃陽中之隂，象龍之弦氣也。坎中戊土，助月之華，居於子上，故冬日暄而夏夜涼。子爲陽之首，而月爲隂，是以戊土乃隂中之陽，象虎之弦氣也。", "py": []}, {"t": "龍虎懷戊己之真土，是以龍虎交而戊己合，戊己合而鉛汞會，鉛汞會而還丹結也。大修行人求其意而莫泥其文也。且求意當求意外之意，叅玄要悟玄中之玄，何也？", "py": []}, {"t": "上陽子曰：金丹大事，全仗戊己二土者也。迷之則雲泥異路，悟之則針芥相投。喻如兩君相見，中有賔相；兩國交兵，中有通好。又如天上鵲橋，人間渡子。又如百萬兵衆，必有將軍；偃武修文，必有宰執。", "py": []}, {"t": "故號之爲黄婆，名之爲媒娉。指戊土爲河車，是有守疆界之說；指己土爲牛車，是有定規矩之妙。但金丹所言，各有其事，所用各有其時。真仙上聖，欲提後人於火坑之中，使知有金丹之道，可以長生度世者矣，故託名借喻，令人易悟。", "py": []}, {"t": "是悟真篇云：赤龍黑虎各西東，四象交加戊己中。其謂金丹出於戊己也。蓋戊己相合，坎離自交，龍虎二物居於戊己之中，頃刻凝結真精一粒，即餌歸黄金室内，却運隂陽符火，鍊成純陽也。", "py": []}, {"t": "王道云：日有三照，月有三移。日月出於東而光耀於西，則西方白虎金德之正氣，入於玄冥之内，化而爲六戊。日月入於西而光耀於東，則東方青龍木德之正氣，入於玄冥之内，化而爲六己。日月當於午而光耀於北，則南方朱雀火德之正氣，入於冥玄之内，就土成形，化爲黑鉛，常居天地杳冥之先，爲天地萬物之根本，爲金丹之祖炁也。", "py": []}, {"t": "火候妙用章", "py": []}, {"t": "金碧經曰：發火初温，微亦如爻動時。悟真篇云：縱識朱砂及黑鉛，不知火候也如閑。王道云：金液神丹，全在火候。火是藥之父母，藥是火之子孫。魏師吕曰：夫能盡性命之道者，無出於黄帝金丹。金丹之妙，在乎火記；火記之妙，象乎坎離，相交而生變化神明也。是以大修行人不知鉛汞火候，則不能成丹，明矣。昔崔翁授純陽祖師天元入藥鏡，是必令其究火功，學者當宜盡心。", "py": []}, {"t": "道光禪師云：聖人傳藥不傳火，從來火候少人知。莫將大道爲兒戲，須共神仙子細推。泥丸真人云：掃除末學小技術，分别火候採藥物。只取一味水中金，收入虚無造化窟。捉將百脉盡歸元，脉住氣停丹始結。", "py": []}, {"t": "黄庭經曰：知雄守雌，可無老；知白見黑，急坐守。棲雲翁曰：人身有三斗三升火，不得風不著。悟真篇註曰：雄裏雌，即龍之弦氣，汞是也；隂抱陽，即虎之弦氣，鉛是也。二物相交合，方生黍粒之丹，吞入腹内丹田中，點化陽魂，以消隂魄也。", "py": []}, {"t": "且以一日之中論之：子時一陽生，人之腎中有一陽純精之氣上昇，則進陽火，是爲復卦；午時一隂生，人之心中有一隂至神之氣下降，則進隂符，是爲姤卦。", "py": []}, {"t": "上陽子曰：火候最祕，聖人不傳，今略露之。藥非火不産，藥熟則火化矣；火非藥不生，火到則藥成矣。且火候之奥，非可一槩而論，中有逐即事條，可不明辨之乎？", "py": []}, {"t": "夫金火爲朋而屬西南，故三日庚方，癸陽初生。當是之時，先究叅同契内四十八章之㫖，則知根乎天地之根，母其隂陽之母，是窈冥之内、恍惚之中，水源至清，全無撓動。紫陽翁曰：虚無生白雪，寂靜發黄芽。火候之祕，此其一也。", "py": []}, {"t": "當其採取之際，用武火之時，一時六候，唯用二候，以取藥。火不可毫髮差謬，宜窮叅同契内四十九章之㫖。紫陽翁曰：藥物生玄竅，火候發陽爐。火候之禁，此其一也。", "py": []}, {"t": "雖已得藥入鼎，要明斤兩爻銖，勿致過當傷多。紫陽翁曰：木汞一點紅，金鉛三斤黑。叅同契曰：名曰第一鼎兮，食如大黍米。火候之妙，此其一也。", "py": []}, {"t": "既而真鉛歸于黄金室内，匀十二節，進火行符。魏真人曰：周旋十二節，節盡更須親。火候之用，此其一也。至於添汞抽鉛，鉛盡汞乾，金丹已成，嬰兒將現，契曰：千周燦彬彬兮，萬遍將可覩。火候之全，此其一也。聖師叮嚀後人，以藥物復謹愼，以火候親切，至矣。", "py": []}, {"t": "紫清翁曰：流俗淺識，末學凡夫，豈知元始天尊與天仙地仙，日日採藥物而不停，藥物愈採而無窮也？又豈知山河大地與蠢動含靈，時時行火候而無暫住，火候愈行而不歇也？只此火候與藥物，順之則凡，逆之則仙。古云：五行顛倒，大地七寳；五行順行，法界火坑。", "py": []}, {"t": "紫陽翁曰：白虎首經至寳，華池神水真金。又云：依時採取定浮沈，進火須防危甚。大修行人已得聖師授以真訣，奚可不明火候者乎？古歌曰：鉛爲芽母，芽爲鉛子。旣得金花，捨鉛不使。蓋鉛是中宫金母，繁生真汞，汞結爲丹，鉛則不用。", "py": []}, {"t": "無名子曰：虚心則無我，萬物皆空，清其天若也；實腹則鍊鉛乾汞，無摇其精。精者，汞也。守汞以實其腹，則金玉滿堂矣。即老子云抱一也。一者，丹也。抱一以空其心，心空則塵不立，方其實也：鍊鉛以制之，汞乾形化。于以抱一以空其心，心空神妙，與道合真。修丹之士，未鍊鉛金，無摇汝精；精少則還丹不成。", "py": []}, {"t": "大修行人翁曰：君火、民火，本鍊形般運，可以燒丹，而使火下進，故必有其道矣。水之就下者，理也；顛倒者，則欲其水之炎上。水豈能炎上哉？正陽翁曰：玉液、金液，本還丹般運，可以鍊形，而使水上行，是必有其道矣。此即反隂陽者也。", "py": []}, {"t": "又如居家者則爲主，外來者則爲賔；顛倒者，反以外來底爲主，居家者乃爲賔。一如女之嫁夫者，理也；顛倒者，反以夫而嫁于女，故曰入贅，且名之曰養老之郎也。夫乃外來底，而却爲主矣。此之謂逆取者也，此之謂大修行者也，此之謂逆則成仙者也。若火炎上而水就下，則人也，物也，非仙者也。", "py": []}, {"t": "神化妙用章", "py": []}, {"t": "鍾離祖師曰：訪仙求友學燒丹，精選朱硫作大還。海蟾翁曰：卦行火候周天畢，孕箇嬰兒瑣下田。霹靂一聲從地起，乾户擘開光萬里。翻身撞出太玄關，這回方是真仙子。", "py": []}, {"t": "叅同契曰：寢寐神相抱，覺寤候存亡。顔色浸以潤，骨節亦堅强。排却衆隂邪，然後立正陽。修之不輟休，庶氣雲雨行。淫淫若春澤，液液象解冰。從頭流達足，究竟復上升。往來洞无極，怫怫被容中。", "py": []}, {"t": "上陽子曰：大修行人既得刀圭入口，運己玉芝以養之。凡運火之際，忽覺夾脊真炁上沖泥丸，瀝瀝然有聲，從頭似有物觸上腦，須臾如雀卵，顆顆自腭下重樓，如冰酥香甜甘美之味无比。覺有此狀，乃驗得金液還丹，徐徐咽歸丹田。自此而後，常常不絶。閑目内觀，臟腑歷歷，如照燭，漸次有金光罩體也。", "py": []}, {"t": "泥丸翁云：我昔工夫行一年，六脉已息氣歸根。老子曰：專氣致柔，能嬰兒。此皆言温養也。夫温養者，隳肢體，黜聦明，終日如愚而不違，不可須臾離也。如雞抱卵，暖氣不可間斷，則抽添之功自見矣。", "py": []}, {"t": "抽添者，以鉛制汞之後，逐日運火，漸添汞，汞漸多，鉛漸少，久則鉛將盡，汞亦乾，化而爲丹砂，號曰金液還丹之純陽。則知形化爲氣，氣化爲神，是曰嬰兒，是曰陽神。黄庭經云：瞻望童子生盤桓，問誰家子在我身。正陽翁曰：孩兒幼小未成人，全藉娘娘養育恩。", "py": []}, {"t": "昔宋景定間，有仙藍養素，鍊金液大還，得丹入嶽，懷胎既久，得海蟾翁假李玉谿奉寄一語，乃撫掌大笑，頂門霹靂一聲而去，今嶽山長笑先生是也。純陽祖師云：九年火候真經過，忽爾天門頂中破。真人出現大神通，從此天仙可相賀。到此，則金丹之大事畢矣。", "py": []}, {"t": "上陽子金丹大要卷之六", "py": []}]}, {"h": "須知卷之七", "paras": [{"t": "上陽子金丹大要須知卷之七(八同/卷)睦五。紫霄絳宫上陽子觀吾陳致虚撰。", "py": []}, {"t": "運火行符須知", "py": []}, {"t": "伯陽真人曰：陽燧以取火，非日不生光。方諸非星月，安能得水漿。二氣玄且遠，感化尚相通。何況近存身，切在於心胷。隂陽配日月，水火爲效徴。又曰：性主處内，立置鄞鄂；情主營外，築垣城郭。城郭完全，人物乃安。黄庭經云：作道優游，深獨居，扶養性命守虚無。", "py": []}, {"t": "縁督子曰：今之修道者，不得正傳，不悟平叔未鍊還丹莫入山之語，唯欲避喧求靜，遯世逃人，出妻屏子，離塵絶俗，窮谷深山，獨居孤處，以爲自高，如棄世間法也。", "py": []}, {"t": "無名子曰：夫運火者，先定刻漏，以分子午；次接隂陽，以爲化基。般六十四卦於隂符，鼓二十四氣於陽火。天關在手，地軸形心，回七十二候之要津，攢歸鼎内，奪三千六百之正氣，輻輳胎中。謹戒抽添，精專運用，慮其危，防其險，不使頃刻叅差、分毫差忒，故得外接隂陽之符，内生真一之體。苟或運心不謹，節候差殊，即姹女逃亡，靈胎不結。", "py": []}, {"t": "瑩蟾子曰：採藥初關，先識天癸生時；中關，則知調和真息，周流六虚，自太玄關逆流至天谷穴，交合然後下降黄房，入于中宫。", "py": []}, {"t": "上陽子曰：運火者，運内外之火。火者，藥火也；候者，符候也；將者，符合也。聖人下工鍊丹之初，須知鉛汞兩相逢迎，真一之鉛將至，運己汞以迎之。鉛汞一合，而即得黍粒之丹，餌歸黄金室内，以爲丹頭也。", "py": []}, {"t": "夫運火者，始自復卦，子符起首，疾進陽火，謂之下手用工；而進火謂之野戰。蓋野戰則龍虎交合，是用三分武火，前行短之謂也。行符者，午時姤卦用事，則進隂符，包固陽火於内，故行符謂之罷功守城。夫守城者，以其鄞鄂已立，唯温養沐浴，防微杜漸，是用七分文火，後須長之謂也。然復與姤乎？皆從人身而求，須認自己生身之由，則得之矣，不必執文而泥象也。", "py": []}, {"t": "紫陽真人金丹四百字云：火候不用時，冬至不在子。學者宜子細求之也。", "py": []}, {"t": "朔望弦晦須知", "py": []}, {"t": "縁督子曰：一點陽精，秘在形山，不在心腎，而在乎玄關一竅。學者不識隂陽，不知時候，不能還返，止於自身摸索，而認彼昭昭靈靈之識神以爲真實，轉轉差馳。易曰：與日月合其明，與四時合其序。朱震易傳云：晦日朔旦，坎月離日，會于壬癸。", "py": []}, {"t": "上陽子曰：每月朔旦子時，日月合璧於癸，薄暮會于昴畢之上，此喻火之初生也。當此之時，純隂已極，微陽將生，是謂潜龍。三日之晡，月生庚上，真陽已肇。庚屬西南，易曰：西南得朋，乃與類行。叅同契曰：神功變成震，三日月出庚。蓋是時也，藥物纔生，水源至清，未曾撓動，有氣無質之際，大修行人急向此時，具一隻智慧眼，則而象之。", "py": []}, {"t": "亦如太隂初受一陽之氣，亦似坤之下爻交乾之初爻而爲震，乃比人身純隂而生一陽，即我師云：先天一氣，自虚無中來，點汞而入鼎也。是時鼎内陽氣初布，砂汞立基。紫賢真人曰：一清一濁，金木間隔於戊己之門；一性一情，隂陽會聚於生殺之户。採二儀未判之氣，奪龍虎始媾之精，入於黄房，産成至寳也。", "py": []}, {"t": "八日酉時，月到天心，其平如繩，是謂上弦，得金半斤。龍虎經曰：坤再變成兌，八日月出丁。以像鼎中鉛汞漸結流珠。是時金水氣停，不進陽火，亦無行符，唯沐浴洗心而已。三五爲朢，朢者，日月相射，則隂中三陽已備而成乾，猶月魄得日魂而滿，喻鼎中鉛水壯盛，真陽充滿，火明金旺，將欲成器，是金火之氣與汞固結，汞與其母兩相留戀也。", "py": []}, {"t": "既望平明，月見辛方，乾初變巽，乃隂陽相承之道。始焉則純隂得交微陽而生藥，後則隂包陽氣而成丹。巽乃承領隂符，隂氣漸生，包固陽精，便無動逸，則金砂落于胞中，隂中含陽，是謂歸根也。", "py": []}, {"t": "二十三日平明，月見丙方，坤交乾之中爻而爲艮，鼎中物藥自然凝結。是時隂陽之氣復停不行，隂符亦無進水，唯沐浴滌慮而已，是謂下弦，得水半斤。以上弦金半斤，下弦水半斤，兩弦合一斤之數，以結丹砂。叅同契曰：兩弦合其精，乾坤體乃成。", "py": []}, {"t": "二十八日平明，月現乙方，此時隂陽之氣俱足，金汞結而成胎，坎離運氣於鼎中，周流六虚於象内，此喻金丹之始終也。至于晦日，日復會于壬，則隂極而陽又將生矣。上陽子曰：句裏雖已分明，而學仙子當體於身。晦朔弦望，皆取證於身，不可泥文而著象也。", "py": []}, {"t": "夫月純隂也，不感日之陽氣，安能滅而復生？人亦似月也。當二八少壯之年，鴻濛未判，則陽純而氣全，故其精方勝而欲泄。其未洩之前，是爲純陽，是號真人。故廣成子謂黄帝曰：目無所見，耳無所聞，心無所知，神將守形，形乃長生。一洩之後，即去一陽而交一隂，是變爲離。自此而往，情慾已萌，淳朴已散，精氣日損，損之又損，以至於陽盡而隂純也。", "py": []}, {"t": "夫惟不知金液還丹之道者，待其陽盡隂純，則死矣。唯修行之人，知其還返之妙，於其未盡之際，疾早修行，急急接助，扶救真陽，收領藥火，以鍊還丹而復其命，亦如太隂領覽太陽之氣而復其明也。", "py": []}, {"t": "防危護失須知", "py": []}, {"t": "縁督子曰：學全真者，得師略指門逕，而不知逐節事條；知神氣相依，而不知鉛汞交媾；既知鉛汞交媾，而不知性命混合，妄擬火候進退不知，此皆無成。", "py": []}, {"t": "真一子曰：陽火過刻，水旱不調，則凝冬變爲大暑；或隂符失節，寒暖相侵，則盛夏反爲濃霜。金宫既砂汞之不萌，一鼎則蟲螟之互起。大則山崩地圮，金虎與水龍沸騰；小則雨暴風飄，坎男共離女奔逸。以此觀之，縱識鉛汞二物，不曉火候，不防險危，實徒然耳。", "py": []}, {"t": "上陽子曰：慮險防危，金丹之大事也。昔紫清白真人既得泥丸翁之傳，年已六十四矣，急忙收拾金丹大料，用盡萬苦千辛，既得汞鉛相合，入鼎烹鍊。以其平日天資聦明，是當温養之時，用心不謹，不防其危，不覺汞走鉛飛，無可收救，遂作詩以自解其愠。詩曰：八兩日月精，半斤雲霧屑。輕似一鴻毛，重如千秤鐵。白如天上雪，紅似猩猩血。收入玉葫蘆，祕之不敢洩。夜半忽風雷，煙氣滿寥泬，", "py": []}, {"t": "這般情與味，啞子咬破舌。捧腹付一笑，無使心腦熱。要整釣魚竿，再斫秋筠節。觀此，可不愼歟？若非白真人之堅固，他人安能再整釣竿而斫筠節乎？又得紫陽仙師以金丹四百字授之，令奠關防愼宻，後乃成道。", "py": []}, {"t": "夫慮險防危，不啻一件，自有數說。其初採藥之時，日月歡會，龍虎將交，戰爭之際，真人已潜於深淵，浮游愼守於規中。盖是時也，閉塞三寳，唯當專心致志，否則有喪身失命之事。紫陽翁云：白虎首經至寳，華池神水真金。又云：依時採取定浮沉，進火須防危甚。最爲初關之緊切，此其一也。", "py": []}, {"t": "採取之時，若或隂陽錯亂，日月乖戾，外火雖動而行，内符閉息不應，枉費神功，此其二也。若也火候過差，水銖不定，源流混濁，藥物不真，空自勞神，有損無益，此其三也。既得黍珠入鼎，須要温養保扶。心君苟或未善，即恐火化丹失，此其四也。", "py": []}, {"t": "至有學者，備歷艱難，屢經危險，心膽驚怖，平時在懷。得丹入鼎，切宜驅除，務令盡淨，勿使牽罣舊慮，以亂心君，是謂滌慮洗心，是謂沐浴。偶或留戀，則恐汞鉛飛走，此其五也。及至十月胎完，脫殻换鼎，不能保固陽神，輕縱出去，則一出而迷途，遂失舍而無歸，此其六也。", "py": []}, {"t": "又有丹成之後，且要識真辨僞。若功行未滿，眼前忽見靈異多端，奇特百出，以至生生之事，如有神見，皆能明知。若此等件，是爲魔障已至，並非真實，不可認爲己靈丹聖，兹乃邪僞妖幻，見吾道成，乃欲引入邪宗，以亂吾真。", "py": []}, {"t": "於斯時也，且須堅固智慧，保養全真，此其七也。凡此七件，皆防慮之大者也。有一不防，非但無成，恐致失喪。正陽祖師曰：已證無爲自在心，便須温養保全真。一年沐浴防危險，免見沈淪更用心。吾所以云慮險防危，金丹之大事者也。", "py": []}, {"t": "卯酉刑德須知", "py": []}, {"t": "紫陽真人曰：兔雞之月及其時，刑德臨門藥象之。上陽子曰：兔雞者，卯酉也。學道的人，須知卯酉非止一說：有天地之卯酉，有一年之卯酉，有一月之卯酉，有一日之卯酉，有一時之卯酉。天地之卯酉者：氐房心爲卯，正躔則房日兔；胃昴畢爲酉，正躔則昴日雞也。一年之卯酉者：春分爲卯，時曰中和；秋分爲酉，序曰中秋。", "py": []}, {"t": "一月之卯酉者：初八日爲卯，月滿上弦，酉時月到天心；二十三日爲酉，月留下弦，卯時月在天中。一日之卯酉者：日出爲卯而萬物作，日入爲酉而萬籟息。一時之卯酉者：蓋攢簇之道也。簇一年於一月，兩日半爲六候；簇一月於一日，則一時分六候。故一年七十二候，簇於一日也。是知一年之中止有一日，一日之内止在一時。大修行人須辨時中卯酉，要知一時六候。", "py": []}, {"t": "蓋採藥取鉛，一時六候，惟用二候，猶三停而用一停。而一時之中，尤餘四候，别有妙用。", "py": []}, {"t": "所謂刑德者，二八也。蓋二八者，卯酉也。卯酉是隂陽平分之位：陽爲德，德則萬物生；隂爲刑，刑則萬物死。而卯月乃四陽而二隂，隂道將離而隂主殺，是以卯之二隂，隂已不能勝陽，然殺氣未絶，至是而榆死，故爲刑也。酉乃四隂而二陽，陽道將離而陽主發生，是以酉之二陽，陽雖不能勝隂，然生意尚存，至是而麥生，故爲德也。", "py": []}, {"t": "正陽翁曰：盡是靈冥轉消息，切須專志保初心。", "py": []}, {"t": "沐浴心慮須知", "py": []}, {"t": "指迷詩曰：沐浴之功不在它，全憑乳母養無差。五行和合隂陽順，同坐同行共一家。無名子曰：陽氣到天地之中，隂陽相半，不寒不熱而温，故爲泰卦，不進火候，謂之沐浴。隂氣降天地之中，隂陽相半，不熱不寒而涼，故爲否卦，不進隂符，亦云沐浴也。", "py": []}, {"t": "上陽子曰：沐浴者，適當隂陽相半，鉛汞氣停，隂陽二氣自然交合。於此時也，不必進火，亦不行符，恐反傷丹，唯宜洗心滌慮，以保養之，故謂之沐浴也。", "py": []}, {"t": "且何謂沐浴？大修行人盡將平時憂悲思慮艱苦之心、執著貪愛之念，翛然脫去，渾無一毫牽罣，直要形如槁木，心若死灰，是謂之沐浴也。", "py": []}, {"t": "純陽祖師曰：木性好清靜，保養心猿定。丹陽祖師曰：水中火發休心景，雪裏花開滅意春。又曰：俗人無清靜之心，道人無塵垢之心。是謂洗滌。其時則近卯酉，其卦則云否泰，其候則屬温涼，其象則爲刑德。至此則罷火守城，故謂之沐浴也。", "py": []}, {"t": "叅同契曰：候視加謹愼，審察調寒温。周旋十二節，節盡更須親。崔公入藥鏡云：受氣吉，防成凶。火候足，莫傷丹。天地靈，造化慳。紫陽真人與白紫清云：及其沐浴法，卯酉特虚比，蓋不可執泥外象，當於藥火到時而取也。", "py": []}, {"t": "古歌云：刑德同生殺，加臨二八門。丹砂宜沐浴，神水灌靈根。閉兌留金汞，禁關養魄魂。不須行火候，爐裏自温温。大修行人，工夫到此，可不愼乎？", "py": []}, {"t": "生殺爻銖須知", "py": []}, {"t": "紫陽真人曰：夫鍊金液還丹者，要須洞曉隂陽，深達造化，追二氣於黄道，會三性於元宫，攢簇五行，合和四象，龍吟虎嘯，夫唱婦隨。昔我師曰：學道之士，得内外藥物之真、兩般作用之全，合大造化，方得所傳。苟有毫髮差殊，未免天地懸隔。", "py": []}, {"t": "上陽子曰：生殺者，隂陽二物也，龍虎二物也。龍乃陽中之隂而主生，故興雲致雨，潤澤萬物，而其中之隂，能殺者也，猶人分陽已盡而純隂則死矣。", "py": []}, {"t": "虎乃隂中之陽，主殺，故呼風哮吼，常有殺心，而其中之陽，能生者也，猶人分隂已盡而純陽則仙矣。夫隂陽二物者，順則成人，逆則生丹，故不爲萬物、不爲人，則成丹矣，是所謂生也。", "py": []}, {"t": "且道生，又生箇什麽？莫不是生天生地？莫不是生人生五行？莫不是生萬物者乎？莫不是有大靈通智慧、有大神聖變化者乎？且道殺，又殺箇什麽？莫不是殺那無明煩惱底賊？莫不是殺傍門愚癡底賊？旌陽祖師以五童女劎殺之，純陽帝君以三清劎殺之，佛祖以金剛王寳劎殺之，德山和尚以入門棒殺之。故云：護生須是殺，殺盡始安居。", "py": []}, {"t": "祖師云：斬魑滅魅了長生。魑者，癡也；魅者，昧也。若人早早殺了這愚癡暗昧底，則可以畢長生之道矣。大修行人定知毫髮差殊，不能成丹，切須洞曉也。若悟隂陽生殺二物，何憂不仙矣？", "py": []}, {"t": "至如所謂卦象爻銖之說：銖也者，將准之而定也；爻也者，將傚之而用也；象也者，將像之而爲也；卦也者，猶挂以示人，使人以此而爲則例也。", "py": []}, {"t": "爻與銖者，明輕重也；象與卦者，明進退也。積三百八十四爻，而成六十四卦；積三百八十四銖，而成一十六兩，謂一斤也。斤足卦滿，喻丹之將成也。", "py": []}, {"t": "修行之人，務在知輕識淺、知重識深、知難識退、知易識進，不過以法金丹内外二藥也。道德經云：有無相生，難易相成。又曰：圖難於其易，爲大於其細。又曰：是以聖人猶難之，故終無難也。", "py": []}, {"t": "猶以復震爲採藥之初，則半斤爲入藥之數。如百爻之謂，以三十爻爲文、七十爻爲武者，則知採藥之難也。以卦足而藥成，則丹足二八一斤之數。故火記言二百一十六，乃乾之策也；十八八箇足，乃一百四十四，坤之策也。隂陽之數既足，金液之丹已成也。", "py": []}, {"t": "上陽子金丹大要須知卷之七", "py": []}]}, {"h": "須知卷之八", "paras": [{"t": "上陽子金丹大要須知卷之八。紫霄絳宫上陽子觀吾陳致虚撰。", "py": []}, {"t": "脫胎换鼎須知", "py": []}, {"t": "崔公入藥鏡曰：盜天地，奪造化。又曰：初結胎，有本命；終脫胎，看四正。紫陽翁云：節氣既周，脫胎神化，名題仙籍，位號真人。此乃大丈夫功成名遂之時也。紫清真人曰：夫金丹者，採二八兩之藥，結三百日之胎。心上工夫，不在吞津嚥氣；先天造化，須當聚氣凝神。若也行持，惟憑口訣，至簡至易，非色非空，無中養就嬰兒，隂内鍊成陽氣。", "py": []}, {"t": "上陽子曰：大修行人既感真師傳授，若其未得真鉛，先當收拾自己精神，不可恣情縱慾。凡於日用應與之間，似有如無，忘情絶念，以待藥火之至。故純陽祖師云：七返還丹在人先，須鍊己待時。葛仙翁清靜經云：人能遣其慾而心自靜，澄其心而神自清，自然六慾不生，三毒消滅。", "py": []}, {"t": "夫人心虚則澄，坐定則靜，寡言希聽，存神保命。蓋多言則損氣，多喜則放情，多怒則觸意，多悲哀思慮則傷神，貪慾勞困則傷精，凡此皆非修行底所宜有也。", "py": []}, {"t": "若得先天真鉛合汞，又喜火候無差，又善温養保扶，均調神息，直至丹熟胎完，嬰兒成就，而成真人。三年九載，立行累功，或留形住世，接物度人，如安期生、藍采和是也；或入仕途，匡時理世，東方朔、竇令君是也；至若七真五祖，慈悲接人，張、葛、許、浮丘諸祖師，乘時救劫，伺詔飛昇者也。", "py": []}, {"t": "大修行人若也再求向上之事，則移胎换鼎，可無難矣。何謂向上事？上陽子曰：前胎完就，已成真人，則移居上丹，却重整乾坤，再造隂陽，子又生孫，千百億化。紫陽翁曰：一載一箇兒，箇箇會騎鶴。泥丸真人曰：一載胎生一箇兒，子生孫，子孫又枝。於此方是大丈夫也。若應時立功，則身歸三清矣。", "py": []}, {"t": "丹陽祖師曰：神滿太虚，一無所礙。故天有時而崩，地有時而陷，山有時而摧，海有時而竭，凡有相者，終歸於壞。唯道成者，神與道合，永劫無壞。又兼功及九祖，則白曰同昇上清矣。", "py": []}, {"t": "續須知七事", "py": []}, {"t": "上陽子曰：道必曰學，學必曰精而已矣。老子曰：吾非聖人，學而得之。孔子曰：十室之邑，必有忠信如丘者焉，不如丘之好學也。曰：我學不厭而教不倦也。曰：君子學道則愛人，小人學道則易使也。", "py": []}, {"t": "南華真經曰：南伯子葵問乎女偶曰：道可得學耶？偶曰：惡！惡可？子非其人也。夫卜梁倚有聖人之才，而無聖人之道；我有聖人之道，而無聖人之才。吾欲以教之，庶幾其果爲聖人乎？不然，以聖人之道而告聖人之才，亦易矣。孔子曰：生而知之者，上也；學而知之者，次也；困而學之，又其次也；困而不學，民斯爲下矣。", "py": []}, {"t": "釋迦聞半偈而欲捨身，黄帝順下風，膝行而進，問廣成子：治身奈何而可以長久？夫古之大聖，亦未有不學而能知大道者乎？今時人也，而多妄誕，不肯下問，何時而得聞斯道也哉？", "py": []}, {"t": "上陽子曰：道有立談，道有心授。君臣也，父子也，兄弟也，夫婦也，朋友也，是綱常之道也。此可以立談，而非心授也。所言心授者：天命之謂性，率性之謂道。此可以心授，而不可以立談也。率性之道，即孔子一貫者也，即孟子集義所生者也。夫綱常之道，雖童稚亦可訓之，惟有國有邦者，置所司以掌其綱常之道，萬世不易者也。", "py": []}, {"t": "至如率性集義之道，前賢註䟽，畧不及焉。若賢人君子，遇聖師口授而不驚疑，以集義率性之道而修之，是則謂之大聖人，方知綱常之道在其中矣。", "py": []}, {"t": "鍊丹也，砂硫也，水銀也，是修鍊之道也。此可以立談，而非心授也。所言心授者：無爲而無不爲也，爲之而有以爲也。此可以心授，而不可以立談也。無爲有爲之道，即金丹之大道也。夫丹爐修鍊，凡砂水銀之道，雖愚夫愚婦亦可鍊之，故可立談。至如先天真鉛有爲之道，雖上士至人，遇師口授，亦不免疑焉。若上士至人，得師指示金丹有爲之道，勤而修之，是之謂神仙也。", "py": []}, {"t": "頑坐也，守性也，持齋也，是坐禪之道也。此可以立談也，而非心授者：唯正法眼藏、涅槃妙心、直指人心、見性成佛之道，此可以心授，而不可以立談也。正法眼藏、直指人心，即最上一乘之道也。夫持齋坐禪，雖庸人孺子，亦可立談。至如一乘之道，雖利根上智，於佛祖言下得證，猶不免疑焉。是以靈山會上，五千退席；五祖佛法，不付神秀而與老盧。是謂可以心授，而不可以立談也。", "py": []}, {"t": "韓湘得仙，而昌黎有收吾骨之句，豈昌黎是下根之器哉？朱晦菴之遍叅，而崔子虚不與以道，豈晦菴之不欲者哉？是云：道不可以立談，可立談者，非大道也。葛仙翁六十始遇師，白玉蟾六十四始遇師，皆成道也，是謂道有心授者也。", "py": []}, {"t": "上陽子曰：道有三悟。孔子翼易曰：近取諸身，遠取諸物。是言道也。大修行人從近與遠、及身與物四者求之，眼下自有悟處。葛仙翁清靜經曰：内觀其心，心無其心；外觀其形，形無其形；遠觀其物，物無其物。是言道也。大修行人從内外遠、及心形物六者求之，目下便有悟處。佛祖云：不是心，不是佛，不是物。是言道也。大修行人從心佛物三者求之，脚跟下即有悟處，是之謂道有三悟也。", "py": []}, {"t": "且夫三教聖師，皆曉以世人從物求道、以道爲物，須當審思，切勿容易看過了也。蓋道者，乃萬物之一物也；而物者，乃大道之一物也。故老子云：有名，萬物之母。又云：淵兮，似萬物之宗。是皆以物而名道也。憫夫一切常人，唯只尋常，不肯尋上：或以孤隂寡陽，攝心兀坐；或以持齋守戒，離俗絶塵；或以凡砂鉛銀，煅鍊爐火。凡此皆誤，而非悟也。能於是編言下投機，須有一箇竒特之大悟處矣。", "py": []}, {"t": "上陽子曰：道有三傳焉。上焉者，文人善士，寡言好善，能棄富貴，唯急於身，是云上士，宜傳道焉。中焉者，質而不文，聞道篤信，能割恩愛，力行精進，不顧是非，是曰中士，乃有上士之志，宜傳道焉。下焉者，愚而信實，樂善棄惡，捨己從人，勇於敢爲，是云下士，其志可尚，宜傳道焉。故得此道者，莫不勇猛精進，莫不堅固智慧，莫不渴惡揚善。夫善之一字，乃入道之梯航也。", "py": []}, {"t": "是以常人耳常聞善，則腎不走精；口常語善，則心不失神；鼻常嗅善，則肺能安魄；眼常視善，則肝能育魂；意常思善，則脾胃生氣，黄中通理。大修行之人，奚可以不善歟？", "py": []}, {"t": "上陽子曰：道有三戒。凡學道者，心雖慕向，而乃驕其富貴，不肯下問，不立盟誓，是謂好譎，戒而莫與。次學道者，畧聞傍門小法，唯事强辯，以逞乾慧，是爲夸眩，戒而莫與。三學道者，疑信相半，不以生死爲憂，重財輕身，是不知命，戒而莫與。", "py": []}, {"t": "上陽子曰：道有三去焉。一者，雖智人材士，而好論狀古人，是謂無德，宜去之也。二者，雖善人勝士，而好詆排是非，妄議今古，是謂不廣，宜去之也。三者，雖好道向佛，而口談心非，背直就僞，是謂無實，宜去之也。", "py": []}, {"t": "上陽子曰：道有四異。四者何也？酒、色、財、氣是也。一切常人，飲少輒醉：平時端莊，化爲戲謔；平時正直，化爲諛侫；平時廉潔，化爲貪淫；平時謙和，化爲狂傲。因酒喪德，逃失性真。猶如山藪所藏者多，平時罔覺，忽然野火，山頳藪爇，千妖百怪，無所逃避。人若無酒，不失所行；山若無火，妖怪藏形。大修行人戒飲靜坐，歛精怡神，不爲酒亂，此爲異耳。", "py": []}, {"t": "世之聲色，敗人者多。一切常人，肆情縱欲，貪著無厭，如彼蜉蝣，以燈爲色，以焰爲樂，投光赴焰，來往不捨，貪著於焰，趨燈而撲。人亦如是，著於愛慾，精氣以竭，而情難割。情牽神失，意動氣散，神氣既喪，命亦隨逝。色之爲物，本無鋒刃，而其殺人，甚於刀戟。大修行人似同而異：酒肆淫房，未嘗不戲，却乃非色爲色、知色不色、不色中色、色無定色，此謂異耳。", "py": []}, {"t": "云何非色爲色？如彼蓮花，香引十里，花却爲色，香即爲聲。大修行人不貴其香，不貴其花，而所貴者唯貴其信，信即爲蓮。花之與香，不能長留，蓮實可久，實能安心，此故云信，是以貴之。故太上云：其精甚真，其中有信。猶此意也。", "py": []}, {"t": "何謂知色不色？如彼河水，清流涓涓，水以濟舟，至于彼岸，其舟與水，悉皆外物。祖師不云：道成而後，丹房器皿，委之而去。此之謂也。何爲不色中色？如彼枯旱，隂雲四興，甘雨聚至，須臾復霽。若乃求其向來雨雲，一無所見，而唯五穀萬物，蒙潤發生。維摩經云：遊諸四衢，饒益衆生；入諸淫舍，示慾之道。此之謂也。", "py": []}, {"t": "色無定色，其義云何？如彼寳月，歲十二度，朔望弦晦，無定之中，而有大定。上陽子曰：當詳論之。三日生兔，色以大定；八日半盈，是云上弦；十五對朢，圓明徧滿。凡彼人間，莫不瞻仰，而其光輝，圓而復缺，乃不長在。若人再欲覩其光彩，須别索求生魄弦望。是故易曰：與天地合其德，與日月合其明。又曰：原始要終，故知死生之說。此之謂無定色也。", "py": []}, {"t": "一切常人貪財無厭，積而不散，爲兒孫計，不悟天地日月盈虚消息之理，如彼石崇，富敵於國，財聚怨結，身戮家喪，禍及緑珠。大修行人既得其財，即以求藥；得藥成丹，丹成而後，盡散其餘。此爲異耳。", "py": []}, {"t": "一切常人爭盡閑氣，惱亂身心，好訟欺貧，量可即奪，不顧因果生死，不悟悔吝凶危，皆由此起。所爭者少，所喪者多，如彼項王，英雄蓋世，卒之烏江，身死尸分，後來視之，爲漢鷹犬。人之所爭，況不及乎？大修行人所爭之氣，非人所知，是先天地真一之氣。上陽子曰：修仙作佛，皆此先天真一之氣。若非是氣，不係修行，不能長生。此爲異耳。", "py": []}, {"t": "上陽子金丹大要須知卷之八", "py": []}]}, {"h": "積功卷之九", "paras": [{"t": "上陽子金丹大要積功卷之九(十同/卷)睦六。紫霄終宫上陽子觀吾陳致虚撰。", "py": []}, {"t": "金丹詩", "py": []}, {"t": "大道從來是强名，隂符道德始存經。神仙次第丹經續，口訣安能紙上明。", "py": []}, {"t": "我以因縁遇聖師，忽於言下大驚疑。方知玄妙無多句，此事如何容易知。", "py": []}, {"t": "特推造化指方來，首捉先天一氣回。先天一氣是何物，不遇真仙莫强猜。", "py": []}, {"t": "氣從四向定生涯，一變水兮二變砂。三變汞兮金四變，五變金丹結紫花。", "py": []}, {"t": "須識玄門與牝門，便安爐鼎定乾坤。内外二丹從此得，休疑大海指崑崙。", "py": []}, {"t": "順則凡兮逆則仙，實非草木與凡鉛。誰知日兔月烏位，却笑他人顛倒顛。", "py": []}, {"t": "月非日映不生光，人亦純隂要復陽。若欲歸根並復命，依他坤體補乾剛。", "py": []}, {"t": "戊坎月鉛氣逐虎，己離日汞火從龍。白鬚老子通神廣，趕虎隨牛過水東。", "py": []}, {"t": "虎之爲物最難言，尋得歸來玄又玄。一陽初動癸生處，此際因名大易先。", "py": []}, {"t": "大易之先藥料真，自然烏兔兩相親。東君切莫離房室，西得朋來是主人。", "py": []}, {"t": "水中之物號金公，遠隔西山幾萬重。黄帝按時宣土德，迎之以意入中宫。", "py": []}, {"t": "一歲簇來一月看，月簇一日又何難。一時六候用唯二，拾取玄珠頃刻間。", "py": []}, {"t": "三百八十四爻銖，反覆隂陽莫道無。大地山河俱是寳，葛仙六十詠流珠。", "py": []}, {"t": "一身上下定中央，腎前臍下號黄房。流戊作媒將就己，金來歸性賀新郎。", "py": []}, {"t": "陽丹結在隂海中，猶如坎裏一爻雄。擒來離内温温養，此即神仙顛倒功。", "py": []}, {"t": "坎中一畫已外離，慾海波澄風浪低。刑德臨門宣沐浴，盈虚消息早防危。", "py": []}, {"t": "八日前弦金半斤，金翁騎虎恐相嗔。過猶不及切須問，𡘫當抽添耐養神。", "py": []}, {"t": "已知隂體得陽暉，和合雌雄入化機。白雪滿空春意動，守形養氣抱嬰兒。", "py": []}, {"t": "胎息綿綿漸漸完，氣沖夾脊觸泥丸。纍纍似彈腭中下，過了重摟香又甘。", "py": []}, {"t": "既達返還九與七，此即木金三五一。氣全神壯换胎時，照護孩提休遠出。", "py": []}, {"t": "性是神兮命是精，要知性命屬心君。精神性命皆隨意，意動人之善惡分。", "py": []}, {"t": "正路當行人未知，呼天吸地驗高卑。觀音尋到脚跟底，閉息之流向此推。", "py": []}, {"t": "求財求侣鍊金丹，財不難兮侣却難。得侣得財多外護，做仙何必泥深山。", "py": []}, {"t": "件件分明說與君，若無物藥也休論。可惜幾多富貴客，僞徒引去說傍門。", "py": []}, {"t": "上士英雄學上仙，積功累行滿三千。脫胎神化尋常事，白曰騰身上九天。", "py": []}, {"t": "判惑歌", "py": []}, {"t": "上陽子聞道遲，四十衡陽始遇師。從來不信長生說，及得師言便釋疑。", "py": []}, {"t": "纔低頭摸鼻孔，方信神仙有真種。乃覺從前萬事非，不道這般真骨董。", "py": []}, {"t": "這骨董、大奥妙，妙在常有觀其竅。此竅分明在眼前，下士聞之即大笑。", "py": []}, {"t": "我得來不敢秘，欲對知音論同異。近來世上幾箇人，空自談天又說地。", "py": []}, {"t": "諸傍門、是邪逕，翠虚吟中略舉盡。除却先天一點真，分外多端總邪正。", "py": []}, {"t": "大道易、不堪論，只將竅妙定乾坤。奈縁失却中心路，傍指三千六百門。", "py": []}, {"t": "有數息、有閉息，於中錯指也無迹。或鍊三黄及四神，或鍊五金並八石。", "py": []}, {"t": "要半夏、用术茯，搜盡藥中諸草木。幾多因此促其生，人參尚有殺人毒。", "py": []}, {"t": "純陽道：張尚書，服藥失明神氣枯。不知還丹本無質，翻餌金石何太愚。", "py": []}, {"t": "欲調息、坐觀鼻，似春沼魚百蟲蟄。其妙無窮在甚處？到老無成何所益。", "py": []}, {"t": "捉一處、存金光，認是丹田也不妨。自己固知行不得，但將此術教它行。", "py": []}, {"t": "體天地、朢日月，二氣吸歸玄牝穴。按摩伸屈恣吐吞，朝暮嘘呵復嚥咽。", "py": []}, {"t": "以土圭定時刻，將謂似是而非實。會教自性有通時，且須觀想以意識。", "py": []}, {"t": "動尾閭、撼夾脊，吞它稠唾及精溺。一生受用大陽丹，專採女人天癸喫。", "py": []}, {"t": "鍊秋石、聚小便，溺便多處是它縁。更把此方爲秘寳，若無財賄不相傳。", "py": []}, {"t": "入淫房、大懊惱，伺候精行轉補腦。如斯謬戾要長生，七祖九玄難作保。", "py": []}, {"t": "食穢惡、及乳溲，試看兩臉曾紅否。更待女男相會合，吞他精血作丹頭。", "py": []}, {"t": "惜性命、全元氣，一吸玉户中精水。老來毫末也無功，却怨壽光黄谷子。", "py": []}, {"t": "頂門響、腹中鳴，此即龍吟虎嘯聲。態伸鳥引空勞力，龜縮鶴舒何足稱。", "py": []}, {"t": "保命訣、用靈柯，隂陽二丹傳大訛。存縮吸抽閉五事，而今此術不勝多。", "py": []}, {"t": "傳達磨、說歸空，觀物知胎語不通。生死定年次月日，臨時更定五心中。", "py": []}, {"t": "八段錦、十號頌，都在無名指上用。驀地浮雲遮日月，大限到來宜穩重。", "py": []}, {"t": "度天魔、隂魔絶，又號天關般弄訣。甲子中宵見子時，運氣七抽放在舌。", "py": []}, {"t": "指天竺胎息經，謂能住世與留形。不知古德無多語，但要人從正路行。", "py": []}, {"t": "恣飮酒、却持齋，或斷煙火不燒柴。前生不布種口禄，却向此生空打睚。", "py": []}, {"t": "頑打坐、只無爲，守箇空屋舊藩籬。早晩不充衣又冷，這般受苦早回思。", "py": []}, {"t": "持素珠、專念佛，見他葷酒欲嘔咳。一心只要向西方，管甚東西與南北。", "py": []}, {"t": "多作法、遍祈禱，有是看經直到老。貪嗔愛慾不能離，安得此生延壽考。", "py": []}, {"t": "現行者切莫用，積取方來業債重。若遇真師急拜投，或者一言便射中。", "py": []}, {"t": "未聞者不須傳，多少傍門亂性天。若要玄中端的處，唯當熟記悟真篇。", "py": []}, {"t": "行脚輩、號禪和，大機大用口頭過。只爭勝負閑言語，不向臺山勘老婆。", "py": []}, {"t": "禪僧家去鬚髮，佛將此相令人察。成行成隊不低頭，見性明心無幾衲。", "py": []}, {"t": "明眼人、見性者，陞坐故將佛祖駡。棒喝指頭機最深，而今把作尋常話。", "py": []}, {"t": "聦明底、談性理，横言强辯唯他是。性與大道有誰明？顔子坐忘曾子唯。", "py": []}, {"t": "誦大學、講中庸，不偏不易朱文公。正心誠意求章句，誠意元非章句中。", "py": []}, {"t": "頂七星、名正一，玄牝之門那箇識。五千餘言道德經，正得一兮萬事畢。", "py": []}, {"t": "居山林、稱道士，不知大道是何事。金丹名也不曾聞，況要教它明生死。", "py": []}, {"t": "雲水客、號全真，却爲朝昏且救身。祖師留下刀圭說，知者如今有幾人。", "py": []}, {"t": "正陽翁指迷歌", "py": []}, {"t": "此道分明事不多，但願人人都解悟。柰縁福薄執迷何？浮生事、水上波。人身已得莫虚過，有縁遭遇明師指，誰謂無由上大羅。", "py": []}, {"t": "詠劎五首", "py": []}, {"t": "尋常莫道黑漫漫，邪怪聞之骨也寒。挂在太虚宜愛護，要將殺虎補龍肝。", "py": []}, {"t": "能活於人有大功，不妨奮迅立威風。十方世界當頭截，變化魔宫作寳宫。", "py": []}, {"t": "三尺鏌鎁倚大空，神威凛凛忒英雄。聖凡不敢抬頭看，一道神光牛女中。", "py": []}, {"t": "非銅非鐵亦非金，不假凡間爐火成。我劎本來天地骨，要知能殺又能生。", "py": []}, {"t": "神仙非劎不成仙，劎匪神仙也不傳。若說金丹靈妙處，其功先立地中天。", "py": []}, {"t": "醒眼詩五十首", "py": []}, {"t": "四十年前事已非，真師縁遇授玄微。從今卸却恩和怨，鍊箇真身跨鶴飛。", "py": []}, {"t": "端有長生不死方，常人縁淺豈承當。鉛銀砂汞分斤兩，德厚恩弘魏伯陽。", "py": []}, {"t": "紆紫拖金列滿朝，荒忙酒盞馬蕭蕭。邇來事事只如此，收取金丹靜處燒。", "py": []}, {"t": "元來世上盡非真，唯有還丹是養身。將相位高憂國事，道人爐内藥苗新。", "py": []}, {"t": "未遇師傳說道難，既聞玄妙却如閑。早將神氣歸金鼎，免死形骸葬野山。", "py": []}, {"t": "鍊丹及早莫遲疑，休待功名到了時。只爲光隂如箭速，吉凶禍福少人知。", "py": []}, {"t": "下手速修已大遲，箇中聞此急回思。喧闐鼓樂鬧何事，前日英雄今裹尸。", "py": []}, {"t": "浮世奔波功與名，道人苦口論修行。丹成回首看浮世，埋没功名荒草生。", "py": []}, {"t": "我昔未聞大道時，起人愛敬最便宜。邇來得箇長生說，路上行人口似碑。", "py": []}, {"t": "掀轟閑氣莫存懷，但把辛勤問藥材。七返九還功行滿，向來閒氣入塵埃。", "py": []}, {"t": "道成之後謗歸塵，謗語端能堅固人。真覺比爲甘露味，古來學道世多嗔。", "py": []}, {"t": "世人冷語不關心，大笑實爲吾道箴。但要神爐添藥火，他時天上有知音。", "py": []}, {"t": "萬善無虧必遇師，須從言下悟玄機。若無善行難遭遇，縱沐師傳未免疑。", "py": []}, {"t": "手把丹經暗裏猜，迴光返照便歸來。就中問箇虚無竅，到選仙場必占魁。", "py": []}, {"t": "莊周鵬志運南溟，一去高飛九萬程。只爲子書多譬喻，後來誰想作丹經。", "py": []}, {"t": "翛翛洒洒大閒人，爲著真鉛奈苦辛。志氣終爲雲外客，還丹問藥合同塵。", "py": []}, {"t": "純陽一闋沁園春，句裏分明藥料真。有箇烏飛曲江上，山頭初月挂庚申。", "py": []}, {"t": "也不看經也不修，却來世上作優游。有時吸盡西江水，鍊箇金輪照九州。", "py": []}, {"t": "總皆凡世播英雄，做盡英雄到底空。唯有金丹最靈妙，大羅天上逞神通。", "py": []}, {"t": "真師訓語復丁寧，八月初三是癸生。此即一陽初動處，若尋冬至枉勞形。", "py": []}, {"t": "烏兔分明顛倒顛，月生庚上有真鉛。金丹只此無難事，莫道仙師不口傳。", "py": []}, {"t": "鍊形化氣氣歸神，不是真陽謾苦辛。擘裂鴻濛分造化，此身身外更求身。", "py": []}, {"t": "不鍊凡間鉛與砂，常提寳劎斬妖邪。有人借問神仙事，一味爐中白馬牙。", "py": []}, {"t": "玉皇若也問丹材，偃月爐中取下來。馳騁英雄吞一粒，男兒懷了一年胎。", "py": []}, {"t": "陽精一點祕形山，言語通時即可還。迷者儘他疑到骨，此中底藴本無難。", "py": []}, {"t": "元來一味坎中金，未感師傳枉用心。忽爾打開多寳藏，木非木也不成林。", "py": []}, {"t": "離内隂爻坤土真，坎中雄者是乾金。當初只爲乾坤順，一死一生直到今。", "py": []}, {"t": "簾幃放下契全真，身外須知别有身。恰是金丹好消息，不爲萬物不爲人。", "py": []}, {"t": "曲江之上月初明，地應於潮天應星。若欲深探玄妙窟，金砂洲對吕仙亭。", "py": []}, {"t": "木金間隔各西東，雲起龍吟虎嘯風。二物寥寥天地逈，幸因戊己會雌雄。", "py": []}, {"t": "降龍伏虎也無難，降伏歸來玉鎖關。日月分明烹鼎内，何憂不作大還丹。", "py": []}, {"t": "無不爲之有以爲，坎中有白要歸離。水源初到極清處，一點靈光人不知。", "py": []}, {"t": "修行人要識黄芽，若會金公却一家。天地未分名太一，此時擘裂産河車。", "py": []}, {"t": "懸胎鼎裏煉流珠，已喜金來歸性初。三教聖人同一轍，後來人我却殊途。", "py": []}, {"t": "白雲無事過前溪，中有神仙未可知。待我玉爐丹九轉，坐乘五色宴瑶池。", "py": []}, {"t": "多少人居富貴叢，到頭富貴只忽忽。不如買取金丹訣，做箇神仙不老翁。", "py": []}, {"t": "得法無財事不全，法財兩足便成仙。丹陽祖是東州富，棄了家財萬萬千。", "py": []}, {"t": "箇中仙子急修行，勤向丹田種又耕。人道金丹富貴客，誰知此内更長生。", "py": []}, {"t": "小隱山林大隱廛，廛中造化妙玄玄。凡人未得廛中說，莫入深山隱洞天。", "py": []}, {"t": "未鍊還丹莫入闤，丹頭多在鬧林間。嬰兒姹女一歡會，却向環中養大還。", "py": []}, {"t": "紅紅白白水中蓮，出污泥中色轉鮮。莖直藕空蓬又實，修行妙理恰如然。", "py": []}, {"t": "一條直路少人尋，風虎雲龍自嘯吟。坐定更知行氣主，真人之息又深深。", "py": []}, {"t": "飢餐渴飲困來眠，大道分明體自然。十月聖胎完就也，一聲霹靂上丹田。", "py": []}, {"t": "醒眼詩中妙更多，勤修趁早莫蹉跎。人身一入輪迴去，來世機縁莫想他。", "py": []}, {"t": "無事常觀醒眼詩，其中奥㫖說刀圭。有人會此醒醒法，便入金門作聖師。", "py": []}, {"t": "曹溪傳法不傳衣，由此燈燈續祖輝。公案半千明佛法，後來却道是禪機。", "py": []}, {"t": "刹竿柱杖酒臺盤，秉拂拈槌總一般。悟了脚跟元踏實，不妨穩去坐蒲團。", "py": []}, {"t": "指頭棒喝趙州茶，爲鬻心肝讚底沙。解悟真禪無半語，青青翠竹對黄花。", "py": []}, {"t": "馬祖磨磚作鏡兒，笑他兀坐要何爲。若還認得西江水，許汝一尊佛出時。", "py": []}, {"t": "佛因半偈舍全身，高證魏巍萬德尊。了得涅槃正法眼，金剛不壞體長存。", "py": []}, {"t": "上陽子金丹大要積功卷之九", "py": []}]}, {"h": "積功卷之十", "paras": [{"t": "上陽子金丹大要積功卷之十。紫霄絳宫上陽子觀吾陳致虚撰。", "py": []}, {"t": "道德經轉語", "py": []}, {"t": "道可道章第一：衆妙應須無以觀，更將有向竅門看。可名物母明明說，兩顆胡珠轉玉盤。", "py": []}, {"t": "天下皆知章第二：美中有喪惡難成，前後相隨高下形。直到無爲方了了，不言之教始分明。", "py": []}, {"t": "不尚賢章第三：弱志須先以骨彊，虚心實腹要當陽。共君說段爐中事，一朵鉛花子細詳。", "py": []}, {"t": "道沖而用之章第四：象帝之先萬物宗，解紛剉銳闡高風。蒼顔老子垂雙手，湛似淵兮道乃沖。", "py": []}, {"t": "天地不仁章第五：不仁乃是大仁人，芻狗民生物化淳。橐籥之中能不屈，當知愈出愈精神。", "py": []}, {"t": "谷神不死章第六：谷神無始立天根，上聖强名玄牝門。點破世人生死窟，神仙只此定乾坤。", "py": []}, {"t": "天長地乆章第七：聖人妙處豈無私，能外其身誰得知。順則凡兮逆則聖，由來於此定根基。", "py": []}, {"t": "上善若水章第八：衆人所惡上賢明，動善其時故下爭。一點靈光君未識，却將水火煑空鐺。", "py": []}, {"t": "持而盈之章第九：滿堂金玉要長存，火候工夫細細論。筌在得魚蹄在兔，塞其兌則閉其門。", "py": []}, {"t": "載營魄章第十：專氣致柔生畜之，積功累行保嬰兒。一斤直要十六兩，莫向人前更好奇。", "py": []}, {"t": "三十輻章第十一：我轂能離三十輻，閒尋無處偷安軸。得便饒也落便饒，君子唯當愼其獨。", "py": []}, {"t": "五色章第十二十：字街頭認色聲雙，眸炯炯却無睛聖。人去彼寧取此下，士聞之疑轉生寵。", "py": []}, {"t": "辱章第十三：大患秪爲吾有身，分明得失總皆驚。没身方是出身處，大患從來亦强名。", "py": []}, {"t": "視之不見章第十四：不聞不見曰希夷，此事如何容易知。乍覩西南一點月，純陽疾走報鍾離。", "py": []}, {"t": "古之善爲士者章第十五：豫涉川兮猶畏鄰，此中微妙且同塵。玄通未許凡人識，誰向亨衢問要津。", "py": []}, {"t": "致虚極章第十六：芸芸物物各歸根，若也知常地自温。昨夜溪頭春水漲，朝來不見水流痕。", "py": []}, {"t": "太上章第十七：上士勤行中士親，只唯下士笑嚬嚬。曾知老子懷胎久，始浴金盆髮似銀。", "py": []}, {"t": "大道廢章第十八六：親不和慈孝生顛，倒乾坤正令行今。日鳳凰臺上客十，年窗下讀書聲絶。", "py": []}, {"t": "聖棄智章第十九：古人棄智定乾坤，說破死生骨董門。不是箇中滋味的，自戕自賊自炮燔。", "py": []}, {"t": "絶學無憂章第二十：察察昭昭我若昏，水頭清處好尋源。不知求食於誰母，便把西江一口吞。", "py": []}, {"t": "孔德之容章第二十一：眼前衆甫即區中，杳杳冥冥内外通。明了地天交泰卦，區中進步作仙翁。", "py": []}, {"t": "曲則全章第二十二：枉則直兮窪則盈，不矜不伐廼功成。昨宵夢裏聞雷雨，今日江頭春水生。", "py": []}, {"t": "希言自然章第二十三：得與失兮兩不羞，形容到了了無儔。真人之德配天地，只在環中匪外求。", "py": []}, {"t": "埪者不立章第二十四：群仙已笑露堂堂，跨者不行子細詳。一著錯時看跌倒，賺人錦袋繡香囊。", "py": []}, {"t": "有物混成章第二十五：有物混成天下母，字之曰道安窠臼。乾尃坤翕證无爲，智者樂兮仁者壽。", "py": []}, {"t": "重爲輕根章第二十六：奈何萬乘乃輕身，孰是踈兮孰是親。寳在眼前凡不識，往教宻宻論君臣。", "py": []}, {"t": "善行章第二十七：知名非實要知情，竅妙之真號襲明。不道善行無轍迹，石中流水豈聞聲。", "py": []}, {"t": "知其雄章第二十八：雄雌黑白坎和離，知則總爲天下谿。眼下十成須認取，由來散樸復嬰兒。", "py": []}, {"t": "將欲章第二十九：神器從來是假名，此名只許上賢聽。不過渡口尋舟子，枉誦玄玄道德經。", "py": []}, {"t": "以道佐人主章第三十：果而不道露鋒芒，却與凡人作禍殃。迸烈豈容君眨眼，山中仙子浴金光。", "py": []}, {"t": "夫佳兵者章第三十一：居貴左兮兵貴右，非人此道莫輕授。有時恬淡樂無爲，上天之載無聲臭。", "py": []}, {"t": "道常无名章第三十二：我相衆生壽者相，權實照用一時放。不通凡聖擬議乖，天地合而甘露降。", "py": []}, {"t": "知人者知章第三十三：智與明兮自勝强，乾坤闔闢要相當。若能守片閒田地，不是尋常孟八郎。", "py": []}, {"t": "大道汎兮章第三十四：大道汎兮不可名，可名非道礙塵生。平時不向西江望，踏破芒鞋未是行。", "py": []}, {"t": "執大象章第三十五：出口淡乎其無味，能者用之不可既。逢人好語說三分，過客欣聞樂與餌。", "py": []}, {"t": "將欲歙之章第三十六：利器如何可示人，不妨勇猛奮精神。叅玄叅到微明的，現出金剛不壞身。", "py": []}, {"t": "道常無爲章第三十七：朝朝只念觀世音，識得觀音辨踵音。若也始終無悔吝，這回方是道人心。", "py": []}, {"t": "上德不德章第三十八：仁之與德不多程，爲與無爲前後行。待問有爲何所似，夜來月在脚跟明。", "py": []}, {"t": "昔之得一章第三十九一：者名爲不二門得，門入去便安身當。年曾子一聲唯誤，了閻浮多少人反。", "py": []}, {"t": "者道之動章第四十：全璧而歸也注心，有生無處此機深。與君評論曹溪水，一滴誰醻萬兩金。", "py": []}, {"t": "上士聞道章第四十一：大象無形道隱名，形名總不向人呈。如今聞者皆應笑，夫唯道善貸且成。", "py": []}, {"t": "道生一章第四十二：沖氣爲和大化爐，與君說了莫疑狐。茫茫宇宙人無數，幾箇男兒是丈夫。", "py": []}, {"t": "天下至柔章第四十三：鍊氣凝神入至聖，紫陽留下悟真篇。元來三教同門户，先要叅皮可漏禪。", "py": []}, {"t": "名與身章第四十四：此身不是四肢身，解向源頭問要津。現自十成非外物，裙釵之下有全人。", "py": []}, {"t": "大成若缺章第四十五：大成若缺直而屈，唯好觀光於上國。有時做箇大閑人，清靜之中無一物。", "py": []}, {"t": "天下有道章第四十六：天下有道馬不走，天下無道物不夭。過猶不及豈忘言，到此一了一切了。", "py": []}, {"t": "不出户章第四十七：目前一寳秘形山，何必長歌行路難。踏破草鞋無覓處，投壺認箭落中間。", "py": []}, {"t": "爲學日益章第四十八：有爲之道須落著，無爲之道要著落。莫向人前認色聲，認色認聲已誤却。", "py": []}, {"t": "聖人無常心章第四十九百：姓之心爲我心分，明說了莫沈吟世。人怎識和山皷一，下能當幾挺金出。", "py": []}, {"t": "生入死章第五十：出生入死無窮已，唯善攝生能不死。知生知死却成人，須入虎穴得虎子。", "py": []}, {"t": "道生之章第五十一：道生德畜却無恩，須彌山上望崑崙。若也另瞠一隻眼，便知落處道方尊。", "py": []}, {"t": "天一有始章第五十二：知其子復守其母，不悟襲常空自走。覆盆之下用其光，休向經中談竅妙。", "py": []}, {"t": "使我介然章第五十三：盜誇盜出自家珍，覆水難收費苦辛。只爲良田荒穢了，如何做得太平民。", "py": []}, {"t": "善建者不拔章第五十四：觀郷觀國觀天下，積德修身道有餘。善建亦知宜善抱，倚需得溥自安居。", "py": []}, {"t": "含德之厚章第五十五：赤子何知爲不攫，未知牝牡而䘒作。益生使氣要長存，豈但筋柔而固握。", "py": []}, {"t": "知者不言章第五十六：閉門塞兌得籝金，電掣星飛何處尋。便遣那吒千手眼，不知佛殿有觀音。", "py": []}, {"t": "以正治國章第五十七：天下從教多忌諱，我唯忌箇小兒名。不知奇處用兵拙，眼下知之即太平。", "py": []}, {"t": "其政悶悶章第五十八：直而不肆極希夷，百尺竿頭未是危。識得聖賢心地用，早應臭腐化神竒。", "py": []}, {"t": "治人事天章第五十九：有國之母重積德，深根固蔕可長生。五更早起無巴鼻，却是街頭有夜行。", "py": []}, {"t": "治大國章第六十：兩不相傷故德歸，鬼非不害自無欺。抱琴有意過西院，彈者彌多聽者稀。", "py": []}, {"t": "大國者下流章第六十一：下流非是下流人，以靜勝人要一真。牝牡之交宜處下，唯應分付下流人。", "py": []}, {"t": "道者萬物之奥章第六十二：善人之寳萬物奥，不善之人之所保。人之不善何棄之，日月去兮進此道。", "py": []}, {"t": "爲無爲章第六十三：早知爲大於其細，天下難事作於易。我若不因師㫖明，舌頭那識味無味。", "py": []}, {"t": "其安易持章第六十四：聖人心上起經綸，幾事不宻則害成。能復衆人之所過，月從西墜日東昇。", "py": []}, {"t": "古之善爲道章第六十五：君子不以智治國，常知楷式是玄德。千蹊百逕要知歸，若不知歸名國賊。", "py": []}, {"t": "江海所以爲百谷王章第六十六：聖人處下復何爭，江海納汙仍太清。點著當前正法眼，抬頭暗室月分明。", "py": []}, {"t": "天下皆謂章第六十七：慈儉本爲天下先，若加精進契前賢。始惟不肖終當肖，正是千錢一貫穿。", "py": []}, {"t": "善爲士章第六十八：善用人者爲之下，善彎弓者爲之射。萬丈懸崖撒手時，方名了了弓弦卸。", "py": []}, {"t": "用兵有言章第六十九：吾寳非金亦匪珍，若輕其敵喪其親。臨深履薄如精進，作主先當會作賔。", "py": []}, {"t": "吾言甚易知章第七十：知我者稀空碌碌，聖人被褐仍懷玉。知之非艱行惟艱，千錢一貫爲知足。", "py": []}, {"t": "知不知章第七十一：大人之病病當心，不用樂醫只用針。針得血膿俱下了，脫除癆瘵似觀音。", "py": []}, {"t": "民不畏威章第七十二：自知已是已靈明，内養工夫熟且純。能自愛兮惟不厭，怡然理順樂天真。", "py": []}, {"t": "勇於敢章第七十三：善惡昭昭網不疏，傷人抵罪豈差殊。種禾種粟不生豆，恬退無爲是護軀。", "py": []}, {"t": "民常不畏死章第七十四：不畏死兮却畏生，畏生之道在持盈。八千兵散渾閒事，項羽頭來落漢營。", "py": []}, {"t": "民之飢章第七十五：無生之義最難言，人世輕生若駿奔。趁得非生非死法，乾坤有限道長存。", "py": []}, {"t": "人之生章第七十六：人死堅强木死枯，夫惟不死是長圖。五行顛倒人能用，有一物常死復甦。", "py": []}, {"t": "天之道章第七十七：不欲見賢豈不賢，只惟平地有神仙。真人指我迴瀾訣，向道女媧解補天。", "py": []}, {"t": "天下章第七十八：受國之垢實希奇，到此方知壽可躋。一得歸來宜永得，渡河筏子上天梯。", "py": []}, {"t": "和大怨章第七十九：左契猶如般若舟，人能執此任西流。故云有德長司契，天道無親親善柔。", "py": []}, {"t": "小國寡民章第八十：小國寡民復古初，壽同日月没盈虚。豈惟老死無來往，天地推遷我自如。", "py": []}, {"t": "信言不美章第八十一：既以與人己愈多，聖人不積抱天和。五千言是金丹髓，信則修之上大羅。", "py": []}, {"t": "上陽子金丹大要積功卷之十", "py": []}]}, {"h": "累行卷之十一", "paras": [{"t": "上陽子金丹大要累行卷之十一睦七。紫霄絳宫上陽子觀吾陳致虚撰。", "py": []}, {"t": "與至陽子田至齋", "py": []}, {"t": "帝皇之得道者，若羲農黄帝焉；仕隱而得道者，若老莊關令焉；侯王而得道者，若子房淮南焉；山巖而得道者，若鍾吕希夷焉。道之在天地間，成仙作佛者，歷歷不可以指數也。後之罕聞者，茫茫而少大丈夫也。其王公大人，折節下士，秪爲有道存耳。士之學無止，亦唯未臻乎道，故明於道者，至聖神人也。", "py": []}, {"t": "僕以西行，旅寓思國宣貳。至齋田侯扣首再三，欲聞至道，經年不倦，乃授之曰：大道者，至人之所祕，聖師之叮嚀也。古之真人，行其所不能行也。宇泰定者，發乎天光；天光發者，人見其人。備物以將形，敬中以達彼。以有爲入無爲：有爲者，與人爲徒；無爲者，與天爲徒。與人爲徒者，鍊先天之一氣；與天爲徒者，鍊後天自然之真。", "py": []}, {"t": "夫人禀天地絪緼一氣而生，從微至著，壯而盛，盛而衰。氣固爲盛，氣餒爲衰。至人者，盛則養之，衰則救之，使一氣長存，歷劫而不死者，金丹也。大修行人既得乾金，入于神室，心目内觀，清靜光明，以成胎嬰。寳之十月，出入去來，無滅無生者，天仙也。", "py": []}, {"t": "所謂氣者，何也？即兩箇隂陽也。一坤一乾，隂陽也；一男一女，隂陽也；一坎一離，隂陽也；一逆一順，隂陽也。南華云：至隂肅肅，至陽赫赫。肅肅出乎天，赫赫發乎地。兩者交通成和，而物生焉。採先天，鍊後天，謂之交通。通則和，成則物生。物生而爲嬰兒，長大而號真人也。至齋言下猛悟，期以勤行，易其號曰至陽子。", "py": []}, {"t": "與初陽子王冰田", "py": []}, {"t": "道也者，不可須臾離也；可離，非道也。惟是道也，在天地之間，旋轉乾坤，昭揭日月，更代四時者也。一切人也，禀大道至聖至靈之體，合大道至精至粹之用。常人順之，是以一生一死，若循環然；至聖神人，以此道而逆之，故成仙作佛，而出造化之外也。", "py": []}, {"t": "三教大聖，皆體此道而用之：儒曰修身，釋曰修性，道曰修命者，即殊途而同歸也。粤後之人，不達聖人之㫖，各尚所聞，而非其所是，豈知身與性命，必不可離者也？若一可離，則非道矣。", "py": []}, {"t": "初陽子王舜民，偉哉大丈夫也。出入仕途，且三十年。僕聞之：舜民之仕也，利不能移其心，困不能改其操，斷然有守。凡所寓，以冰田自扁者，示無纖瑕小疪焉。", "py": []}, {"t": "乙亥冬，會溢江任所，一揖次，若久要。握手輪心，畧無官況。僕覩其氣宇高邁，骨相合仙，因縁遭逢，求我丹道，遂用盟天，以青城老師金鼎火符之祕，次第授之也。乃先除其執著，去其驚疑，道其縁熟，培其根深。僕之用心，又如此者，蓋欲將師所傳，悉授不隱。顧惟聞道不難，行之宜謹。", "py": []}, {"t": "純陽老仙云：便下手速修，猶太遲。使上士聞道，必勤而行之。彼常人者，聽之則且驚且疑，不肯疾早下工。電陣之光，石擊之火，似箭之速，吁可畏哉。今語初陽，其毋忽諸。夫金丹者，金液還丹之道也。金液者，即人身中之真氣也。以氣合形，而成真人，是爲還丹。", "py": []}, {"t": "厥人之初生也，毓先天地至純之道。逮二八，精氣日泄而樸散，則先天之氣不純。且世人之壯，必昏必娶者，以續綱常也。若也中年，却能寳愛其身者，聖人也。", "py": []}, {"t": "孟子四十不動心，莊子五十而知四十九年之非，孔子五十而知天命。今初陽子行年五十有二，而聞金丹乆視之道，以其時考之，則可矣。況初陽子道縁既重，信心益堅，謹因師㫖授之曰：古之真人，欲理其性，先寳其精；欲理其命，先淳其氣。是孟子曰：吾善養吾浩然之氣。", "py": []}, {"t": "其爲氣也，至大至剛，以直養而無害，則塞于天地之間。若以孟子爲寓言，則聖賢寧如是乎？若以孟子爲教言，則人一身之氣，豈能塞乎天地哉？然必有其道矣。道者何耶？氣也。氣者何耶？命也。即經云：天命之謂性，率性之謂道也。", "py": []}, {"t": "夫欲了命，必先修性，性命雙修，何憂不仙？且性也者，何耶？義也。故孟子曰：是集義所生者，非義襲而取之也。若義襲而取，則物也，順也，人也，非金丹也。唯集義所生，則逆也，是所謂金丹也。故云配義與道。而孔子曰：成性存存，道義之門。釋迦云：是諸法如義。老子曰：上義爲之而有以爲。聖人之於道，不離乎義也。義之道，大矣哉。", "py": []}, {"t": "採鉛鍊汞者，集義也；西南得朋者，上義也；龍女獻珠者，如義也。是義也者，即羲之易，一隂一陽之道也。夫一隂者，離中之雌；一陽者，坎中之雄。離中之隂爲火，坎中之陽爲水。配義與道者，以坎反上於離，是水火既濟之道也。蓋於坎中取出陽爻，降而入於離之中，换出隂爻，是爲地天泰也。蓋離中之隂爲汞、爲精，坎中之陽爲鉛、爲氣。", "py": []}, {"t": "心印經云：上藥三品，神與氣精。然精依氣生，神依氣旺，神氣精三者，無一可離。此所謂道也者，不可須臾離也。儻精耗則氣憊，氣餒則神離，氣憊神離，可謂之人乎？此所謂可離非道也。", "py": []}, {"t": "聖師深慮世人不能明乎道、不能鍊其氣，乃借名爲鉛、爲汞、爲鼎、爲爐、爲龍、爲虎、爲砂、爲銀、爲刀圭、爲火候，百般譬喻，託物假名，以曉後之學者，亦豈不欲人人作仙、箇箇成佛也？縁爲世人信之弗及，承當不得，偶或就中間有一二，復爲旁蹊小逕，著相執空，罕聞正道。若大乘根器、上士至人，際遇真人，一言之下，生實信心，寳愛其身，積累其氣，而勤行不怠者，則高仙地位，指日可躋。", "py": []}, {"t": "僕閱人多矣，今觀初陽子，姿禀非凡，神氣充裕，祖師金丹之道，不敢祕者如此。", "py": []}, {"t": "與一陽子潘太初", "py": []}, {"t": "老子曰：上士聞道，勤而行之。至哉言也。僕自獲遇至人，盟授大道，即欲圖就所事，而以功縁未立，用是求諸仙經，搜奇摭粹，作成金丹大要。書成之後，不恤起處，每過名山及諸城邑，隨方作縁，低首下心，開導世人，誘進此道。四三年來，求者紛紛，卒未見有大力量而精進者。", "py": []}, {"t": "比謁廬山太平宫，揖當代主人太初潘一陽，塵襟一見，懽如平生。茶罷復茶，有物外趣。顔童髭墨，神氣裕如，膚澤臉桃，丰標洒落。其剸繁治劇，若不經心；而待物擇交，似有定見。顯官軒車而至者，皆得懽心；負義蓄材而來者，願識其面。頭顱且無塵俗，骨骼脗合仙姿。平川洗滌而疏明，大山嵯峨而增秀，天人交替，鬼神其依。", "py": []}, {"t": "僕每嘆：夫福之與慧，二者不可得兼。太平閒暇，安富尊榮，此人之福也；通玄達妙，研精究微，此人之慧也。二美具全，則斯人也，不可以尋常而同年語。眷顧之初，言及丹道，僕未即應。既而情真語簡，好篤誼深，叙其主領事繁，已覺年光流邁，念念急於兹事者，更來歲而又遲也。僕覩其開心見誠，列盟奉誓，乃授之曰：大道者，與天地生物、乾坤覆育、日月隂陽，同其造化焉。在人之身，不外是也。", "py": []}, {"t": "天地以隂陽爲橐籥，人身以玄牝爲橐籥。天動地靜，動爲陽而靜爲隂。隂極則萬物不生，而陽氣潜伏。及夫剥盡，則一陽初動而梅先吐白者，以陽在地中而將復也。世政以梅爲報春之信，故易之復卦曰：復，其見天地之心乎？復之爲卦，五隂一陽，其一陽在下，而陽爲之主也。人身亦然：自少而壯，壯必衰，壯爲陽而衰屬隂，逮乎隂極，則陽氣欲盡而散也。", "py": []}, {"t": "至人於此，則能體天地之道：以子爲度，以日爲符，以癸爲候，以月爲則，以汞爲隂，以鉛爲陽。鉛生於癸，而癸在坎，坎屬北方，北乃子之正位。天地以七日而來復，復一也；太隂以三日而出庚，庚爲金而金爲乾，乾之金寓于坎。人身亦猶是，而陽復有時。", "py": []}, {"t": "大修行人急於癸生之時，求彼先天真一之氣，以爲鉛也，納此真鉛于離之中，配以離之真火，煅煉成丹，故曰金丹。則金丹者，無外乎坎離二物。且坎離爲何物？要知只是兩箇真隂真陽而已。是知金丹之道，不外乎隂陽也。", "py": []}, {"t": "當其一陽初至，雖一身皆隂，而一陽自外來，彼一陽反爲之主矣。今其號曰一陽子者，取義于此。一陽子既聞此道，儻不爲，則亦已矣；若也興勇猛之心，奮勤行之志，吾知其功成也必矣。", "py": []}, {"t": "與九宫碧陽子車蘭谷", "py": []}, {"t": "古之真人，其寢不夢，其息深深。寢不夢，則神存；息深深，則以踵。此即上德無爲而無以爲之道。至隂肅肅，至陽赫赫，赫赫發乎地，肅肅出乎天。此即上德爲之而用以爲之道。無以爲者，後天自然也；有以爲者，先天一氣也。", "py": []}, {"t": "何謂後天？夫人禀先天一點真陽之氣而生，爲物之最靈者。此氣日生夜長，與天地混沌之時，同其造化。其神之所以存者，鷙鳥不能攫，兕虎不能傷，以其神王故也。及乎年登二八，真氣已盈，復遇至人，授以寳身之道，使天機不逐於事物，無勞于形，無摇其精，息以踵而不以喉，與天爲徒，而世不能移其志，則比古人千二百歲，不啻過也。此所謂後天無爲之道。", "py": []}, {"t": "何謂先天？且人生天地間，年壯而嗜慾，俱以酒爲漿，以妄爲常，恣情縱欲，亡精損神，所禀先天之氣，驅之勞之，猶虎奔而寓于西矣。", "py": []}, {"t": "即如乾之爲物，純陽也，始交于坤，則乾之體破而爲離；坤之爲物，純隂也，潜奪乾之一陽而爲坎。由此之後，乾體反虚，坤體乃實，則離坎者，乃乾坤之繼體。乾坤順行，男女奔放，精竭神去，一切常人至此則已。", "py": []}, {"t": "大修行人體金丹之道而修之，逆五行而用之。逆者何也？坎中之陽赫赫，即乾金也；離中之隂肅肅，即坤爻也。金丹者，以坎而升於離之上，以己而合于戊之門，伏坎中之虎，以降離中之龍；取坎中之金，以尅離中之木；納坎中之水，以鍊離中之火；採坎中之氣，以補離中之精；回坎中之陽，以實離中之隂，即復純乾，而成真人。", "py": []}, {"t": "傳云：西南得朋。伯陽云：真人潜深淵。天台云：鉛見癸生，須急採。馬祖云：一口吸盡西江水。者皆此還丹之道也。故降伏自己之龍虎，採取身中之精氣。然降伏者，功在於德；採取者，不外乎道。道無德，不能採取；德非道，無以降伏。", "py": []}, {"t": "所謂採取者，只須一時之功，非有遲疑之事。蓋一時者，要在初三日内取之。當此初三之夜，月生庚方之際，此時水源至清，渾無撓動，急用半時，採取歸於鵲橋之東，結成黍粒之丹，入于黄金室内，鍊之成之，謂之金丹，謂之先天大道。世人一知金丹，即我本來乾中之真金，則爲微妙玄通之士，而深不可識矣。", "py": []}, {"t": "九宫山碧陽子車蘭谷，爲玄門棟梁者，四十餘年矣。其功業設施，表表在人耳目也。卓然道眼，識人不似他人之忌才者。僕以不檢，唯志於道，不免沽癡自醜，賈愚自賣，既無華衣以浮飾，不能强容以求知。一揖之初，乃即深契，求我丹道，足所未聞。覩其神氣裕如，遂將祖師先天後天金丹之㫖，悉以授之，却加勉勵焉。", "py": []}, {"t": "噫。世人之所以峨其冠者，入老氏之門，學老氏之道也。夫老氏之道，寳精氣，修返還，尚清虚，寡嗜慾，薄飲食，離塵縁，廣慈悲，樹隂德，損之又損，至於無爲，是則謂老氏之徒。今焉處珠宫，披鶴氅，直以問道爲羞、爲辱者，何不反思吾教之所學何也？間有一二希乎修養之說者，則叢聚而笑之。我太上曰：下士聞道，大笑之。豈古然哉？", "py": []}, {"t": "夫既入其門，而不行其道，則爲老氏之蠹也。蠹者，衣其服而妬其教，蠶其食而訾其道，是猶服堯之服而非堯之言，吾不知其可也。縱負出類拔萃之材者，亦甘以清高至貴之身，棄之於濁惡之地，使俗之有口者，呼之爲異端之徒。吁可惜哉。", "py": []}, {"t": "就中有能去傲除慾、節飮靜坐者，雖不得真師之指，亦不爲教門之罪人也。彼神仙者，慈愍爲心，不顧訕毁，唯欲化人成道而已。昔者黄帝之問道也，膝行跪進。既聞道已，乃曰：廣成子之謂天矣。", "py": []}, {"t": "今之時人，去古道遠，以矯詐爲誠，以妄誕爲心。其未之聞，謂有何道？及稍有聞，自以爲足。或始聞師之語，恐師未盡善；及略聞其端倪，則謂素所自有。借使造其閫奥，即萌僥倖而得之喜，惟恐師之求其所報，寧肯勤行哉？果若此，又孰得而臻乎極也？豈能如碧陽子，聞一且問二，聞二復問三，既不以才自矜，復愈高而愈進？", "py": []}, {"t": "山間林下，或有超然穎脫之器，以生死爲一大件，如我碧陽子者，出研精究微，叅玄造妙，還丹坎户，結胎黄房，若非白日而飛升，亦傍神仙地位而去，況其精進而勇猛者乎？諺云：一子出家，九族俱仙。者斯之謂歟？", "py": []}, {"t": "今碧陽子，雖其主領事繁，猶能孜孜上道，直以堅固爲實踐，不以誑妄爲虚彰，與彼夢生醉死者，大有逕庭。南華云：卜梁倚有聖人之才，而無聖人之道。吾將以聖人之道告之，庶幾其果爲聖人乎？碧陽子今聞聖人之道，已早修有爲之德，高證無爲之功，以應龍沙八百之讖乎？異時名公鉅卿，必有取法于子者，子其勉乎？", "py": []}, {"t": "上陽子金丹大要累行卷之十一", "py": []}]}, {"h": "累行卷之十二", "paras": [{"t": "上陽子金丹大要累行卷之十二睦八紫霄絳宫上陽子觀吾陳致虚撰", "py": []}, {"t": "與宗陽子明素蟾", "py": []}, {"t": "通今博古，註書立言，筆迴狂瀾，錦心繡口，此文章之學至矣。鮮不以是而自足者，斯人也。其才勝德也，叅玄入妙，窮神知化，積精累氣，鍊氣化形，此道學亦至矣。鮮不以是而自高者，若能慈悲接引，斯人也可與鍾吕並駕者矣。", "py": []}, {"t": "僕登九宫山，有曰明素蟾者，自弱冠棄親出家，敏而好學，年幾而立，卓犖不群，博采雄覽，謙訪浩記，談今考古，作爲文章，奔放横流，悅可人意，不免盈而大溢，焰乃上飈，則於良明知己者少。", "py": []}, {"t": "既而求神仙家學，凡四方來者，雖旁蹊小逕，莫不開心見誠，必盡其說而後已。前後閱數十人，自以爲畢得金丹之道已。僕從容訊其所得之說，則亦有般運身中之神氣者，然似是而非；亦有烹煉丹田之鉛汞者，又似同而異。甚而非採戰則燒黄煑白，非兀坐則注想空言。今兹弛焉，自謂金丹之道如斯而已矣。", "py": []}, {"t": "其於丹經符契，朗誦如流，又且枉釋旁通，辭亦近理，俯視同輩，傍若無人，將有環中之期而不可遏也。傾蓋之初，試問我以金丹一事，覩其才高氣焱，貌敬禮疏，而所遇人無下手處，僕乃從而順之、美之、揚之、德之。僕之所以德之者，將有以化之也。蓋所以化之者，爲其滯於癖見邪說，使一聞至道，必若驚若疑。", "py": []}, {"t": "嗟夫，時之高人勝士，負不世出之才，而執一方之見，往往不足以語大道者，非恥於相師，則過於聦明，況其下此者乎？僕見明素蟾資禀非凡，勇銳可授，特其平時流於敖放，泥於慣常，首須降其驕心，攝其狂心，去其放心，移其疑心，正其邪心，開以道心。明素蟾忽於言下幡然大改，頓然大悟，於是指令脚跟踏在實處，然後授以先天烹煉神氣之道也。", "py": []}, {"t": "曰：夫先天一氣，即金丹之祖氣也。要知此精、此氣、此神，根於父母未生之前，是太極也。則人禀此先天太極之氣而生也，成於渾渾沌沌之内，出於窈窈㝠㝠之中，當此之時，和之至也。故夫人之生也，男則萬神唱恭，女則萬神唱奉。恭則温良儉讓具其間也，奉則委婉聽從存其内也。男以剛健中正而不敬恭者，是棄其生也；女有工容言德而不奉順者，是殘其德也。", "py": []}, {"t": "且厥初至和之氣，日生夜長，至于二八，而陽又太極矣。生而知之者，於此行上德無爲之事也。只爲世人顛倒妄想，由此淳樸一散，純粹難全，則向來所受之乾金，虎奔而寓于西矣。自是而後，名利心動，寵辱晨馳，投老而不知退步以求自全者，吁，可惜哉。凡人欲全此精氣神者，非先天太極之氣餘則無可，故曰：天下無二道也。", "py": []}, {"t": "是此先天太極之氣，名爲真鉛，亦曰乾金，寄于坎中，是云母隱子胎。世人不覺不知，不明大道之本，而用採戰、採隂、補腦、還精、肘後飛金之術者，是愈促其生也。", "py": []}, {"t": "大修行人要明生身造化，産藥川源，坎水乾金，求之西南。東三南二，會在中央。真虎真龍，必得癸一而方戰；真水真火，必得二八而始交。悟玄牝，是還丹；辨刀圭，即藥物。龜蛇蟠結之際，横天上之鵲橋；木金間隔之時，會人間之牛斗。主賔揖遜，老嫩毋差。片餉工夫，十分謹愼。", "py": []}, {"t": "寳珠現于月地，穩穩收來；金液至于丹田，温温調燮。當時且讓，凡事宜謙。饒人先鞭，取他快意。如愚似訥，顯道人之家風；禮下不爭，乃神仙之上計。方得臨爐有慶，一點落在黄庭；養火何難，九轉待行符候。洗心滌慮，以結三百日之胎；鍊神還虚，成就大丈夫之事也。", "py": []}, {"t": "明素蟾始聞而驚，再聞而疑，竟至通宵摸索，渾身是汗，忽然壁立萬仞，直下承當，始悟性命即是兩箇隂陽，身心儘有許多神氣。淨倮倮亦是，圓陀陀亦是，滿空白雪，便欲一口雄餐；西江清流，不待一口吸盡。方知大道不在丹經，以數十年精進之功，今而後知實未始有學也。衆雌而無雄，而又奚卵焉？", "py": []}, {"t": "問之曰：明素蟾者，其有謂乎？曰：琮也，每慕白玉蟾者也，故用姓以謝覆載，名以謝親，字以謝友。明即白也，素猶玉也，故謂明素蟾云。", "py": []}, {"t": "上陽子曰：子真能求乎仙矣。慕其人，希其道，並以名而就之，抑亦至矣。子又知之乎？夫精通而不昧者，明也；聞道而勤行者，素也。惟蟾也，月中之物也，隂中之陽也，黑中之白也，雌中之雄也，坎中之畫也。蟾之爲物，止三足焉。三足者，爲鼎器取像，爲懸胎鼎也。則蟾之爲妙，乃道之用乎？今子希紫清翁者，其謂此乎哉？", "py": []}, {"t": "雖然，吾將勉之。修行之人，用心若鏡，不將不迎，應而不藏。我趙老師云：讓而不爭，則無愆尤。玉蟾《大道歌》曰：神仙伎倆無多子，只是人間一味呆。又云：世間學仙者，胷襟變清雅。又《雲遊歌》云：滿面著盡笑，喝駡教吾去。噫，紫清翁且能受盡世人笑駡，而直一味呆之嘆。今一切人矜以自高自足之心，而欲希慕神仙之說者，抑何愚哉？子儻能以清雅而變於心胷，以謙讓而出其傲忽，必能以呆而奉人之笑駡矣。", "py": []}, {"t": "自我丹陽之傳黄房公也，又六傳而至于子，子其勉之。", "py": []}, {"t": "明素蟾曰：疇昔聞見，自謂人人可爲鍾吕，今廼深知遍界無一人能擔負此事者。道妙玄微，天機深遠，詎可忽諸？常謂玉蟾翁始得泥丸老仙之傳也，歌云：隂陽顛倒入玄谷。又云：六十四年都是錯。又云：前年仙師寄書歸，道我有名在金闕。何其聞道之晚，而成之之易也如此？今承教者，孰知至妙至玄最爲難思難議者哉？始知五十八年都是錯也。", "py": []}, {"t": "千經萬卷總非，裏許便將捉住西山之白虎，攝伏東海之青龍，期集吾事而已，奚敢忽慢而傲世哉？就令書此，凡到諸方，遇蓬萊仙侣，試一出之，將必有取則於此者，信夫。", "py": []}, {"t": "與玄陽子歐陽玉淵", "py": []}, {"t": "先哲曰：形以道全，命以術延。子書曰：魚相忘於江湖，人相忘於道術。則知道與術二者，不可得而離也。術以道爲主，道以術爲用。要知此道，非泛常所言之道，乃天仙之道也；要知此術，非泛常所用之術，乃長生之術也。僕於玄陽子有說焉。玄陽子，廬山歐陽玉淵也，訊道於上陽子，上陽子語以天仙之道，併以長生之術而授之也。", "py": []}, {"t": "上陽子曰：是道也，極深而研幾。《易》曰：唯深也，故能通天下之志；唯幾也，故能成天下之務。極深者，淵淵其淵也；研幾者，浩浩其天也。浩浩其天者，陽之極也；淵淵其淵者，隂之極也。故隂極則爲坎，陽極則爲離，是坎中有一陽之氣，而離中有一隂之精。天仙之道，以坎離爲之主也；長生之術，以坎離爲之用也。孔子曰：愼斯術也以往，其無所失矣。術者何也？能顛倒坎離而用之也。", "py": []}, {"t": "古仙曰：五行顛倒，大地七寳；五行順行，法界火坑。夫坎雄爲金精，離雌爲真火，取坎中之金精而降于離宫，以離宫真火而煅鍊之，是云顛倒隂陽之術也。然顛倒之術，在乎研其幾也。幾者，隂陽不測之謂。隂陽不測，則鬼神不知，日月不照。爲其日月不照，吾將以道而合乎日月也。合之者，月生于庚，則金旺水清，乃採金于三日，故云與日月合其明。", "py": []}, {"t": "合者，彼之庚金一生，即以我之真火而候之，是謂之火候。庚，西方也，西方金之正位。顛倒之術者，則採庚金于坎之中，縁以其母隱于子胎也。是以坎之雄而補離之雌者，謂之天仙也。故幾者，動之微，吉之先見者也。幾於道者，其長生之術也。幾之爲言，宻也。《注齡經》曰：斗步子形，光映子精，宻而行之，方得成道。玄陽子研乎幾之妙，極乎深之㫖，宻而行之，勤而修之，則由長生之術以入天仙之選者，其玄陽子乎？", "py": []}, {"t": "與復陽子歐陽玉田全陽子周草窗", "py": []}, {"t": "金丹之道，三十四傳而得雙玉翁，又三傳以至於予。予始得縁督趙公之語，雖素有志，未免遲疑。後羇旅中，復拜至人，以青城至祕之文，悉授無隱，敬受以來，日夕不遑。嗟夫，金丹一事，自長春老仙慶會而後，真仙聖師不肯降世者百有餘年，凡今之士，直以爲無。若即自善于身，則於功行何在？乃作《金丹大要》十卷。", "py": []}, {"t": "書成之後，又慮世人非得口傳，寧有自悟，遂用携書，朅蹷屈己求人，稍有可招可挈者，莫不低首俯身，奬辭勸誨，冀進此道。或遭詬駡，姑自隱忍；偶獲一人兩人之知，即來千人萬人之謗。但欲行道，不顧是非。", "py": []}, {"t": "遇諸訕，則喜而受之；是法器，則勉而進之。其間可及門者，則引之而入門；可入門者，則引之而陞階；可陞階者，則引之而陞堂；可陞堂者，則引之而入室。凡用心至于如此者，欲續大道於一綫，提流俗於火坑，使世知有金丹之道不誣也。", "py": []}, {"t": "廬山有歐陽玉田、周草窗二子，皆尚操行而清高者。玉田蓋恬淡爲心，機圓應物，素有志於物外，唯恐此身之墮於塵籠也，故平居暇日，群而不黨，處稠人廣衆，和而不同，以未遇真師，是拘於枯坐而已。草窗則幼而敏銳，習於程朱事業，持己以方正爲德，先孝友，主乎忠信，立其敬義，可謂君子矣。衣冠不同於俗，猶善場屋之文，此其志有未艾。", "py": []}, {"t": "相逢湓江，一笑適契，方知性理之學，程朱未嘗不究，今知其有未至者。既聞予說，雖群疑積毁，而頓然深者，是其明也。然二子素守如彼，若使陟聞至祕，寧免驚疑？予乃從容引喻，以漸爲隄，又摘丹經中最警句而啓之，復以正言而析其輕易，必其堅固，增其智慧，然後授之。", "py": []}, {"t": "曰：金丹者，即老子觀妙觀徼之道也。妙也者，無爲而無不爲也；徼也者，有爲而有以爲也。無爲者，安而行之也；有爲者，勉强而行之也。夫人禀上德之資，本來清淨，豈知日鑿一竅，而渾沌之體不全。常人以愛慾而就不全之體，至於殆而已。今吾命玉田曰復陽子，草窗爲全陽子，豈無㫖乎？蓋大修行人，以其不全而圖其復全也。", "py": []}, {"t": "世之千蹊百逕，俱不能復而全之，唯金丹之道可以復全。復者何也？要我真陽之復歸也。全者何也？要我真陽之純全也。牽將白虎歸家養，復陽也；産箇明珠似月圓，全陽也。陽復則有火候，陽全則有脫胎，金丹之道，其斯之謂歟？雖然，其要又有三焉：口訣而心傳者，一也；决烈而勤行者，二也；以定而制動者，三也。口訣之心傳之，既盡我之真矣；决烈勤行，定以制動，則在乎二子之用功耳。", "py": []}, {"t": "昔正陽之授純陽也，以十事而歷試之；重陽之授丹陽也，以分梨而十化之。前聖後聖，艱難若此。吾之與子，曾不一試，然而盟誓至重，子其守之：上不愧于神明，中不負於師資，下不羞于同學。三者既備，二子之金丹必成。金丹成而聖胎圓，聖胎圓而真人見。於是時也，則身外有身，皆分内事。神仙之道，三十八傳而今附二子，宜相矢勵焉。", "py": []}, {"t": "與心陽子", "py": []}, {"t": "余觀古世之所謂貧賤富貴者，曰有命；而壽夭窮通者，曰有數。然數係乎命，而命係乎天矣。世固有年相若而道相似也，固有出其類而拔其萃也。至若越乎壽夭窮通之域，超乎富貴貧賤之外者，唯古之真人也。", "py": []}, {"t": "比揖余舜申觀古心也，謾逢適契，一語投機，芝蘭其香，煙霞同味。劇談之外，則暢飮銜杯，丰神洒落，揚眉吐氣，議論高遠，拂意者弛然而不答，快心者作焉而不辭，飄飄匪塵俗之拘，翛翛然物外之趣。予乃不倦，細而詢之，始知年俱上章攝提之季夏，日既同，而生之時又同，甫大笑曰：是真同年也，不免道亦相似。", "py": []}, {"t": "試徴之：吾乃江右之廬陵，而舜申亦江右之武寧，是其地同也。昔長者字予曰觀吾，而舜申之號曰觀古，是名又同也。觀古居九宫山頭，而吾家三山高處，則居亦同也。偕誦老莊之言，而明周孔之易，咸簪晋代之冠，俱樂堯舜之道也。蓋常病古人多癖此而非彼者，今吾二人得兼而明之，非唯道相似，是均所同也。", "py": []}, {"t": "就其間審有同而異者：予借名觀吾者，止乎一己而已；而舜申之號觀古者，蓋善觀乎古人者也。以道德仁義觀乎古人，是得古人之心也；以禮樂文物觀乎古人，是得古人之實也。觀古而希堯，是堯而矣；觀古而希舜，是舜而矣。此觀古之所以爲勝也。", "py": []}, {"t": "且吾有大不勝於觀古者：予之癖於金鼎火符之道也，欲運坎而實乎離，儗駕龍而娶于虎，將求西江之水，以來西南之朋，潜採黑中之白，以化陽中之隂，期若蛻蟬，而冀神化者。夫既不能如舜申之觀乎古，日但務此恍惚杳冥爲一大事，唯恐不至者，此吾所謂大不勝也。", "py": []}, {"t": "且夫松檜桂栢，植于陵阜也，地則同也，樹之時又同也。日視之，性有曲直而凋瘁者，影有婆娑而凌霄者，豈其造化之慳也哉？而況於人乎？雖然，觀古之與觀吾，有大同而不肯自異者，爲能弗拘拘於命數也。", "py": []}, {"t": "不徯袍帶之榮，無羡萬金之富，然食飲足以充飢渴，衣帛足以禦歲寒，以淘汰乎神情之渣滓，逍遥乎無何有之郷，越壽夭窮通之域，而超于富貴貧賤之外，與彼之求田問舍、貪名競利者，猶許之洗耳而汙夫巢之犢也。", "py": []}, {"t": "歲紀乙亥六月八日，肩彘籠鵝，會于所寓，叅杯交賀，亦人生之希有，因書以見同異焉。觀古心曰：何其多同也，還能以金鼎坎離之道、龍虎神化之㫖以相授受，庶足其所同？予應之曰：可。明年再會，詢兹益勤。僕且箴之曰：金丹大道，必先積德而後可聞，否則爲之顛踣。今子餌於射利，縶於計慮，殉於嗜慾，穽於嗔疑，如是而求德，誣也；如是而求道，難也。", "py": []}, {"t": "故道之與德，如隂之與陽，二者不可一缺。若隂而無陽，不得謂之道；若道而無德，未可言金丹。古仙云：言清行濁，休談道。且士之爲學，不學則已，學則期於必成，而況道乎？僕之所以不即相付者，猶植樹焉，將欲固之，必深其根。觀古心聞而唯唯，不逆於心，發其悔艾之辭，將刈嗔疑之妄。", "py": []}, {"t": "僕乃授之曰：金丹者，以有作合無爲，以外鉛合内汞。汞，精也；鉛，氣也。採先天之鉛于坎之中，是云有作；合後天之汞于離之内，是名無爲。採鉛則一時，合汞須十月。一時者，月生三日也；十月者，丹成九轉也。知雄守雌者，三日之内一時也；知白守黑者，九轉之功十月也。如斯而已，信則行之。觀古心言下悟，廼覺疑信在人心也，而彼乾金在坎心也，方知天下無二道，聖人無兩心，遂更名曰心陽子。", "py": []}, {"t": "上陽子金丹大要累行卷之十二", "py": []}]}, {"h": "發真卷之十三", "paras": [{"t": "上陽子金丹大要發真卷之十三睦九紫霄絳宫上陽子觀吾陳致虚撰", "py": []}, {"t": "生死事大", "py": []}, {"t": "上陽子清齋夜坐，弟子侍。曰：弟子見師閑居入室，抱神毓精，似廣步妙庭而身未嘗移，似怡情真館而形未嘗離。其逍遥而真遊乎？其恍惚而無爲乎？弟子敢問。上陽子靜坐未應。弟子曰：司聽以默，其駕景窈冥之鄉乎？司視以靜，其飛神虚無之境乎？弟子敢問。乃三問而三不發。", "py": []}, {"t": "弟子曰：弟子不度無材，獲事我師，實以生死一事最大。流光奔電，過隙飛星，冉冉年華，其不可止乎？而芸芸姤復，其又可已乎？聖人已還，寥寥而何法乎？富貴貧賤，紛紛亦何雜乎？天地之大，可得原乎？至道之妙，可得聞乎？何三問而三不發？其秘耶？其靳耶？上陽子欣然視之曰：善哉，而生之問也，庶幾而身之問也。來，汝齋，吾將條而語汝也。", "py": []}, {"t": "弟子乃各攝衣起敬曰：齋矣，敢問其生。上陽子曰：無者，生之太一也；有者，生之太極也。太一者，兆無之先，含靈藴精；太極者，兆有之後，凝胚剖孕。其道之物乎？其生之問乎？其地水乎？其火風乎？其嬰兒乎？其赤子乎？子獨不聞之地水火風之四大者乎？髮齒骨甲，假之于地；涕精血液，假之于水；温煖燥熱也，其於物也，與聖人、天地合其心而同其有也。", "py": []}, {"t": "聖人也，德我也，而不數；數我也，天地也；有我也，而不常；常我也，父母也；生我也，而忽忽遺我也。是生非我長也，有非我常也，德非我良也，而師教也。德且至矣，其有且多矣，非師恩也，奚陶鑄之也歟？", "py": []}, {"t": "聖人之德", "py": []}, {"t": "弟子請進於上陽子曰：弟子因縁遭逢，獲親大道，敢聞聖人之德，以啓發於蒙迷也。上陽子曰：聖人也，生而知之者也，亦學而知之也，亦困而學之也。聖人也，學而不厭，乃無所不通也。聖人也，知天之所爲也，知人之所爲也。聖人也，非多能也，乃多學而識之也。聖人也，非自然也，唯善格其物也。聖人也，非生而知乎道，唯道乃求而得之也。", "py": []}, {"t": "聖人也，善終其天年，而不中道夭也。聖人也，息以踵而不以喉也，不知說生而惡死也。聖人也，德盛仁熟之稱也。聖人也，躬大道之本，明大道之正，成大道之事也。聖人也，其狀義而不明，故莊生曰：凄然似秋，煊然似春，喜怒通四時，與物有宜，而莫知其極也。聖人也，成天下之亹亹者也。", "py": []}, {"t": "條萬物，明曆數，造書契，垂衣裳，樹五穀，通舟車者，聖人也；無爲而治者，聖人也；不言而教、不令而行者，聖人也。聖人之在天下也，河出圖，洛出書，聖人畫易以形道。是易也，成天下之大，盡天下之務，定天下之業也。是以聖人貴精而不從事於務，死生無變於己，乘雲氣，騎日月，遊乎塵垢之外也。", "py": []}, {"t": "聖人神矣，常善救人而無棄之，衣被萬物而不爲主，不爲天下先而德交歸焉。難得之貨，聖人則不貴焉。聖人不積也而愈多，先天地生而不爲久，長於上古而不爲老。故老子曰：聖人處上而人不重，處前而人不害，天下樂推而不厭。", "py": []}, {"t": "故夫聖人生而不有，爲而不力，立天地而不偏其恩，久天地而不見其勞，仁萬物而不私，德萬物而不居。聖人非唯不居也，而生非其愛也，而身非其有也，而名非其存也。唯其不存，是以長存。", "py": []}, {"t": "天地之大", "py": []}, {"t": "弟子復進曰：敢問天地。上陽子曰：天地之大，莫可得而論也。故莊周曰：六合之外，聖人存而不論也；六合之内，聖人論而不議也。且我而爲天地中之一物，猶大海之一滴也，惡得而論天地？弟子曰：傳云：有真人而後有真知。請因所聞，而聞所不聞之聞也。上陽子曰：無已，則我借言之，汝亦妄聽之。", "py": []}, {"t": "夫天地一大身也。天地之未始有始之始也，一氣蟠積，溟溟涬涬，窈冥莫測，氤氲活動，含靈至妙，是爲大一，是爲未始之始。始也是爲道也，故曰無始。夫天地之有始也，一氣動盪，虚無開合，雌雄感召，黑白交凝，有無相射，混混沌沌，沖虚至聖，包元含靈，神明變化，恍惚立極，是爲太易，是爲有始之始。始也是謂道生一，也是曰元始。", "py": []}, {"t": "夫天地之太極也，一氣斯析，真宰自判，交映羅列，萬靈肅護，隂陽剖分，是爲太極，是爲一生二，也是曰虚皇。隂陽既判，天地位焉，人乃育焉，是爲二生三，也是曰混元。", "py": []}, {"t": "隂之清者，升上而焕麗也，則日月星辰布焉，故天左運，三光右旋；陽之清者，騰上而會于陽也，故風雲動而雷雨作焉；陽之濁者，重滯而就地也，則海嶽奠峙，而五穀草木昌焉，故巖岫出雲，山澤通氣；隂陽之氣，閉而不通也，則雪霜結而凍冰焉；隂之濁者，積沍而下凝也，穴巖幽藏而深邃，故五金八石以錯雜焉。", "py": []}, {"t": "天地之中，隂陽正氣之所交也，聖人焉，仙佛焉，庶民焉，賢愚壽夭，寔所殽焉，胎卵濕化，無有息焉，是爲六合也，是爲三生萬物也，是爲萬神聽命也。子來前，予語汝：有道之士，就中取則也。蓋九天之上，鉛汞已乾；九地之下，重隂積固。唯中也是有道焉，是爲一小天地也。", "py": []}, {"t": "子不聞之天地之外有大天地焉？子又不聞之佛祖之法言也，其言曰：何物高於天？生天者是。何物厚於地？育地者是。何物寬於虚空？包虚空者是。夫以是知天地之外，復有大天地也。子抑知之乎？今之天地，屬大天地之中之一物耳，即如人是今天地中之一物也，即如道乃人身中之一物也，是故人身又一小天地也。", "py": []}, {"t": "子抑知之乎其大天地也？且孰爲其大？汝來，吾今直以語于汝：是道也，能以之大而且久也，故有生而無終窮，有結凝而不散，是以包乎天地之外，而且不自知其爲大。夫惟不自大，故能就其大。", "py": []}, {"t": "道本隂陽", "py": []}, {"t": "弟子復進曰：天地之外有大天地者，弟子謹受教矣。所謂道能成天地之大者矣，而又云道乃人身中之一物耳，何小大之異也？是道也，果何物也，而靈通變化若是者也？弟子敢問，以釋驚疑。", "py": []}, {"t": "上陽子曰：夫道也，生天也，生地也，成仙佛也，類萬物也，是先天地之道也。夫唯今有天地也，有人也，有萬物也，是復天地之道也，而道也者，乃行乎其中也。吾所謂先天地之道者，其功溥博，其用莫測，天之所祕，不可思議，不可妄說，汝亦不庸於妄聽也。", "py": []}, {"t": "曰：何謂也？曰：夫道也者，難言也。曰：願聞教㫖。曰：未也。夫上士急於聞而勇於行，中士試於聞而怠於行，下士聞之，嗔謗乃生。弟子跪而進曰：天地之間，道惟至大，豈中下之人能聞能受者也？弟子不自揆度，而以愚下之庸，不敢輕忽怠慢，願聞至道。", "py": []}, {"t": "上陽子曰：至道之妙，吾嘗釋《道德經》矣，其於道可道章，指出稍詳，行將授汝。且道也者，即一隂陽也。子不聞之乎？天地，一隂陽也；人，一隂陽也；萬物，各一隂陽也。日月星辰、風雲雷雨、雪霜冰電、山川草木、胎卵濕化，莫不各禀一隂陽也。", "py": []}, {"t": "而正也，而偏也，得其道之正者，天地也，人也，是曰禀隂陽之正氣也。而聖人仙佛也者，蓋善於用隂陽者也。故抱隂而負陽，則沖氣以爲和；入隂而出陽，則有生而無已。故太上以爲善攝生也。", "py": []}, {"t": "子抑不聞之乎？天地之道也，陽極而隂，隂極而陽，故萬物終焉，萬物生焉。人之道也，隂極而已，世故有生死焉；陽極而已，世故有金丹焉。世之生死者，後天地之道也，有盈虚焉，有消息焉。唯金丹也者，即先天地之道也，不爲人也，不爲物也，非順求之，乃逆取之，有生也無死也，是之謂聖人也，是之謂仙佛也。", "py": []}, {"t": "子獨不知夫先天地之道是爲金丹乎？世人非唯不知先天地之道爲金丹，設使聞之也，則非笑毁謗隨之矣。故夫子曰：非聖人者無法也。天地長且久，而猶有壞，未若金丹之超然獨存。非金丹之能自存也，實在乎人用之何如耳。唯其不自存，是以能長存。", "py": []}, {"t": "金液還丹", "py": []}, {"t": "弟子再拜以進曰：金丹之謂也，是先天地之道，弟子謹受教矣。弟子不揆短末，念此有生斯世也，未有若是之愚也。弟子嘗試而有爲也，人莫我若也；嘗試而有以也，人莫我其多也。每讀書也，人以我爲浩有；每學易也，人以我爲粗通。弟子而今也，乃知所未至者也，若鼠之飮于河也，故未能測其深，而乃妄云知其源。因承師訓，惘然如失，豈唯見之未見，實未試聞而未之聞也。願垂慈憫，指示金丹。", "py": []}, {"t": "上陽子曰：道也，唯金丹之祕，六耳不可言，坐立不可談，飮食不可見，非齋沐不可得而聞也。弟子各敬而退：一之日沐，二之日戒，三之日齋。齋肅而進，稽顙言曰：弟子宿生慶幸，遭際真師，實以愚迷，恐墮生死，一失人身，同於朽腐，謹受教矣，敢問金丹。", "py": []}, {"t": "上陽子曰：道也，唯金丹之所難言，不可得而易聞也。曰：何謂也？曰：子不聞佛之爲說乎？佛之言曰：若說是事，諸天及人，皆當驚疑。來，吾語汝也。且夫士有賢愚，人有明闇，若說是事，或驚或疑，此則有之，是無他也，爲其根器淺薄，智識昏陋，是以然也。", "py": []}, {"t": "云何諸天亦復驚疑？則當於此究竟審問，須要知其必有可驚可疑之事者也。爲他一切人，孰肯於驚疑二字上以索之？我縁督子作《仙佛同源》，每章曉以驚疑之說，使學者深思其㫖也。", "py": []}, {"t": "子抑聞之庚桑者乎？陳人有庚桑楚者，自號亢倉子，得老子之道，著書九篇，居畏壘之山。其臣之畫然知者去之，其妾之絜然仁者遠之，擁腫之與居，鞅掌之爲使。南榮趎聞其有道也，往而師焉。楚曰：奔蜂不能化藿蠋，越雞不能伏鵠卵，其才有巨小也。吾才小，不足以化子，子胡不南見老子？趎因楚見老子。老子曰：子何與人偕來之衆也？趎瞿然顧其後，府而慙曰：今者吾忘吾答，因失吾問。", "py": []}, {"t": "老子曰：何謂也？趎曰：不知乎，人謂我朱愚；知乎，反愁我軀。不仁則害人，仁則反愁我身；不義則傷被，義則反愁我己。我安逃此而可乎？老子曰：若規規然，若喪父母，揭竿而求諸海乎？朱願聞衛生之經。老子授以至人之說，趎勤修之，是封曰洞靈真人。", "py": []}, {"t": "子乃不聞之六清淨乎？道也者，非六清淨，不可得而易聞也。弟子悚而退：一之日不染諸塵，得身清淨；二之日慎内閉外，得口清淨；三之日不貪諸色，得眼清淨；四之日不著於聲，得耳清淨；五之日香臭自分，得鼻清淨；六之日不起妄想，得意清淨。", "py": []}, {"t": "七之日，焚百寳香，叩首而言：弟子今而清淨已，敢問金丹。曰：爾惟六識得而清淨，外有二識，安能清淨？曰：何云二識？曰：含藏、傳送，此二識也，非容易知，況欲其清淨者乎？且金丹之道，天之所禁，若欲聞者，奉誓盟天，登壇歃丹，非率爾而可言，非一汝心而莫可聽也。", "py": []}, {"t": "弟子乃率卜吉，裂帛書丹，盟天告地，齎金爲信，盡有爲誠。心無所澄而清，志無所撓而一，頓首跪而進曰：弟子幻身，罔知所措，光隂迅奔，生死是懼。伏惟金丹之道，可以不死，可以長生，喘息已殘，願垂矜憫，敢問金丹。", "py": []}, {"t": "上陽子曰：而獨不聞之廣成子乎？廣成子千二百歲而形未嘗衰，其抱一守和之至也。其非金丹之道也，安能若是其久乎？而又不聞之廣成子乎？廣成子曰：至道之清，窈窈冥冥；至道之極，昏昏默默。無視無聽，抱神以靜，形將自正。", "py": []}, {"t": "必靜必清，無勞汝形，無摇汝精，乃可以長生。而復不聞之巢父乎？巢父之讓許由也，上流而飲其犢也。世之唯知巢父之潔也，而不知巢父之道之尊之。夫唯是道之尊，非巢父其能自潔。子抑聽知乎？曰：敬受教矣。金丹之要，其是之謂乎？曰：未也。曰：敢問金丹。", "py": []}, {"t": "上陽子曰：大修行人，其志清靜，用心猛烈，使聞金丹之道也，縱榮極要地，若棄糞土然。何哉？唯急於身也，而以名爲惡也，爲疾也。其商山翁然，其張子房然，其扶摇子然。", "py": []}, {"t": "子豈不聞之扶摇子乎？扶摇子之得麻衣仙翁之道也，其小睡也，三年而一覺；其大睡也，未可以年而計，以劫爲度也，而且無濁劫焉。其以詩而復寵命曰：剛被山童一向應，爲言天子詔書來。無非只說名和利，撇在床頭不用開。是知名與身孰親，是謂知止不殆，可以長久也。", "py": []}, {"t": "其次也，有富家翁焉，有貴公子焉，以精進勇猛爲心，使聞金丹之要，則棄其所愛，改而行於大道也。其陶朱公然，其龐居士然，其馬宜甫然。子豈不聞之馬宜甫之說乎？馬宜甫者，東州富室也，重陽老仙授以至道，乃即棄其所有，捨其所愛而修道焉，即丹陽祖師也。是知身多於貨也。", "py": []}, {"t": "又其次也，若困若窶，財之不充乎用，而志也堅，唯忙忙汲汲也，復忘寢失哺也。既聞至道而乏丹材，則兢兢業業，遇有餘而好善者，則相貿易也，是名法財兩用，彼此而不欠也，是其心誠之不可移易。", "py": []}, {"t": "其張天台然，其鄧郁之然，其薛紫賢然。子不聞紫賢之說乎？紫賢削髮爲僧，曰薛式，究竟佛法真性，積年無落著。一日寓杏林驛，蒙真人石得之授以性命真要，且戒之曰：疾往通邑大都，依有力者圖而爲之。紫賢從之，是成道焉。", "py": []}, {"t": "子復不聞神仙鄧郁之之事乎？鄧郁之與真人徐靈期遍投師焉，一旦忽遇至人，授以金鼎火符之道，遂謀修鍊，而二人所帶貨財，唯克一人丹材之用，郁之悉讓靈期，靈期得以成道上昇，而郁之聞道乏材，艱難未遂，唯志不移，忽感祖師憐憫。", "py": []}, {"t": "一日，臺司奏云：少微星現，南楚長沙分野。武帝勑採訪之，遂索得郁之以應命。詔問所以，曰：貧道修鍊金液還丹之道而缺丹材。乃賜金帛子女，許於南嶽選地，置上中下三宫，修内外二丹，二年餘，就石壇而升天也。是其心也，急於道成也；是其心也，恐負師㫖也。", "py": []}, {"t": "今時人也，方其未聞道也，亦不知急於聞也，且不知爲道之何謂者也。或因以見之，或偶而聞之，亦不急於行，亦不果於成，唯事多聞也，唯事多知也，唯事辯也，唯事能也，展轉而蹉跎也，依稀而皓首也，同歸于泯滅而已矣。英雄功名，如斯而已；子女玉帛，莫之及已，是之謂下士者也。復有多疑而少信者，謂之常人。又孰知金丹大道是一何事也？是云何謂也？或而聞是道之名也，則毁笑隨之矣。", "py": []}, {"t": "彼人也，其謂仙也謂佛也，天之所生，必從天而墜者也。彼且相聚而議曰：世人而欲學仙學佛者，所謂見者也。噫，覆盆之下而求大明者，實難。曾不知彼醯雞也，離於罌瓿則失夫，又惡知鳥之棲深山也，其飛則沖天，安有區區之戀戀者乎？又惡知魚之遊于江湖也，洋洋焉，悠悠焉，禹門之躍也，三躍而化龍。彼醯雞之卑微也，豈得而知乎龍？彼人也，斯之謂也，豈得而知乎仙？", "py": []}, {"t": "彼人也，乃不知夫即有待之速者也：地也待其齒毛，水也待其血液，火也待其光華，風也待其活動機變。是四者已待之速，而復有待之甚也，是輪迴也，尤速於待者也，又待之多者也。彼人也，甘也分也，曾莫之悔，汝其記之。弟子皆悚慄。上陽子曰：是金丹也，非有大智慧之根器，非有大丈夫之真實，非有大因縁之遭遇，又奚可得而冒聞者乎？今夫真仙聖師，未逢精進勇猛之士，奚又可得而昌禁者乎？", "py": []}, {"t": "弟子伏地曰：願廣慈悲，開濟愚暗。今身不死，是即再入於爐鞴也。弟子誓已，敢問金丹。曰：金丹也，不辭爲汝道。夫得易也，則失於輕；夫妄聞也，則信不篤。上累師資，紫陽真人之慈憫故也。三傳於人而三遭譴，册載事存，可不戒之乎？弟子悲泣曰：宿縁會遇，使走骸餘尸，再生再活，弟子不敢泄慢，不敢背違教㫖，儻渝盟也，則一身屠戮，九祖同愆。伏願哀憫，指示金丹。", "py": []}, {"t": "曰：來，汝之身也，而祖也是積累之有，吾豈不爲汝道也？然知之非艱，而行之惟難，其敬之歟，其愼之歟？弟子再拜曰：師恩罔報。上陽子曰：金丹者，即金液大還丹也。以金而就木液，故謂之還；以金木養煉而成，故謂之丹。", "py": []}, {"t": "何謂金？蓋金者，鉛也，而非世間之凡鉛，非從土石中出者。是鉛也，隱於造化窟中，乃從先天地而生。此鉛既生之後，日夜增長，至二八一斤之數，是云足也，故於後天地而存者也。是以非内非外，而又亦内亦外，是假名之曰内外二丹也。", "py": []}, {"t": "又經云：上藥三品，神與氣精。一切學人，將此經語，直以爲身中之物，乃運氣般精，以爲養神，謂之修行，非也。此精也者，非交感之精，乃金精也；此氣也者，非呼吸之氣，是鉛之氣也；此神也者，非思慮之神，乃金剛之神也。發明到此，方信所謂諸天及人皆當驚疑者也，方知下士大笑之說者也，是故上士聞而勤行者也。", "py": []}, {"t": "弟子敬喜頓首，問曰：既云金即鉛，却云非凡鉛也；既引經言精氣神，又云非身中之物。弟子以幸聞而喜，因聞所未聞而驚者也。願始終開導，以釋下懷。上陽子曰：夫天一生水，是爲氣也。水居北，正北爲坎位，坎中有鉛，故曰非凡鉛，乃真鉛也，是謂鉛之氣也，故曰非呼吸之氣也。何謂金精？夫地四生金，金本居西，西乃兌之正位，取金當於正西兌位是也。", "py": []}, {"t": "大脩行人顛倒取之，蓋先天地之金，乃寄胎于子，子正位爲坎，故於坎中取此金也，是曰金精，是云逆而取之也。坎中之金，乃兌位所寄，乾乃坎兌之中也，故曰乾金。大脩行人取此乾金，歸于黄金室内，運調真火，鍊以成丹，故曰金丹也。弟子感悟，再拜信受，如不勝聞。", "py": []}, {"t": "仙佛長生", "py": []}, {"t": "弟子伏地而起曰：仙也佛也，必是金丹之道而後能證仙佛者乎？上陽子曰：而不聞之老子乎？老子之得无上元君者也。無上元君謂老子曰：子不聞長生乎？長生之功，由於丹；丹之成，由於神。老君得此，勤脩而成。後士成綺問道，老子曰：夫道，於大不終，於小不遺，廣乎其無不容也，淵乎其不可測也。夫至人極物之真，能守其本，故外天地，遺萬物，而神未嘗困也。", "py": []}, {"t": "老子之謂南榮趎曰：能總一乎？能勿失乎？能舍諸人而求諸己乎？能脩然乎？能同然乎？能兒子乎？兒子動不知所爲，行不知所之，身若槁木之枝，而心若死灰。若是，則福亦不至，禍亦不來，禍福無有，惡有人灾？老子之謂孔子曰：至隂肅肅，至陽赫赫。肅肅出乎天，赫赫發乎地，兩者交通成和，而物生焉。", "py": []}, {"t": "夫真鉛者，至陽也；真汞者，至隂也。大修行人將彼先天地之真鉛，歸於懸胎鼎内，以真汞合之，鍊成金丹一粒，吞入黄金室内，養就嬰兒，胎完卦足，神化出入，縱横天地，無有死壞，是爲仙也。帝釋謂釋迦曰：諸行無常，是生滅法；生滅滅已，寂滅爲樂。此即交通成和之義也，釋迦修之而爲佛也。", "py": []}, {"t": "道非言顯", "py": []}, {"t": "弟子復進曰：道即金丹也，而道始無名，至老子乃强名之曰道，而老子著五千言，未嘗言金丹者也，弟子實蒙疑焉，敢問何以？上陽子曰：老子未嘗不言，特不之顯題耳。曰：何謂也？曰：老子曰：常無欲，以觀其妙；常有欲，以觀其竅。此兩者，同出而異名，同謂之玄。玄之又玄，衆妙之門。", "py": []}, {"t": "老子曰：有物混成，先天地生，寂兮寥兮，獨立而不改，周行而不殆，可以爲天下母。吾不知其名，字之曰道，强爲之名曰大。是以後來稱之曰大道者，此也。古之聖人也，或正言，或方言，或巵言，或寓言也。是金丹也，皆存於言之表，而言之中乃含之而已矣，奚可顯而言之者也？", "py": []}, {"t": "曰：老子之不顯言也，千古之上，固未有顯言者；萬世之下，復不可得以言而顯之也。世漸薄而人閉，自非師㫖，寢不可以聞金丹之大道也。曰：昔者廣成子之授黄帝也，廣成子曰：愼汝内，閉汝外，多知爲敗。", "py": []}, {"t": "我爲汝遂於大明之上矣，至彼至陽之原也；爲汝入於窈冥之門矣，至彼至隂之原也。黄帝稽首再拜曰：廣成子之謂夭矣。黄帝修之，鼎湖之舉，騎龍上昇。後之繼脩者多矣，若傅豫焉，若録圖子焉，若務成巢由焉，若善卷錫則焉，若支邑郭叔焉，若老彭鴟夷焉，且隱而深宻者尤多。", "py": []}, {"t": "老子者，猶龍者也，以道爲已也，懼而將息也，乃優游以存其道焉，或出或隱，非世人所能識量者也。故自關令之八傳也，黄石公出焉；又五傳也，河上公出焉；又三傳也，隂徐二真君出焉。魏伯陽真人得之於徐也，乃準易而作《叅同》之書，指出鉛汞砂銀，而以傳于輔元天師也。", "py": []}, {"t": "自張葛許吴之功成，而鍾吕王劉之派接，列仙相踵，子傳序書，皆明此金丹之道也。天台紫陽《悟真篇》出，金丹火候愈明。我師縁督子復作《金丹難問》《仙佛同源》等書，是金丹之道，至此而大備矣。世降人浮，華而不實，上士乃不一見，又安足以語道哉？", "py": []}, {"t": "上陽子金丹大要發真卷之十三", "py": []}]}, {"h": "發真卷之十四", "paras": [{"t": "上陽子金丹大要發真卷之十四睦十紫霄絳宫上陽子觀吾陳致虚撰", "py": []}, {"t": "脫胎去留", "py": []}, {"t": "弟子復進曰：敢問金丹之言脫胎者，何也？上陽子曰：天機深遠，未可猝聞。弟子曰：今而不言也，夫時也者，可乘而不可失，此因縁時節之來者也；今而不聞也，非乘時之謂也。曰：將語乎汝，若秘之焉。", "py": []}, {"t": "夫先天地鉛汞之一合，而歸于黄金室内，是云金胎神室也；却運火行符，十月乃足，是云男兒懷胎也。曰：胎完已後，其功何如？曰：十月功足，是聖胎已就也，則移居上丹田，保養之，長大之。一周二載，則化爲陽神，陽神出入去來無礙，是云脫胎而去也。", "py": []}, {"t": "曰：是則此身，抑有死壞耶？曰：難言也。曰：願師指示。曰：夫一切常人，聞暗識汙，其謂神仙既得道矣，必合留形長生，永居於世者矣，此凡俗之說也。仙與佛則不然。曰：敢問其方。上陽子曰：蓋有身則爲患，仙者欲去其患也。雖然，仙道已成，無所不可，各隨所欲焉。", "py": []}, {"t": "有白日而飛肉尸者，黄帝之謂也；有優游而住世者，彭祖之謂也；有受命而居天職者，天師之謂也；有或隱而或顯者，黄石公之謂也；有拔宅而上升者，旌陽之謂也；有示疾而終世者，重陽之謂也；有尸解而脫殻者，紫清之謂也；有入仕而匡世者，東方朔之謂也。各隨其所欲，初不拘於長生而住世也。口若是則飛升而居天職者爲上，長生爲次，尸解、示疾又其次也。曰：否。曰：願聞其略。曰：子不聞之河上公乎？", "py": []}, {"t": "河上公之居于河濱也，聲聞于闕，文帝車駕禮焉，曰：普天之下，莫非王土；率土之賔，莫非王臣。域中有四大，王居其一。子雖有道，猶朕民也，不能自屈，何乃高乎朕？足使人富貴貧賤須臾。河上公冉冉昇于空中，曰：今上不至天，中不累人，下不居地，何民之有？帝悟禮謝，遂授以《老子章句》，畢，失所在。", "py": []}, {"t": "子抑聞之蘇公堤之說乎？宋有蘇雲卿者，乃管仲樂毅之流也，隱居豫章，張德遠薦以爲相，高宗令其尋訪之。德遠奉命作書，托守臣躬親禀請，及造其所，乃一人獨居茅舍，日以種園織履爲生。得書不剥，佯許詣朝，其夕隱去。", "py": []}, {"t": "翌早，守臣悉來迎接，唯見請書留案，遺一詩云：多年别作一家風，豈料聞名達帝聦。自有時人貪富貴，莫將富貴污蘇公。後名其處曰蘇公堤云。斯人也者，其列禦寇之流乎？其子陵之流乎？其范蠡之流乎？", "py": []}, {"t": "子不聞之列禦寇乎？列禦寇居鄭圃也，四十餘年，人無識者。其始事壺丘子也，聞道而志不篤，復師老商氏，友伯高子，相規以道，禦寇行之九年，乃能御風以行。子又不聞范蠡乎？范蠡之爲越相也，一舉而滅吴，乃曰：功高不可以久處也。遂飄然遊于五湖。齊君聞其賢，往聘而相焉，曰：大名之下，不可以久居也。乃去之，易名更姓，稱陶朱公，將營財以養其老。", "py": []}, {"t": "忽遇濮上人文子者，辛鈃(音/刑)字計然，授以長生之道。乃又曰：財者，所以就事也，道成則無用財也。且財曰利，利能害人，如此則財不可以久積也，孰若吾身之多於財也？竟散其財而隱去，後修其道而仙焉。若此者多，不可以枚數也。噫，彼神仙之云爲，豈世凡所能測之者哉？", "py": []}, {"t": "三教一家", "py": []}, {"t": "弟子曰：蒙師指示金丹之道已，敢問古之聖人立教分三，師乃合三教而歸一家。夫如是矣，道唯一乎，抑有三乎？上陽子曰：天下無二道也。昔者孔子曰：叅乎，吾道一以貫之。老子曰：萬物得一以生。佛祖云：萬法歸一。是之謂三教之道一者也。聖人無兩心：佛則云明心見性，儒則云正心誠意，道則云澄其心而神自清，語殊而心同，是三教之道惟一心而已。", "py": []}, {"t": "然所言心，却非肉團之心也。當知此心，乃天地正中之心也；當知此心，乃性命之原也。是《中庸》云：天命之謂性。《大道歌》云：神是性兮氣是命。達磨東來，直指人心，見性成佛。是三教之道，皆當明性與命也。孔子曰：一隂一陽之謂道。老子曰：萬物負隂而抱陽。六祖教示云：日與月對，隂與陽對。是三教之道，不出於隂陽二物之外也。", "py": []}, {"t": "孔子曰：成性存存，道義之門。老子曰：玄之又玄，衆妙之門。佛云：無上真實不二之門。是云三教各門而同歸者也。是以教雖分三，而道則一也。若言有二者，即非聖人之心也。後之所謂三教者，各指其門，而不能升其堂，況欲入其室乎？是以尊孔子者謂之儒，雖讀其書，而不知其性命之道也；尊釋迦者謂之佛，日拜其佛，而不知屋裏之真佛也；尊老子者謂之道，日遊於中，而不知金丹之大道也，是皆名而不實也。", "py": []}, {"t": "其崇儒者，是非今古，訾毁佛老，却不明孔子一貫之道是何物也；其尚佛者，口談禪機，勤勞枯坐，却不明最上一乘之道是何物也；其習老者，燒竭朱汞，弄盡傍門，却不明金液還丹之道是何物也。若知還丹之道而勤修之，則謂之上仙；若知一乘之道而勤脩之，則謂之真佛；若知一貫之道而勤脩之，則謂之大聖人矣。", "py": []}, {"t": "曰：三教各門而道則一，弟子敬受教矣。而又有一貫、一乘、金丹之道爲異，敢問其名之不同歟？曰：一貫即一乘也，一乘即金丹也，金丹即一貫也。夫人皆禀隂陽二氣之全而生者也，既禀隂陽二氣，則必能變化矣。", "py": []}, {"t": "物之久者成精，松之久者茯苓，魚之久者化龍，草之腐者化螢，而況於人乎？人也者，爲萬物之靈也。人能久固其真也，謂之真佛；人能久存其神也，謂之神仙；人能超凡而入聖也，謂之上聖。皆不離於性命，皆不逃於隂陽，而皆出入於中心，緫謂之金液還丹也，是云聖人無兩心也。", "py": []}, {"t": "曰：上聖大賢，已證高仙佛果，其視下也，一撮爾已，禍福奚爲？乃謗道詆佛之人，多有報之者，何也？曰：否。一切仙佛已成道矣，或居天職，或住世間，以匡救劫運爲心。一切凡間，萬寳供養，百般布施，立寺度僧，寫經造塔，奉迎佛骨，音聲法事，是皆無益。", "py": []}, {"t": "論者亦欲正其所正爾，抑又何罪焉？但其辭峻，又未得其道，乃引古之是而證時之非，不能濟事救時，反成萋菲，旋受其咎，宜矣。彼仙佛者，奚屑屑於是哉？後來緇黄之流，見其排斥之文，以爲詈己，何其昩哉？", "py": []}, {"t": "儒者見佛老之書，不肯深明其道，有可取者，例言異端，即肆詆毁，以昭其名，是又惑之甚也。夫漢之賢，子房爲高，乃從赤松子遊，萬世之下，無能及者；唐之賢，李白爲首，而號爲謫仙；宋之賢，子瞻爲亞，而呼爲坡仙者也。以其教則毁之，以爲異端；以其名則美稱而借重。", "py": []}, {"t": "假使識得其道，而爲真仙真佛，則孰云不美乎？見之偏者，各不識羞，故相毁也。古之聖賢，自相尊禮，唯明是道而已矣。今指佛老爲楊墨，差了多也。況三教多儒名而墨行者，亦多墨名而儒行者，況仙佛乎？上士至人，唯求其道而棄其餘也，故云天下無二道，世人皆得。", "py": []}, {"t": "弟子問曰：古今之所以成仙作佛者，貴富乎，貧賤乎？上陽子曰：此莫得歷歷而盡也。貴富也，貧賤也，皆可脩也，若大路焉，若旁蹊焉，在人之行何如耳。曰：弟子敢問所以者何？曰：昔者黄帝問道於廣成子，廣成子謂黄帝曰：彼其物無窮，而人皆以爲終；彼其物無測，而人皆以爲極。", "py": []}, {"t": "得吾道者，上爲皇而下爲王；失吾道者，上見光而下爲土。今夫百昌，皆生於土而返於土，故余將去汝，入無窮之門，以遊無極之野，吾與天地爲常。黄帝修之，騎龍上昇。", "py": []}, {"t": "無上元君謂老子曰：神丹入口，壽無窮矣。老子修之，是大道祖。後言金丹之道爲黄老術，不知聖人所傳，乃金丹至道，脩仙作佛之大事，非術也，是道也。非得真師口傳，安有天生而自會者邪？人但堅心求師，無分富貴貧賤也。", "py": []}, {"t": "是以老子爲柱史，彭祖爲大夫，仇生仕殷，吕望太師，伯矩爲卿士，尹喜爲關令，辛鈃、崔瞿皆上大夫，庚桑隱毗陵，子休治漆園，留侯帝者師，四皓輔漢惠，常生執鞭，琴高執笏，甯封陶正，方回閭士，輔光仕漢，馬丹仕晋，旌陽爲令，鍾離棄宦，許大雇僕，純陽應舉，海蟾帝君燕國之相，棄富貴而脩行，故有詩云：抛離火院三千口，屏棄門兵百萬家。", "py": []}, {"t": "丹陽祖師，富家者也，兩試殿庭，年四十五，遇重陽翁，乃捐萬有，歸於虚无，待師乞化，備歷苦辛，結譚丘劉郝爲弟兄，自相規戒，忍諸憂辱。其雲遊也，常引古詩云：三山有侣人清淡，四海無家道義深之句。得其傳者亦多，唯黄房公最先道成。我太虚真人得黄房公之傳，以授先師紫瓊真人，而我師縁督子，是得紫瓊之道焉。凡此言其畧也。", "py": []}, {"t": "又如東方朔之於黄眉翁，安期生之於羡門子，鹿皮翁之於王方平，陸脩靜之於孫遊岳，陶弘景之於王知遠，葉天師之於羅公遠，种放之拜希夷，處厚之就紫陽，富韓公之於王沖照，朱晦庵之禮崔子虚，劉志畧交六祖，龐居士禮馬師，傅大士會嵩頭陀，崔相國叅東寺會，陸大夫見投子，陳尚書見睦州，慈明依昭陽，良遂見麻谷，趙霜臺送仰山，楊文公見石門，李萬卷見歸宗，裴相國禮希運，于迪叅紫玉，房孺問國一，韓昌黎禮大顛於廣，李刺史禮藥山於荆，范文正禮古塔主於江東，李文和叅石門於京南，楊翰林禮惠璉於西京，張無盡禮雪峰於湖南，類此甚多，不能悉數，是皆王公大人折節而卑禮者也。", "py": []}, {"t": "雖然，叅有實叅，亦有妄叅。妄叅者，意裏非真；實叅則言下悟㫖。悟㫖者進求，非真則詆謗。詆謗者，豈知自毁？進求者，必成道焉。進者更在心堅，毁者終爲口業。口業者，雖賢能而失本真；心堅者，雖愚賤而躋聖位。", "py": []}, {"t": "信背只在眼下，學者可不戒之？且已仕而聞道也，因在仕以濟其道焉；聞道而未仕也，將假途以成其道焉。或隱於仕宦，或隱於賤役，或隱於城市，或隱於山林。財之足用則散之也，財之不足則求之也，唯務道之成，何分於貴富貧賤？", "py": []}, {"t": "觀水得道", "py": []}, {"t": "上陽子示諸弟子曰：來，予有以語夫汝也。且吾嘗而觀夫水焉，夫水之道，暗合於吾之大道也。子不知夫水之道乎？抑不知夫水之廣乎？則詎得而知乎水之清也耶？子來，且將以語汝也，語汝以水之源者也。子學夫道而不知水之源，其於道也，若有適而不知其舍也，則將焉往乎哉？今語以水之源。", "py": []}, {"t": "其源也，縣崖壁立，孤峰危峭，峻險萬仞，仰之則彌高，曠穴難測，鑽之則彌堅，思而不可得，瞻之在前，見之不可用，忽然在後，是聖也，是凡也，是神也，是鬼也，目如奔電，不敢以一窺也。深窈窈焉，黑漫漫焉，須彌山上望之，若大海焉。此爲水之源也，故名之曰涅槃境界。", "py": []}, {"t": "其中有泉出焉，皎皎如甘露，滴滴如明珠，溶溶似龍涎，涓涓似骨髓，亦瓊漿之謂也，亦酥酪之謂也。其始之流也，若經乎洪波穢濁，待夫兩晝夜，旖旎乎三百里，此焉而得水也，是水之至清者也，是云水之源者也。有華池焉，有曲江焉，有癸穴焉，有庚渦焉。此水也者，其白如銀，其清透底。且吾得聞至人之真言也，至人曰：水之清也，中有白金，化爲黑鉛，紛紛如空中雪，皚皚若太素烟。此水也，得先天地一陽之正也。", "py": []}, {"t": "此水也，不寒也，冬温也；不熱也，夏凉也。熱熱者浴焉，思渴者飮焉。飮此水者，無飢渴之害也，無睡眠之惱也，無生死之念也。子其記之。是水也，或清或濁：濁者遠而清者近也。濁也者，人飮之而醉也；清也者，人得之而醒也。是水也，又流五百里而漏焉。當其漏也，弗覩也，無庸而知也。行且一月矣，至于萬丈洪崖壁絶之口，有月窟焉，有子匯焉，又有子午谷，有金華池，於此而復得其源，是源之再清也。", "py": []}, {"t": "或𥗋焉而逆注，或寖焉如血液，或浮焉如素練，或科焉如碧潭，恍惚杳冥，總流而合于溪，溪合而會于河也。至河則汪汪焉，湯湯焉，浩浩焉，渺渺焉，不可測其涯涘也。于是時也，私謂得其水之至矣，而猶有所未至者也。於是分涇渭，泛五湖，泝黄河，清流也則行焉，洪波也則息焉，遨遊而至于大海也，乃索焉而驚：大海者，無邊際也。專于一誠，戰戰兢兢，唯一精純，則不至於喪身而失命。子其記之。", "py": []}, {"t": "吾復聞至人之言曰：大海者，天下之水歸焉。昔蒙莊之鵬運也，以六月而一息，其息也者，則飮于此海也。子其記之也。大海者，人不得而窺其洋也，不得而測其深也，不得而知其廣也。有真人焉，吾就而問之，真人之㫖曰：大海者，萬谷所以流入者也，百川所以歸納者也，爲江漢之所宗朝者也。", "py": []}, {"t": "真人之㫖又曰：此特其近焉者耳。夫知大海之說者，水逆流焉。大海之水逆流者，上接于天河。水之逆流至于天河，故有一消一息之道焉。子其記之也。夫水之逆流，是水之至者也。吾乃今而所以知得水之至者矣。夫得水之至者，有道存焉。子其記之也。與弟子曰：諾，水之至者有道存焉。", "py": []}, {"t": "上陽子曰：汝來，吾復有以語子也。且吾嘗而學焉，其昔之爲學也者，工駢儷，習聲律，窮今古，喜註述，談性理，分是非，大而易，小而術，益不倦于學也，私謂爲學之至矣，而未知其有所未至者也。且不知夫世之有真人者也，抑不之信世有成仙作佛之道者也。我師趙真人，從太滌山脩行來，授我以金丹之道，並合天河逆流之說，吾乃今而所以知爲學之有夫至者矣。子其記之也。", "py": []}, {"t": "水之道，未至逆流，則不知其極也；人之學，未聞長生之道，亦未爲學之至者也。夫海之接于天河，則知水有逆流之道；人之爲學而知夫道，則知身之可以長久。子其記之也。與弟子曰：諾。爲學而知夫道，則知身之可以久長也。是聞一也而得三焉：得水之道焉，得爲學之道焉，得長生久視之道焉。", "py": []}, {"t": "見性成佛", "py": []}, {"t": "弟子問曰：天下無二道，固則然矣。老子之道，唯金丹之道；金丹之道，是性命之道也。而達磨西來，唯直指人心，見性成佛，豈此而出金丹之外乎？上陽子曰：達磨之道，即金丹之道也。世人根器，各有利鈍，佛祖慈悲，方便立名，後之學人，智者過之，愚者不及也。", "py": []}, {"t": "夫何以故？智者不明脚跟底實際裏一件大事，輝耀今古，迥脫牢籠，能殺能生，一死一活，此處既昧，則任脚跟走也，故云過之。愚者不問肉團上有箇無位真人，擔荷大事，此處既昧，却以誦經念佛、持齋兀坐，將此而求見性成佛，抑何愚哉，故云不及。", "py": []}, {"t": "曰：見性即成佛乎？曰：傅大士云：饒經八萬劫，終是落空亡。夫見性猶聞道，而成佛猶成道也。聞道須行，故上士聞道，勤而行之；見性須脩，故雪山脩行積年而證佛位。奚有不學不脩，而以見性爲成佛乎？問曰：蠢動含靈，皆有佛性；又曰見解智識，爲靈明覺知。", "py": []}, {"t": "二者云何而能成佛？曰：見解智識之性，不能成佛；唯蠢動含靈之性，則能成佛。曰：異乎所聞。敢問蠢動含靈之性，爲己性乎？曰：然。曰：何哉？曰：然，見解智識，乃是非業障之性；此蠢動含靈，乃造化萬物之性。人唯不知蠢動含靈之性，所以難逃生死，迷於涅槃。", "py": []}, {"t": "彼見解智識之性，以聲色爭愛而爲執著妄想；此蠢動含靈之性，處污穢而有大機大用。彼見解智識之性，起於六賊門頭，日爲恩愛纏縛，無有休歇；此蠢動含靈之性，在脚跟後，如如不動，得大自在。古德云：地獄未苦，袈裟下不明大事，是爲最苦。世人豈認蠢動含靈之性，即真佛性？悟此真佛，則知屋裏自有，却非木雕泥塑，故云真佛屋裏坐。到此方爲見性成佛，所以道即心是佛。", "py": []}, {"t": "若不悟屋裏真佛，即我之真性，却認見解智識之性爲佛性，猶認他姓爲我子，差了多也，所以道心不是佛。既悟我之真性，即屋裏之真佛，則此性此佛，猶是四大假合底，未及長蘆四會之功，所以道非心非佛。若悟我性是我真佛，分明了也，假之而修，假之而成，所以道見性成佛。故雪山四十二年，少林九年冷坐，實皆爲此一段公案者也。", "py": []}, {"t": "上陽子金丹大要發真卷之十四", "py": []}]}, {"h": "越格卷之十五", "paras": [{"t": "上陽子金丹大要越格卷之十五夫一紫霄絳宫上陽子觀吾陳致虚撰", "py": []}, {"t": "與王祥翁", "py": []}, {"t": "淨倮倮，赤洒洒，是一大事因縁，是箇見成公案，有大力量，宻示神通，立極造端，撑天拄地，逈超宇宙，獨耀古今。無始以來，靈光不昧；窮劫之際，真性常存。上聖至人，高仙諸佛，由此施設，由此儀刑。", "py": []}, {"t": "所以道：三世諸佛也恁麽，彌勒下生也恁麽，七佛已前也恁麽，七佛已後也恁麽，西天四七也恁麽，唐土二三也恁麽，歷代佛祖都恁麽。且道古人千般計較，都不會安名，也不肯立字，唯唤作恁麽。子細看來，無頭無尾，無背無面，總只是恁麽了也。", "py": []}, {"t": "自從達磨西來，至于曹溪，單提别唱，而後天下叢林偉器，以恁麽事話會不少，就中更無一人肯爲他標箇名目。若是箇大善知識出來，或者脫却娘生袴子，未舉先知；若是鈍根，都教他向人前句裏說心說性，尋箇本來，認影認光，竟無落處，到老破賺，却去怨祖怨佛。", "py": []}, {"t": "此輩可深惜哉。上陽子只得不惜舌頭，爲他前聖後聖，說出極到之處。且道如何是恁麽底？當知這恁麽，即是那淨倮倮赤洒洒底。天下後來都會得那倮倮洒洒，即是恁麽事也。", "py": []}, {"t": "則知父母未生以前，也恁麽倮倮洒洒；父母既生已後，也恁麽倮倮洒洒。一大事因縁也恁麽倮倮洒洒，這見成公案也恁麽倮倮洒洒。", "py": []}, {"t": "只今箇樣分明說了，後之人纔舉目看，便知倮倮洒洒即恁麽底，恁麽即倮倮洒洒底，夫復何疑？豈不道：昔日摩耶夫人左手攀枝，釋迦老子右脇降誕，九龍吐水，沐浴金軀，便乃周行七步，目顧四方，一手指天，一手指地，作大獅子吼云：天上地下，唯我獨尊。一場話靶，古今禪林舉揚者多也。有作實事看去，也有作靈迹看去，也有作怪異看去，也有作話會看去。", "py": []}, {"t": "今若不饒露箇消息，把釋迦老子只容易看過了，將來孰肯承當？且道：摩耶左手攀枝，釋迦右脇降誕，豈不是他離了生死岸頭底？那九龍吐水，沐浴金軀，豈不是那恁麽淨倮倮赤洒洒底？周行七步，目顧四方，豈不是貌堂堂顯露底？一手指天，一手指地，豈不是八字打開中有箇見成公案？作大獅子吼云：天上地下，唯我獨尊，豈不是一大事因縁，人中最爲第一？點檢將來，也是好中不足，暗裏藏刀。", "py": []}, {"t": "後來雲門道：我當時若見，一棒打殺，與狗子喫，貴圖天下太平。雲門拳拳奉揚宗㫖，只得恁麽駡佛喝祖。及後圜悟云：釋迦把斷要津，雲門知恩解報。他豈不知釋迦無伴無侣？是以雲門特恁欺主，圜悟深知家醜，却又白日叫鬼。", "py": []}, {"t": "且似這般話頭，是障礙底，是方便底？若謂障礙，是瞞你了；若云方便，目前便見。是臨濟云：赤肉團上有箇無位真人，當從諸人面前出入，豈不是直指了也？一切常人，暗中摸索，是又不是。他器識底，直下便知那無位真人，即是恁麽淨倮倮赤洒洒的。", "py": []}, {"t": "古聖云：性由自見，命待師傳。若本分底，有箇真實，方寸之下，真常獨露，全體見成，何必又待許多詮註？便知淨倮倮是真佛性，赤洒洒是真佛性，一大事因縁、恁麽見成公案，無非是真實佛性底。莫道釋迦老子有此一箇大事因縁，各各當人分上，皆有如是一大事因縁，元不闕少，盡乾坤大地，一時收來。雲門出世也道一句不得，圜悟再生也不敢擬議。於此處便知性是自家底，世人如何瞞得自家？方知道性由自見。", "py": []}, {"t": "若到這田地，深深宻宻，儘他業風沙起，滄海塵飛，須知淨倮倮底如如不動；那赤肉團上，穩穩當當，儘他萬生萬死，須知這赤洒洒底如如不動。此爲不落窠臼，不迷境物。磨睚到臘月三十夜，孤燈自照，忽聽漏盡鍾鳴，又說新年佛法去了，豈不是大解脫、大光明，不迷生死岸頭，不拘得失流轉？當知龍光佛時，也只恁麽來也。若搆得去，與三世諸佛齊肩，彌勒爲奴，亦不小了。", "py": []}, {"t": "大丈夫漢，切莫做箇矇矇𥋾𥋾，當斷不斷，脫衫着袴，無有了期。疑上疑下，着實說空，語言裏尋窠窟，文字裏尋公案，是皆妄想，何時得返照回光，脫胎换骨也？我趙老師云：今時人脚跟前、脚跟後，不認點地處，即是這箇了。却乃無端指性說空，直賺到老。", "py": []}, {"t": "只如此語，豈不脫露機鋒？然這老師舌柔齒剛，不許人道恁麽，亦不許說倮倮洒洒，亦不許說見成公案，亦不許直指，亦不許棒喝。如是豈不作家？縁爲時人將他佛祖面目，做情識見解去。我這老師接上等人，唯撑眉弩目便是；下梢却饒一笑而已。", "py": []}, {"t": "予過荆南，逢一偉器，祥翁道人，自叙往者訪謁禪林，深得其趣。詢之，乃應菴之裔也。其師瞎翁，每指云：與他相挨厮伴，暫時不得捨離，方有少許入作之分。又云：更須識取箇空爛底髑髏，試向夜靜燈滅時，打箇蒲團獨坐，宻宻地體取。", "py": []}, {"t": "只這語言，瞎翁費盡老婆心多少了。常人看來如此，予謂瞎翁不當引人落草，千古之下，惹人提掇，無有了期。雖然，入作底事，還要入作底人。故其所出金剛九還大義，乃曰：佛示初中後三日分，豈非入作事也？", "py": []}, {"t": "祥翁自倮倮洒洒而來，藴利根智，得師印證之後，而唯獨一無侣，二六時中，認主人翁，以此自照。比來請益，求脚跟轉處一句，乃爲普說倮倮洒洒之真諦，使祥翁權以金剛爲體，實以涅盤爲用，淨倮倮作大獅吼，赤洒洒奮雄虎勢，得了便住，遇縁即宗，然後懸崖撒手，大休歇去，豈不是箇少林冷坐底工夫也？到此方知，非唯脚跟轉處事，須知親爲佛子已上事也。", "py": []}, {"t": "此去諸方，遇著衲衣下瞌睡漢，不妨饒舌云：是我普說。拄杖刹竿，棒拂拳喝，一機一境，是皆佛祖旁開户牖，提振綱宗，亦有大機，亦有大用，亦有權，亦有實。一喝不可作一喝用，一棒不可作一棒行。要知賔主交參，前後際斷，昭懸日月，把定乾坤。", "py": []}, {"t": "在昔阿難問摩訶迦葉：世尊傳金襴袈裟外，别傳何法？迦葉唤云：阿難。阿難應諾。迦葉云：倒却門前刹竿著。此豈不是直指人心，獨露全體？則知當年世尊所傳涅槃妙心、正法眼藏，只消迦葉一句，總在裏許。", "py": []}, {"t": "雖然直截，要先識破他的處，將如之何是他底處？世尊傳來，饒得微笑；迦葉傳來，饒得一唤。只此一笑一唤，方知佛祖無可柰何，落草尋人。若不恁地，怎得那西來意？怎得箇消息底？這般提唱以來，厥後諸佛諸祖，遇因立縁，隨方設便，以棒拂拄杖行，不如一喝，省了多少計較。", "py": []}, {"t": "除非明眼人，舉頭便知。是故馬祖一喝，百丈三日耳聾。喫茶也是，受食也是，鼻孔也是，靈骨也是，即心即佛也是，非心非佛也是，一株花、栢樹子、麻三斤、衫七斤，風與月，石與泉，前聖後聖所遺公案，一題著，緫是了；若使鈍根之器，到了緫不是也。", "py": []}, {"t": "只如釋迦老子云：以大圓覺爲我伽藍。圓覺且置，且道如何是伽藍？後來舉世以伽藍爲招提所在、僧衲所住者，尤爲可笑。却不知伽藍本是一物，故下云：身心安居，平等性智。今之禪僧，言及平等性智，便自無處尋頭，況與他說伽藍？有般强底人，見人題平等性智，隨云是他的心，又怎知道他心非是心？故佛祖云：非心非佛。", "py": []}, {"t": "又云：心不是佛，智不是道。佛祖慈悲，爲一切人自性不明，起立模樣，令人自像，故不得已，乃至堅拳倒拂，吐舌低頭。其以此機，至淺至近，令人易見，而一切人不肯承當，遂至騎山門向佛殿上，放佛殿於燈籠内。", "py": []}, {"t": "且道：佛殿須要供佛，如何移山門於其上？豈不觸了？燈籠内著佛殿，大似光燦燦地。又至山河大地、須彌崑崙，有輩禪流，見此等語，渾如嚼蠟，全無意義，總謂禪機葛藤，置而弗看。", "py": []}, {"t": "難似佛果云：上無攀仰，下絶已躬，外不見大地山河，内不立聞見知覺，直下擺脫情識，一念不生，證本地風光，見本來面目，祖師心印，何幸人人領悟，箇箇圓成？挨拶將來，了不可得。及至末後，喝佛駡祖，走釋迦奴彌勒。凡此皆要諸人各認自己心，莫作他人見。", "py": []}, {"t": "誰知後來，見喝也喝，見駡也駡，不知古人向自身内說將出來，暴露消息底意。那一等人，專事機鋒，待爾招積口業，總迷了這箇道理。饒他聲前句後，尋覓猜想，明來暗合，也只野狐精見解。", "py": []}, {"t": "一到如此，奚謂五百年？縱萬劫千生，何時是了？古之人藴大根器，若不猛利，猶自蹉過。是以圜悟奮志，南詢長慶，坐破七箇蒲團；雪峰三登投子，九上洞山；馬祖因悟磨磚，六祖躬役碓舂，二祖斷臂立雪，釋迦聞半偈而捨全身。古聖先賢，波吒到了，方討得箇生死義路。", "py": []}, {"t": "今時人也，口誦堯之言，而行桀之行，皆是笑破自己心，賺破他人口。若人人到那田地，猛着力，暗中求，不驚不疑，無退無轉，忽然相似，脚跟後穩穩當當，綿綿宻宻，照天灼地，豈不是彌勒下生，釋迦親見？到彼時節，回首覷著一切常人，皆立下風，方知道有何難事：低一著是凡，高一著即佛了也。", "py": []}, {"t": "真法眼", "py": []}, {"t": "問云：佛法還有本末也無？上陽子曰：自威音王已前，佛生佛滅，綿綿歷歷，不可窮已。從過去莊嚴劫來，曼殊室利爲七佛師。至見在賢劫，釋迦文佛告摩訶迦葉云：吾以正法眼藏、涅磐妙心、實相無相、秘妙大乘，今付於汝，汝當護持。迦葉禮足，白言：我當體敕，恭順佛故。自爾燈燈相續，至菩提達磨，受法於般若多羅，乃至中國，而得總持、道副、道育、慧可四人，乃授法焉。", "py": []}, {"t": "後將西返，謂道副曰：汝得吾皮；謂尼總持曰：汝得吾肉；謂道育曰：汝得吾骨；謂慧可曰：汝得吾髓。復云：昔如來以正法眼藏、涅槃妙心，付大迦葉，展轉祝累，而至于我，我今付汝，汝當護持。慧可傳來，唐土二三，逮至慧能，遍傳天下，於是濫漫矣。故達磨告慧可云：二百年後，法周沙界，明道者多，行道者少；說理者多，通理者少。就中有能悟實際地，了心空法，三身清淨者，然後得證大乘也。", "py": []}, {"t": "宻多聞越次問曰：大乘、中乘、小乘，此三乘法，皆成佛否？上陽子曰：唯正法眼，是爲最上一乘。故經云：十方佛土中，唯有一乘法，無二亦無三，除佛方便說，但以假名字，引導於衆生。吾所以云中乘小乘皆假名字，唯最上一乘，真空無漏，真實希有，無非以真心真空爲之極則爾。豈不聞大珠和尚云：心是佛，不用將佛求佛；心是法，不用將法求法。佛法無二，和合爲僧，是謂一體三寳。則知三寳本同一體，奚有二乘乎？", "py": []}, {"t": "妙香佛陀問曰：如來說法，學人聽法，聽法說法，有功德否？上陽子曰：如來證佛，爲上根菩薩說法，以度天人，非如阿含爲小機說也。故提婆謂羅㬋羅多云：本對傳法人爲說解脫道。盖諸說法聽法者，本具一體三寳，方能說，方能聽。一體三寳者，法身、報身、化身，三身是曰一體三寳。昔神會大師云：說法則先佛而後法，聽法則先法而後佛；聽法則頓中而漸，悟法則漸中而頓。", "py": []}, {"t": "故色身善說法，則法身低頭稽首而聽法；法身善說法，則報身摩肩聳耳而聽法；報身善說法，則化身清淨無爲而聽法。然四大色身、法報化三身，俱不解說法聽法，唯座上有一無位真人，善說法聽法。是以義玄和尚云：虚空不解說法聽法，是汝目前歷歷孤明勿形聲者，解說法聽法。所以道：心法無說，佛法無聽。", "py": []}, {"t": "多口阿師問曰：三身且置，云何是色身？云何是法身？上陽子曰：色身是幻身，亦是妄身；法身是清淨身，亦是圓滿身，亦是自在身，亦是如來身，故號爲真佛。大鑒云：色身雖大，内心量小，不名大身；法身雖小，内心量大，等虚空界，是名大身。", "py": []}, {"t": "此即佛性，此即真心，諸修行人把他做箇主人翁也。所以佛祖安名立樣，棒拂拳喝，燈籠佛殿，拄杖刹竿，千般計較，形容不到了，處是謂不可思議功德。然隨用而立名，借物而喻色，總而論之，只是箇功德法身也。", "py": []}, {"t": "法體如如問曰：三世諸佛，還住世否？上陽子曰：過去佛，過去已；未來佛，且未至；見在佛，不得見。曰：我師還見否？曰：汝爲甚不見？曰：有形容否？曰：尋常頂禮，接引衆生。曰：我師獨見，復誰可見？曰：見者不說。曰：我還可見否？曰：汝不信佛，佛不汝見。如如低頭曰：發心信已，若何見佛？曰：開汝一隻眼，佛即在目前。曰：過去佛神通若何？曰：覆載包含。曰：現在佛神通若何？曰：生育造化。曰：未來佛神通若何？曰：多寳藏將開也。", "py": []}, {"t": "曰：云何是寳藏義？曰：緫歸一大藏。曰：一大藏教，云何指示？曰：普攝有情。曰：大藏亦有情乎？曰：無情。若何名藏？因爾無情，强名曰正法眼。縁此法眼，不屬内外，不在四旁，秉生殺機，爲佛法祖，是曰正法眼藏。曰：正法已聞，若何是眼藏？曰：汝且道什麽一件物無眼？曰：此眼藏即虚空藏否？曰：佛法一般，名不虚設。", "py": []}, {"t": "夫叅學人，莫學客語，莫學異見，須知脚跟有此寳藏，大包天地，光耀古今，形容無盡，妙用無窮，故云無盡藏。物去物來，如如不動；亘古亘今，如如不動；生死岸頭，如如不動，得大自在；如如不動，演出大藏，皆如來說，故云如來藏。", "py": []}, {"t": "寳如意問曰：迷悟兩途，迷者多而悟者少，敢問何以？曰：昔南陽忠國師云：衆生迷時，結性成心，猶寒則水結爲冰；衆生悟時，釋心成性，猶煖則冰釋爲水。上陽子復喻云：衆生迷時，猶隔水而求魚；衆生悟時，猶水涸而魚鱉自現。是慧海云：凡夫見性，即非凡夫，以能頓悟上乘，超凡入聖；佛子若迷，即非佛子，以其論凡論聖，終爲下鬼。", "py": []}, {"t": "悟人超越生死涅槃，迷人唯學說事說理。迷人今生作來世福德，悟人目下頓見活維摩。所以迷底人，修因待果，如逆風而渡海，何有了期？悟底人，了心是佛，似月下觀影，真僞自知。故毱多尊者云：心自本來心，本心非有法。則知本心無法，而本來心乃是法身。是以迷人以清淨法身爲五藴色身，悟人以清淨法身爲我佛法身也。", "py": []}, {"t": "優婆夷多問曰：自曼殊室利而七佛，法偈皆言幻起滅空罪福；至釋迦傳來言法，而十七祖僧迦難提以來，又言心地；二十二祖摩拏羅以後，皆言性；二十七祖般若多羅，與唐土二三佛，又只言華種；及曹溪别唱，天下老和尚，唯直指單提，各呈面目，千般百計，指小喻大，有如山河大地、棒拂花草、燈籠佛殿、拄杖拳喝，似此等樣，以爲傳授大乘，何前後之相戾也？敢問是同是别？", "py": []}, {"t": "上陽子曰：迷人說法，迷法見性，迷性；悟人悟空非空，悟色非色。故前迦葉云：即此身心是幻，生幻化之中，無罪福。後迦葉云：何於一法中，有法有不法？十八祖迦耶舍多云：有種有心地，因縁能發萌。", "py": []}, {"t": "二十五祖婆舍斯多云：我今悟真性，無道亦無理。東土二祖云：本來縁有地，因地種華生。此祖祖燈燈，唯在明心而已。自風旛論後，各立宗門，别出模樣，直到于今，豈離心之外而别有大乘者乎？離大乘之外而别有佛法者乎？", "py": []}, {"t": "大傳送問曰：夫生而有形，死而魂散，有形則有性，魂散則性泯，理之常也。比形住而性存，猶華之有香；比身逝而魂去，猶葉之墜地。雖然，人爲萬物靈，到此得有性也無？上陽子曰：造化之内，無明殻子爲卵生，煩惱包裏爲胎生，愛水浸潤爲濕生，欻起煩惱爲化生。", "py": []}, {"t": "四生之中，各從其類，狐兔不能産鳳，明也。爲人之靈者，本性而已。性之於人，猶烟焰之於火，泡漚之於水。形存之性，猶火之飛焰；魂散之性，猶漚之歸水。此一切人失其真性，流浪輪迴，萬死萬生，迷迷相指，皆謂如是。", "py": []}, {"t": "道人之性則不然，超乎造化之外，生以不生，死以不死，亦唯真性而已。守此性如防盜焉，敬此性如供佛焉，愛此性如護寳焉。是故法此性，即名法性；佛此性，即名佛性。若見此性，即是佛地，豈干生死之義乎？十四祖龍樹云：佛性非大非小，非廣非狹，無福無報，無死無生。所以悟我性無生死，見我性無地獄，修我性超乎造化之外也。", "py": []}, {"t": "上陽子金丹大要越格卷之十五", "py": []}]}, {"h": "超宗卷之十六", "paras": [{"t": "上陽子金丹大要超宗卷之十六夫二紫霄絳宫上陽子觀吾陳致虚撰", "py": []}, {"t": "見性成佛", "py": []}, {"t": "上陽子曰：威音王已前，這一段公案，不在左右，不在偏傍，不在中間，不在外。當其時也，既無師匠，又無宗㫖，七佛且未出世，彌勒尚未下生。此一大事，出模走樣，照天爍地，哆哆和和之後，佛已在世，人人具足，箇箇分明了也。爾來到今，而一切人將自己的别了，尋問他人。", "py": []}, {"t": "且道他家底事，豈容你知？猶你家下之事，容他知否？所賴先哲慈悲開示，祖祖單提，達磨大師直指人心，見性成佛，大過則了。豈唯後人愈行愈遠，總將日用現前一切不問，却乃千思萬想，向那邊覓，而欲見性成佛。此輩可深惜哉。豈比天人師，明星出時，成佛了也？", "py": []}, {"t": "弟子再拜稽顙，問曰：傳云：釋迦生下，周行七步，一手指天，一手指地，曰：天上地下，唯我獨尊。若是，則世尊生而知之者也。上陽子哂之曰：非也。曰：敢問所以。曰：釋迦文師瞿曇，乃得金丹之道，修之而證佛也。以其修金丹而成仙，故曰金仙。盖金丹者，二八兩之弦氣也，二八合成一十六兩，故云丈六金身。", "py": []}, {"t": "世豈有天生自然之釋迦者乎？曰：唯我獨尊，復從何來？曰：此佛法之謂也。曰：敢問所以。曰：後之佛祖，將此語題以爲公案，因謂之佛法，使後之學人，藴利根上智者，以此公案，常題常拈，照破自己脚跟踏實，而明心焉，而見性焉，轉相悟入。因之仍之，佛祖繼出，各呈面目，形容益多，語殊意合。", "py": []}, {"t": "是以非理可釋，思議不得，或以小而喻大，或以賤而比貴，不涉程途，難堪訓誨。大根器識，一見了然明白，更不驚疑，直下承當，有何言句？下士愚人，思攷不能得，擬議又不是，只得妄云：此乃葛藤之語也。若有問其如何謂之葛藤，則謬云：即禪機也。", "py": []}, {"t": "如此宛轉支離，却不究竟佛法實事。所謂葛藤禪機之語者，乃齒外之浮辭，而爲佛法之喻也。唯大智慧底，則去其口頭之虚論，而見其佛法之真實也。下愚之人，誑談鋒辯，至有公案非理可釋去處，則去禪機也。彼以禪機爲辭之屬底，如百尺竿頭，不復可進，又安知有佛法哉？", "py": []}, {"t": "弟子進曰：佛法者，世尊以靈驗而示人乎？抑以天龍護衛之神而見之乎？曰：皆非也。此乃常人所談之佛法也。今夫生死禍福，影響靈驗，幽冥報對，浮辭彰虚，以示於人者，此之謂常人之佛法也。若真實佛法，唯靈於己，倏忽廣大，變通須臾，而復自在，廼能過人之過，而亦自知其過，此爲真實佛法也。盖真實佛法，聖凡不敢一窺，況可以示人乎？若真實佛法，則諸天捧花無路，魔外潜覷不得，況云天龍見之乎？", "py": []}, {"t": "曰：如此，則佛法之大，唯世尊能有也。曰：世尊已無佛法，唯人有佛法。曰：人之佛法，復在何處？曰：挂向太虚，壁立萬仞，視之不見，聽之不聞。曰：有靈驗否？曰：顯大神通，霔大法雨，撑天拄地，作佛成仙，古今專生殺之權，頃刻有感通之便。是十翼曰：寂然不動，感而遂通。故鬼神不敢視，邪怪不能憑。", "py": []}, {"t": "所以破竈墮云：本是泥土合成，靈從何來？聖從何起？諦觀此語，豈非大靈驗乎？何者是人之佛法？曰：人以性爲佛法。曰：既以性爲佛法，則諸佛祖、一切常人，皆以見性而成佛，是不必於金丹之道也。曰：否。曰：何謂也？曰：一切常人，且不知性爲何物，而假言金丹之道乎？曰：一切常人，唯不知性，而諸佛祖是見性而成佛也。曰：否。曰：請問其義。", "py": []}, {"t": "曰：子不知夫達磨之說乎？昔者達磨西來，不立文字，唯直指人心，見性成佛，固有其道矣。盖道之一事，不可得而形容思議者也，如之何可以立文字？且人心不可得而聞見者也，如之何用直指？人之性即真佛者也，如之何待見而成乎？此即老子觀妙之道也。", "py": []}, {"t": "是以達磨下工於長蘆，於少林修鍊，是云金丹之㫖，即達磨直指之㫖，即釋迦獨尊之㫖，即迦葉所受正法眼藏、涅槃妙心之㫖，即馬祖非心非佛非物之㫖，即六祖共永嘉無生無速之㫖，即龐居士悟一口吸盡西江水之㫖，即藥山一物不爲頭之㫖，即丹霞燒水佛之㫖，即石鞏弓箭之㫖，即趙州蘿蔔、栢樹子、喫茶之㫖，即歸宗先天爲心祖之㫖。", "py": []}, {"t": "以至山河大地、拄杖刹竿、棒喝露柱、燈籠佛殿、山門庫堂、金剛王寳劎、洞山麻三斤、石霜百尺竿、俱胝脂頭禪、黄龍赤班蛇、鳥窠吹布毛、法燈天真佛、法眼透聲色、思和尚米價、遵布衲浴佛僧、奚仲造車、孚上座摇扇、雪峰輥毬、雲門胡餅、鹽官扇子、青平搬土、潙山水枯、禾山打鼓、秘魔持叉、香嚴擊竹、首山竹篦、仰山拂子，以至頂門拳肘、眉眼鼻尖、米粟絲毫、釘鞋木履、清風明月、曉鍾畫角、芥子須彌、圈蓬漆桶、銀山鐵壁、葛藤寒松、黄花翠竹、枯椿乾橛、古澗寒泉、源頭路口、翅爲獅兒、大雄猛虎、牛車羊角、狗子猫兒、胡孫鼷鼠，此等公案，備難悉數，莫不皆是見性之㫖也。", "py": []}, {"t": "上陽子復謂弟子曰：從上祖佛，做模打樣，百般遷就，托物立名，爲一切人指箇真實佛性之處。然其各隨方便而說，謂之隨方結縁。而一切人不到性地，及爲多事，如引過河之網，未提其綱；若牽織金之花，不編其綜。", "py": []}, {"t": "吾今分明指出了也，似風雲雷雨，驀然黑暗，須臾散去，紅日當空，誰不見了？恐你諸人以光明之眼，如翳障了；以智慧之性，爲塵撲之。一向弄舌頭，不顧損神氣，是又不是，修又不修，如此蹉過，走破脚跟下皮肉，賺到老來，可惜了也。", "py": []}, {"t": "比來說禪者，明立高座，聚衆問答，口頭活弄，性地蒙迷，以辯論敏捷爲能，所以多記公案爲明了。人示以一指，隨以二指應；或而向下，他即儗上；或云眼前，即疑背後；或轉脚跟，他便走了。似此捏僞，那知真實？此爲設辭應敵，豈能見性明心？如與聾人覓物相似：與之索蛤，聾乃掬水；指令下鞍，聾反勒馬；指向脚下，聾遍拾芥。", "py": []}, {"t": "雖云近傍不遠，孰知所差太多？此乃聾人誤聽强猜者。今一切人，本皆聦識，見物如蔽，若彼聾人，强猜妄臆，其中以誤爲悮，能有幾人？不免再爲諸人各各現箇本來面目，這回莫只又做箇矇𥋾底人也。", "py": []}, {"t": "圜悟云：父母未生以前，淨倮倮，赤洒洒，不立一絲毫；及乎既生之後，亦淨倮倮，赤洒洒，不立一絲毫。佛祖慈悲，興言至此，欲爲世人作箇指蹤極則。而一切人既聞此語，便以倮倮洒洒爲冷俐快活看，却不知倮倮洒洒即本來面目也，即是性也。", "py": []}, {"t": "且道既生之後，倮倮洒洒，不立一絲毫，鈍根錯想而不明了，亦不足怪。何以故？此盖常人而紐於常也。且道云何父母未生以前，亦云倮倮洒洒，不立一絲毫？此言殺過則了，利根之士，即於見前，早辦一箇入頭之處，安有不明了哉？", "py": []}, {"t": "吾之說此者，非但爲汝諸人提題拈起，亦使叢林禪僧、天下一切人，誦此《金丹大要》，究竟超宗釋義，如懸夾鏡相似，人立其中，若頂若足，若背若面，不必求人，莫不自見。如今多少住禪刹者，不知禪是何物，率三二百人，或至千數餘衆，唯只頑坐。", "py": []}, {"t": "禪棒夜巡，渴睡者辱；日則限以規程，何暇見性？夜則勞神廢寢，安知真佛？此謂一盲引衆盲也。豈不聞大慧云：一種杜譔漢，脚跟下不實，只管教人攝心靜坐，坐教絶氣，真可忴憫。六祖又云：長坐拘身，是病非禪。", "py": []}, {"t": "石霜諸禪師，堂盈千數，長坐如杌，識者呼爲木衆橛多。三藏師於曹溪大鑒，一日見僧結菴而坐，藏即前唤之曰：我西域最下根者，不墮此見。馬祖南岳住菴，日唯坐禪，以求成佛。讓禪師故將甎於菴前磨，祖云：何爲？曰：磨作鏡。祖曰：磨甎豈能作鏡？讓曰：然，坐禪豈能成佛？馬祖頓悟，言下得㫖。昔玄沙因共雪峯論佛法，峯云：世間闊一丈，古鏡闊一丈。沙指火罏云：闊多少？峰云：如古鏡闊。沙云：老和尚脚跟未點地在。", "py": []}, {"t": "從那到今，有輩禪流，因名行脚，摇唇識解，不知落處，走遍叢林，踏破了草鞋，不肯認他脚跟。如之何是點地處？佛祖大慈大悲，指出禪名，使人覺悟，如東禪、西禪、南禪、北禪、圓通禪、廣佛禪、圓學禪、真佛禪、無位禪、如來禪、祖師禪、大方禪、城市禪、脚跟禪、龍女禪、蚌殻禪、老婆禪、新婦子禪、一味禪、指頭禪、皮可漏子禪、口鼓子禪、琉璃瓶子禪，千名百樣，惟要世人早自見性。", "py": []}, {"t": "今世衲僧，以順寂入涅槃爲終世過化之奬辭，是爲明眼所嗤，寧不惶愧？彼安得知涅槃之際，是衲僧脚跟下求向上之事也？又稱僧名，唯求下字，何乃諱上而不諱下者乎？不認佛祖欲人見性，以下爲體，人却不知性是身中之物，廼以性爲見解智識，猶認靈臺以爲心地，不悟靈臺即是性也。", "py": []}, {"t": "世人孰肯若良遂者哉？良遂再見麻谷，眼下見性，瞞他不得，出謂衆曰：諸人知處，良遂總知；良遂知處，諸人不知。爲他諸人或出或入，向六根門頭，做盡顛倒，良遂故云總知。而良遂之所知者，乃真佛也，諸人難識得真佛，所以云良遂知處，諸人不知也。今爾諸人，遂知得否？時諸弟子罔知所措。", "py": []}, {"t": "上陽子曰：甚矣，性之易見也；信矣，人之難悟也。汝來，且道性命是汝自家底，吾已擘破面皮，爲汝說了，汝尚不知性爲何物，命爲何事。若不就你心上體認去，却只於語言文字裏話會，待將從舌頭譌了，有甚干涉？吾又再四與你呈露，無一肯認。", "py": []}, {"t": "若得掀倒禪床，則敗闕了。今復爲汝討條活路，做箇了也。夫此一事，不過是箇有爲法也。昔者神人商容，以有爲之法欲授老子，乃先示以柔弱之道，遂因吐舌，老子即悟曰：舌柔齒剛，此是有爲之法也。", "py": []}, {"t": "夫有爲之法者，須知甘露之門，掣電之機。故世尊云：夢幻泡影，如露如電，謂之有爲法也。而一切人聞甘露掣電之說，則謂露電是天上落來底，夢則以爲睡中所見，幻則以爲化凡易脆，泡則以爲水上浮漚，影則以爲相因而出，皆非者也。", "py": []}, {"t": "凡此皆是妄猜謬度，不向分内以求真實也。世尊是大聖人，豈肯空言閑論無益者哉？所說皆指實事，令人各自見性。其用意處，言近指遠，以大喻小，上士聞之，一言千悟；一切常人，任佛說到下梢，反以爲禪機之語言也。", "py": []}, {"t": "爾時衆中，忽有一弟子，若脫了桶底子相似，豁然大悟，眼下見性，驚喜過望，即前伏地稽首而言：師慈憫開我愚迷，指以非佛之佛，而說非法之法，弟子萬劫千生，遭逢如是，群疑妄想，一切釋然，猶暗然炬，外内洞明，又如傍水觀影，上下俱見，真實而希有也。上陽子知其根器不淺，乃曰：來，汝所悟者，是汝性也。汝性非性，汝心非心，心即是心，性即是性，性非汝心，心非汝性。", "py": []}, {"t": "汝試爲我言汝實性。應時答言：弟子鄙見，性即云性，心即云心，心無所心，性無所性，性亦非心，心亦非性，性非心心，心非性性，性性非心心，心非性性，無有心心，無有性性，本無心，心本無性，性則言性，心則言心，心若有性，即非佛心；性若有心，是名佛性。佛性我性，是真實性；我心佛心，是妄想心。心若妄想，即不見佛；性若真實，即是真佛。更乞我師慈悲，開顯真實妙義。", "py": []}, {"t": "上陽子曰：汝於佛法，惟只八成，吾今告汝，兩下圓滿。名何云心？有肉團心，有虚空心。此虚空心，是名何心？是金剛心，是涅槃心。彼肉團心，復名何心？是妄想心，是煩惱心。世人思慮，總皆執著，故是爲障碍心。有障碍，因縁不來，因此無縁，輪迴生死。", "py": []}, {"t": "若金剛心，若涅槃心，是虚空心。此虚空心，即智慧心，即真實心。上士一聞，發大智慧，勇猛精進，是云真佛。此真佛心，是堅固心，是成就心，是圓滿心，是真佛心，是真人心。此一切心，歷劫不壞；彼一切心，爭愛貪著，見色迷戀，聞聲驚怖，是非分别，無有窮已。", "py": []}, {"t": "此一切心，凡所見聞，如如不動；霹靂大震，如如不動，況彼聲色，豈能動摇？生死岸頭，如如不動，況彼水火，豈能焚漂？如金剛劎，有大精進；如百尺竿，直而不屈，盡世甲兵，無能摧折。此精進心，有大勇猛，諸天及人，見此精進，歡喜無量。假此精進，成佛作祖。云何名佛？是虚空心。云何虚空而名真佛？此虚空心，懸崖壁立，智慧精進，倏爾變通。因爾虚空，前無所進，後無所退，執著不得，思議不及，是云真佛，亦云法身。", "py": []}, {"t": "縁此法身，住虚空中，得大解脫，得大自在，遍十方界，廣大神通，故云南無十方虚空常住三寳。離此三寳，無有法身；離此法身，即不明了。此法身外，更覓何心？更覓何性？若有所覓，即不見性。爲不見性，肉團心起，六賊煩擾，世以此故，猶夢中夢，無有了期。", "py": []}, {"t": "唯覺是了，真佛之心，常如夢覺，智慧靈明，無有顛倒。大修行人以此爲悟，悟無不了，悟即進修。若大智慧心，即云佛；若大了悟，佛即云心；若大解脫，非心非佛；若大因縁，即心即佛。此心即性，此性即佛，性佛不離，佛性明了。", "py": []}, {"t": "上陽子曰：性由自悟，命待師傳。演禪師云：悟了須是遇人。悟了若不遇人，十箇有五雙杜撰子。不聞廬惠能者乎？惠能是新州樵夫，年已半百，聞客誦經，頓見佛性，致母出郷，遠叩黄梅。五祖纔見，數語投機，使役碓舂，經八箇月，因聞秀偈，始露錐鋒，大滿授之衣鉢，佛法能得指歸。", "py": []}, {"t": "又無法財，乃得神會足之，又得劉志畧爲之外護，遂隱于四會縣獵人之中，而下工焉。性命雙修，以土制鉛，以鉛制汞，二歸金鼎，却入深山，兀坐修養，道成之後，潜抵番禺，吐風幡之語，以顯神通，爲大宗師，是與達磨出處同風。", "py": []}, {"t": "弟子問曰：黄梅數百餘人，其中豈無一人可授佛法，何乃直待惠能至而授之？五祖乃若是乎？曰：五祖何幸，早得人傳。若說是事，豈唯數百人中而無一人？昔者世尊靈山會上，五千退席，且無一人。爾道方今之時，四海之廣，其真得佛法者，復有幾人焉？是之謂希有者也。弟子思之，再拜伏諾。", "py": []}, {"t": "上陽子曰：今時修行的人，安知得傳之後，無量艱苦，方能就事？其所云苦，與世不同：彼所謂樂，此以爲懼；此以爲得，彼反謂失。若人於此下箇柱脚，是敢保他有落著處，是知神氣一用，性命雙修者也。", "py": []}, {"t": "若只見性爲是，則大鑒何必往黄梅？永嘉何用往曹溪乎？是以我師趙真人曰：坐禪入定，一件在得牟尼之珠、聖胎已成之後，謂之抱一守和、知白守黑也，謂之面壁端坐、修禪入定也，謂之鍊形化氣、鍊氣歸神也，是名形神出胎，親爲佛子已上事也。", "py": []}, {"t": "故《玉皇集經》云：頓悟大乘正宗，漸入虚無妙道。大乘之道，即今金丹之道也。所以達磨有云：見此東土赤縣神州，有大乘氣象，成佛無礙，是載巨舟，實以衆寳，三周寒暑，來求大乘之道。是知達磨，始則見性得法而來，終則得丹成佛而西歸，是之謂直指人心、見性成佛者。時諸弟子皆得解悟，再拜而退，信受奉行。", "py": []}, {"t": "上陽子金丹大要超宗卷之十六", "py": []}]}]};
